-- DSM-5-TR (curso="DSM-5-TR"), parte 3 de 3: 139 preguntas.
-- Ejecutar en Supabase (Dashboard -> SQL Editor -> New query -> Run). Las tres partes
-- son independientes y da igual el orden.
--
-- Fuente: "DSM-5-TR. Preguntas de autoevaluación. Exámenes tipo test sobre los
-- criterios diagnósticos" (Muskin y cols., Editorial Médica Panamericana),
-- Parte II "Guía de respuestas", que repite cada pregunta con su respuesta correcta,
-- su explicación y la referencia al DSM-5-TR. Transcrito por OCR de un escaneo y
-- generado por un script que valida cada fila antes de escribir (4 opciones,
-- correcta 0-3, enunciado acabado en ? : o ., sin restos de maquetación ni el
-- "punto + número suelto" de supabase-detectar-basura-preguntas.sql).
--
-- tema = el capítulo del libro. explicacion = la del libro + "Referencia: DSM-5-TR, ..."
-- con el apartado y la página del manual.
--
-- Se puede volver a ejecutar sin duplicar nada: cada fila solo entra si no hay ya
-- una pregunta DSM-5-TR con el mismo enunciado y las mismas opciones.
--
-- Capítulos de esta parte: Trastornos relacionados con sustancias y trastornos adictivos; Trastornos neurocognitivos; Trastornos de la personalidad; Trastornos parafílicos; Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos; Medidas de evaluación (Sección III del DSM-5-TR); Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR); Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR).

insert into public.preguntas (curso, tema, pregunta, opciones, correcta, explicacion, inventada)
select v.curso, v.tema, v.pregunta, v.opciones::jsonb, v.correcta, v.explicacion, false
from (values
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Los criterios diagnósticos del abuso de sustancias, la dependencia de sustancias, la intoxicación con sustancias y la abstinencia de sustancias no eran igualmente aplicables a todas las sustancias en el DSM-IV y se cambiaron en el DSM-5. Esto continúa así en el DSM-5-TR, donde el trastorno por consumo de sustancias reemplaza los diagnósticos del DSM-IV de abuso de sustancias y dependencia de sustancias. ¿Con respecto a cuál de las siguientes clases de sustancias hay evidencia suficiente como para respaldar los criterios diagnósticos del DSM-5 en las tres categorías principales de trastorno por consumo, intoxicación y abstinencia?', '["Cafeína.", "Cannabis.", "Tabaco.", "Alucinógeno."]', 1, 'La característica esencial de un trastorno por consumo de sustancias es un conjunto de síntomas cognitivos, conductuales y fisiológicos que indican que el individuo continúa utilizando la sustancia a pesar de haber problemas significativos relacionados con ella. Como se ve en la Tabla 1, "Diagnósticos asociados con la clase de sustancia" (p. 545), el diagnóstico de un trastorno por consumo de sustancias puede aplicarse a las 10 clases de sustancias incluidas en este capítulo, excepto la cafeína. Con respecto a ciertas clases, algunos síntomas son menos sobresalientes y, en algunos casos, no todos los síntomas se aplican (por ejemplo, no se especifican síntomas de abstinencia para el trastorno por consumo de fenciclidina, el otro trastorno por consumo de alucinógenos o el trastorno por consumo de inhalantes). Son frecuentes los signos fisiológicos marcados y en general fácilmente medibles de la abstinencia en el caso del alcohol, los opioides y los sedantes, hipnóticos y ansiolíticos. Los signos y síntomas de abstinencia de los estimulantes (sustancias de tipo anfetamínico, cocaína, otros estimulantes o estimulantes no especificados), así como los del tabaco y el cannabis, a menudo están presentes pero pueden ser menos obvios. No se ha documentado ninguna abstinencia significativa en los seres humanos después del uso repetido de fenciclidina, otros alucinógenos e inhalantes; por lo tanto, este criterio no se incluye en relación con estas sustancias. La abstinencia de cannabis y la abstinencia de cafeína están incluidas en el DSM-5-TR; sin embargo, solo el cannabis tiene suficiente evidencia como para respaldar las tres categorías de los trastornos relacionados con sustancias. Referencia: DSM-5-TR, Introducción al capítulo (pp. 543-544).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de los siguientes pares de drogas se clasifica en una sola clase en el DSM-5-TR?', '["Cocaína y fenciclidina (PCP).", "Cocaína y metilfenidato.", "3 4-metilendioximetanfetamina (MDMA [éxtasis]) y metanfetamina.", "Lorazepam y alcohol."]', 1, 'Los estimulantes tratados en este capítulo son la anfetamina, los estimulantes con receta de efectos similares (por ejemplo, metilfenidato) y la cocaína. Los trastornos relacionados con otras sustancias con propiedades estimulantes se clasifican en otros apartados de este capítulo. Estos son la cafeína (en los trastornos relacionados con la cafeína), la nicotina (en los trastornos relacionados con el tabaco) y el MDMA (en otros trastornos relacionados con alucinógenos), que tiene efectos tanto estimulantes como alucinógenos. Referencia: DSM-5-TR, Trastorno por consumo de estimulantes / Características diagnósticas (pp. 635-636).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de las siguientes afirmaciones sobre la tolerancia y la abstinencia es verdadera en el diagnóstico del trastorno por consumo de sustancias del DSM-5-TR?', '["La tolerancia y la abstinencia ya no se consideran síntomas diagnósticos válidos del trastorno por consumo de sustancias.", "Las definiciones de tolerancia y abstinencia se han actualizado porque las definiciones anteriores tenían una fiabilidad interevaluador escasa.", "La presencia de tolerancia o abstinencia ahora es necesaria para hacer un diagnóstico de trastorno por consumo de sustancias para algunas, pero no todas, clases de sustancias.", "La tolerancia y la abstinencia aún se enumeran como criterios, pero si ocurren durante un tratamiento médico correctamente supervisado, no cuentan para el diagnóstico de trastorno por consumo de sustancias."]', 3, 'Los síntomas de tolerancia y abstinencia que ocurren durante el uso adecuado de medicamentos recetados como parte de un tratamiento médico (por ejemplo, analgésicos opioides, sedantes, estimulantes) no cuentan para diagnosticar un trastorno por consumo de sustancias. La aparición de una tolerancia farmacológica normal y esperada y de una abstinencia durante el curso del tratamiento médico se sabe que lleva a un diagnóstico erróneo de adicción incluso cuando se trata de los Únicos síntomas presentes. Las personas cuyos únicos síntomas son los que ocurren como resultado del tratamiento médico (es decir, tolerancia y abstinencia como parte de la atención médica cuando se toman los medicamentos según lo prescrito) no deben recibir un diagnóstico únicamente según estos síntomas. Referencia: DSM-5-TR, Introducción al capítulo; Trastornos por consumo de sustancias / Características diagnósticas (p. 547).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de las siguientes opciones diferencia el trastorno por consumo de alcohol de los otros trastornos relacionados con el alcohol?', '["El trastorno por consumo de alcohol implica un deterioro del control sobre el consumo de alcohol.", "El trastorno por consumo de alcohol requiere consumir una alta cantidad de alcohol.", "El trastorno por consumo de alcohol es una entidad intratable.", "La mayoría de las personas que consumen dosis altas de alcohol desarrollan el trastorno."]', 0, 'El trastorno por consumo de alcohol a menudo se percibe erróneamente como una afección intratable, quizás por el hecho de que las personas que se presentan para recibir tratamiento suelen tener una historia de muchos años de problemas graves relacionados con el alcohol. Sin embargo, estos casos más graves representan solo una minoría de personas con este trastorno y la persona típica con el trastorno tiene un pronóstico mucho más prometedor. El elemento clave del trastorno por consumo de alcohol es el uso de dosis altas de alcohol con el consiguiente estrés repetido y significativo o deterioro del funcionamiento. Aunque la mayoría de los bebedores a veces consumen suficiente alcohol como para sentirse intoxicados, solo una minoría (<20%) llegan a desarrollar un trastorno por consumo de alcohol. Por lo tanto, beber incluso a diario dosis bajas y tener una intoxicación ocasional no hacen por sí solas este diagnóstico. El trastorno por consumo de alcohol se diferencia de la intoxicación con alcohol, la abstinencia de alcohol y los trastornos mentales inducidos por alcohol (por ejemplo, trastorno depresivo inducido por alcohol) en que el trastorno por consumo de alcohol describe un patrón problemático de uso del alcohol que implica deterioro del control sobre dicho uso del alcohol, deterioro social debido al consumo de alcohol, consumo de riesgo de alcohol (por ejemplo, conducir mientras se está intoxicado) y síntomas farmacológicos (el desarrollo de tolerancia o abstinencia), mientras que la intoxicación con alcohol, la abstinencia de alcohol y los trastornos mentales inducidos por alcohol describen síndromes psiquiátricos que se desarrollan en el contexto de un consumo excesivo. La intoxicación con alcohol, la abstinencia de alcohol y los trastornos mentales inducidos por alcohol ocurren con frecuencia en personas con trastorno por consumo de alcohol. En tales casos se debe dar un diagnóstico de intoxicación con alcohol, abstinencia de alcohol o trastorno mental inducido por alcohol además del diagnóstico de trastorno por consumo de alcohol, cuya presencia se indica en el código de diagnóstico. Referencia: DSM-5-TR, Trastorno por consumo de alcohol / Desarrollo y curso (pp. 556-557); Diagnóstico diferencial (pp. 560-561).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de los siguientes no es un trastorno relacionado con el alcohol reconocido en el DSM-5-TR?', '["Dependencia del alcohol.", "Trastorno por consumo de alcohol.", "Intoxicación con alcohol.", "Abstinencia de alcohol."]', 0, 'Los trastornos relacionados con el alcohol son el trastorno por consumo de alcohol, la intoxicación con alcohol, la abstinencia de alcohol y los trastornos mentales inducidos por alcohol. Los siguientes trastornos mentales inducidos por alcohol se describen en otros capítulos del DSM-5-TR junto a los trastornos con los que comparten fenomenología (véanse los trastornos mentales inducidos por sustancias/medicamentos en estos capítulos): trastorno psicótico inducido por alcohol ("Espectro de la esquizofrenia y otros trastornos psicóticos"); trastorno bipolar y trastornos relacionados inducidos por alcohol ("Trastorno bipolar y trastornos relacionados"); trastorno depresivo inducido por alcohol ("Trastornos depresivos"); trastorno de ansiedad inducido por alcohol ("Trastornos de ansiedad"; trastorno del sueño inducido por alcohol ("Trastornos del sueño-vigilia"); disfunción sexual inducida por alcohol ("Disfunciones sexuales"), y trastorno neurocognitivo mayor o leve inducido por alcohol ("Trastornos neurocognitivos"). Referencia: DSM-5-TR, Trastornos relacionados con el alcohol / Trastornos mentales inducidos por el alcohol (pp. 567-568).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de las siguientes afirmaciones es correcta sobre el diagnóstico de un trastorno relacionado con la cafeína?', '["El individuo debe ser consciente de consumir cafeína.", "Para diagnosticar la intoxicación por cafeína, la cantidad consumida debe superar los 200 mg.", "El diagnóstico de abstinencia de cafeína requiere el consumo previo de cafeína a diario.", "La abstinencia de cafeína puede diagnosticarse incluso en ausencia de malestar clínicamente significativo o deterioro en las áreas sociales, ocupacionales u otras áreas importantes de funcionamiento."]', 2, 'La característica esencial de la intoxicación por cafeína es el consumo reciente de cafeína y cinco o más signos o síntomas que se desarrollan durante o poco después del consumo de cafeína (Criterios A y B). Los síntomas incluyen inquietud, nerviosismo, excitación, insomnio, rostro enrojecido, diuresis y quejas gastrointestinales, que pueden ocurrir con dosis bajas (por ejemplo, 200 mg) en individuos vulnerables como los niños, los ancianos o los individuos que no han estado expuestos a la cafeína previamente. La cafeína puede consumirse de diferentes fuentes, incluyendo café, té, refrescos con cafeína, bebidas "energéticas", analgésicos de venta libre y remedios para el resfriado, ayudas para la pérdida de peso y chocolate. La cafeína también se utiliza cada vez más como aditivo en vitaminas y productos alimenticios. Más del 85% de los adultos y niños de Estados Unidos consumen regularmente cafeína, ingiriendo los consumidores adultos de cafeína alrededor de 280 mg/día de media. La incidencia y la prevalencia del síndrome de abstinencia de cafeína en la población general no están claras. La característica esencial de la abstinencia de cafeína es la presencia de un síndrome de abstinencia característico que se desarrolla después de la interrupción abrupta (o la reducción sustancial) de la ingesta diaria prolongada de cafeína (Criterio B). Debido a que pueden no ser conscientes de la amplia variedad de fuentes de cafeína aparte del café, las colas y las bebidas energéticas (por ejemplo, analgésicos de venta libre y remedios para el resfriado, ayudas para la pérdida de peso, chocolate), muchas personas pueden no conectar la ingesta de estas sustancias con los síntomas de abstinencia de la cafeína. El síndrome de abstinencia de cafeína se indica por tres o más de los siguientes síntomas (Criterio B): dolor de cabeza; fatiga marcada o somnolencia; estado de ánimo disfórico, estado de ánimo depresivo o irritabilidad; dificultad para concentrarse, y síntomas similares a los de la gripe (náuseas, vómitos o dolor/rigidez muscular). El síndrome de abstinencia causa malestar clínicamente significativo o deterioro en las áreas sociales, ocupacionales u otras áreas importantes de funcionamiento (Criterio C). Referencia: DSM-5-TR, Trastornos relacionados con la cafeína (pp. 569-574).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de los siguientes síntomas es más común en las mujeres que en los hombres como consecuencia de la interrupción abrupta del uso diario o casi diario de cannabis?', '["Síntomas de abstinencia menos graves.", "Suicidio.", "Hambre.", "Irritabilidad."]', 3, 'Los síntomas comunes de la abstinencia de cannabis incluyen irritabilidad, estado de ánimo deprimido, ansiedad, inquietud, dificultad para dormir y disminución del apetito o pérdida de peso. Comparadas con los hombres, las mujeres refieren síntomas de abstinencia de cannabis más marcados, especialmente síntomas anímicos como irritabilidad, inquietud y enfado, y síntomas gastrointestinales como dolor de estómago y náuseas, lo que puede contribuir a un posible efecto telescópico (transición más rápida desde el primer consumo de cannabis al trastorno por consumo de cannabis). En particular, los hombres con trastorno por consumo de cannabis tienen una tasa de suicidios de 79 por 100.000 personas-año y las mujeres con trastorno por consumo de cannabis tienen una tasa de suicidios de 47 por 100.000 personas-año. Referencia: DSM-5-TR, Abstinencia de cannabis (pp. 584-586).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de los siguientes no es un síntoma reconocido asociado con el consumo de alucinógenos?', '["Abstinencia.", "Tolerancia.", "Deseo persistente o intentos infructuosos de reducir o controlar el consumo de la sustancia.", "Consumo recurrente de la sustancia en situaciones en las que es físicamente peligroso."]', 0, 'La característica esencial de un trastorno por consumo de sustancias es un conjunto de síntomas cognitivos, conductuales y fisiológicos que indican que el individuo continúa usando la sustancia a pesar de haber problemas significativos relacionados con la sustancia. En ciertas clases, algunos síntomas son menos sobresalientes y en algunos casos no todos los síntomas se aplican (por ejemplo, no se especifican síntomas de abstinencia para el trastorno por consumo de fenciclidina, el otro trastorno por consumo de alucinógenos o el trastorno por consumo de inhalantes). La abstinencia (Criterio A11) es un síndrome que se produce cuando las concentraciones de una sustancia en la sangre o en los tejidos disminuyen en un individuo que ha mantenido un uso prolongado y masivo de dicha sustancia. Después de desarrollar síntomas de abstinencia, es probable que el individuo consuma la sustancia para aliviarlos. Los síntomas de abstinencia varían enormemente entre las distintas clases de sustancias, y el DSM-5-TR proporciona conjuntos de criterios separados para la abstinencia de las distintas clases de drogas. Los signos fisiológicos marcados y generalmente fácilmente medibles de la abstinencia son comunes con el alcohol, los opioides y los sedantes, hipnóticos y ansiolíticos. Los signos y síntomas de abstinencia de los estimulantes (sustancias de tipo anfetamínico, cocaína, otros estimulantes o estimulantes no especificados), así como los del tabaco y el cannabis, a menudo están presentes pero pueden ser menos obvios. No se ha documentado una abstinencia significativa en los seres humanos después del consumo repetido de fenciclidina, otros alucinógenos e inhalantes; por lo tanto, este criterio no se incluye en estas sustancias. Referencia: DSM-5-TR, Trastornos por consumo de sustancias / Características diagnósticas (pp. 544-547).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Para poder cumplir los criterios propuestos para el trastorno neurocomportamental asociado con la exposición prenatal al alcohol, la exposición prenatal al alcohol del individuo debe haber sido "más que mínima". ¿Cómo se define la exposición "más que mínima" en términos de cantidad de alcohol consumido por la madre durante la gestación?', '["Cualquier exposición al alcohol durante el embarazo.", "Menos de 10 bebidas al mes y no más de una bebida por ocasión de consumo.", "Menos de 7 bebidas al mes y no más de tres bebidas por ocasión de consumo.", "Menos de 13 bebidas al mes y no más de dos bebidas por ocasión de consumo."]', 3, 'El diagnóstico clínico del síndrome alcohólico fetal, que incluye una dismorfología facial específica relacionada con el alcohol prenatal y un retraso del crecimiento, puede utilizarse como evidencia de niveles significativos de exposición prenatal al alcohol; se han desarrollado pautas específicas para la dismorfología facial en diversas fisonomías etnorraciales. Aunque tanto los estudios en animales como los de seres humanos han documentado los efectos adversos de los niveles bajos de consumo de alcohol, identificar cuánta exposición prenatal es necesaria para afectar significativamente al neurodesarrollo sigue siendo un reto. Los datos sugieren que podría ser necesaria una historia de exposición gestacional más que mínima antes del reconocimiento del embarazo y/o después del reconocimiento del embarazo. La exposición más que mínima se define como más de 13 bebidas al mes durante el embarazo o más de dos bebidas en una sola ocasión. Identificar un umbral mínimo de consumo de alcohol durante el embarazo requerirá la consideración de diversos factores conocidos por afectar a la exposición y/o interactuar para influir en los resultados del desarrollo, como la etapa de desarrollo prenatal, el tabaquismo gestacional, la genética materna y fetal, y el estado físico materno (es decir, edad, salud y ciertos problemas obstétricos). Referencia: DSM-5-TR, Afecciones que necesitan más estudio / Trastorno neurocomportamental asociado con la exposición prenatal al alcohol / Criterios propuestos / Características diagnósticas (pp. 916-918).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de los siguientes es el único trastorno no relacionado con sustancias que se incluye en el capítulo del DSM-5-TR "Trastornos relacionados con sustancias y trastornos adictivos"?', '["Trastorno de juego.", "Trastorno de juego en Internet.", "Trastorno de adicción a la comunicación electrónica.", "Trastorno de uso compulsivo de la computadora."]', 0, 'Además de los trastornos relacionados con sustancias, este capítulo también incluye el trastorno de juego, lo que refleja datos objetivos de que los comportamientos de juego activan sistemas de recompensa similares a los activados por las drogas de abuso y producen algunos síntomas conductuales que parecen comparables a los producidos por los trastornos por consumo de sustancias. Referencia: DSM-5-TR, Introducción al capítulo (p. 543).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'En la mayoría de los trastornos mentales inducidos por sustancias/medicamentos (con la excepción del trastorno neurocognitivo mayor o leve inducido por sustancias/medicamentos y el trastorno de percepción persistente por alucinógenos), si la persona se abstiene de consumir sustancias, el trastorno finalmente desaparecerá o ya no será clínicamente relevante incluso sin tratamiento formal. ¿En qué plazo es probable que esto suceda?', '["1 hora.", "1 mes.", "3 meses.", "1 año."]', 1, 'La mayoría de los trastornos mentales inducidos por sustancias/medicamentos, independientemente de la gravedad de los síntomas, es probable que mejoren relativamente rápido con la abstinencia y es poco probable que sigan siendo clínicamente relevantes más de 1 mes después de cesar completamente su uso. Referencia: DSM-5-TR, Introducción al capítulo; Trastornos inducidos por sustancias / Trastornos mentales inducidos por sustancias / medicamentos / Desarrollo y curso (pp. 551-552).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Dado que la abstinencia de opioides y la abstinencia de sedantes, hipnóticos o ansiolíticos pueden cursar con síntomas muy similares, distinguirlos puede ser difícil. ¿Cuál de los siguientes síntomas presentes ayudaría a diferenciar la abstinencia de opioides de la abstinencia de sedantes, hipnóticos o ansiolíticos?', '["Náuseas o vómitos.", "Ansiedad.", "Bostezo.", "Inquietud o agitación."]', 2, 'La ansiedad y la inquietud asociadas con la abstinencia de opioides se asemejan a los síntomas observados en la abstinencia de sedantes-hipnóticos; sin embargo, la abstinencia de opioides también va acompañada de rinorrea, lagrimeo y dilatación pupilar, que no se observan en la abstinencia de tipo sedante. Las pupilas dilatadas también se observan en la intoxicación por alucinógenos y la intoxicación por estimulantes; sin embargo, otros signos o síntomas de la abstinencia de opioides, como náuseas, vómitos, diarrea, cólicos abdominales, rinorrea o lagrimeo, no están presentes. Referencia: DSM-5-TR, Trastorno por consumo de opioides / Diagnóstico diferencial (pp. 614-615); Abstinencia de opioides / Criterios diagnósticos (pp. 617-618).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'En el DSM-5-TR, la clase de sedantes, hipnóticos o ansiolíticos contiene todos los medicamentos recetados para dormir y casi todos los medicamentos recetados para la ansiedad. ¿Cuál es la razón por la que los agentes antiansiedad no benzodiacepínicos (por ejemplo, buspirona, gepirona) no están incluidos en esta clase?', '["Generalmente no están disponibles en formulaciones no parenterales (intravenosas o intramusculares).", "No parecen asociarse a un uso indebido significativo.", "No están asociados con la fabricación ilícita o la desviación (por ejemplo, drogas de la Lista II-V en Estados Unidos, lista de sustancias psicotrópicas reconocidas por la Junta Internacional de Control de Narcóticos y las Naciones Unidas).", "No son depresores respiratorios."]', 1, 'Las sustancias sedantes, hipnóticas o ansiolíticas incluyen benzodiacepinas, fármacos similares a las benzodiacepinas (por ejemplo, zolpidem, zaleplon), carbamatos (por ejemplo, glutetimida, meprobamato), barbitúricos (por ejemplo, secobarbital) e hipnóticos similares a los barbitúricos (por ejemplo, glutetimida, metacualona, propofol). Esta clase de sustancias comprende la mayoría de los medicamentos recetados para dormir y la mayoría de los medicamentos recetados para la ansiedad. Los agentes antiansiedad no benzodiacepínicos (por ejemplo, buspirona, gepirona) no están incluidos en esta clase porque no parecen asociarse a un uso indebido significativo. Referencia: DSM-5-TR, Trastorno por consumo de sedantes, hipnóticos o ansiolíticos / Características diagnósticas (p. 622).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de los siguientes criterios no fue uno de los criterios del abuso de sustancias o la dependencia de sustancias en el DSM-IV, pero se incluyó en el DSM-5 y continúa en el DSM-5-TR?', '["Se abandonan o se reducen las actividades sociales, laborales o recreativas importantes debido al consumo de sustancias.", "La sustancia se toma a menudo en cantidades mayores o durante un período más largo de lo que se pretendía.", "Hay anhelo, ansia o impulso de consumir la sustancia.", "El consumo recurrente de sustancias lleva a no poder cumplir las obligaciones principales en el trabajo, la escuela o el hogar."]', 2, 'En general, el diagnóstico de un trastorno por consumo de sustancias se basa en un patrón patológico de comportamientos relacionados con el uso de la sustancia. Para facilitar la organización, los elementos diagnósticos que componen el Criterio A pueden considerarse dentro de los grupos generales de control deteriorado, deterioro social, consumo de riesgo y criterios farmacológicos. El deterioro del control sobre el uso de sustancias forma el primer grupo de criterios (Criterios A1-A4). La persona puede tomar la sustancia en cantidades mayores o durante un período más largo de lo que inicialmente se pretendía (Criterio A1). La persona puede expresar el deseo persistente de reducir o regular el uso de sustancias y puede referir múltiples intentos infructuosos de disminuir o interrumpir el consumo (Criterio A2). La persona puede pasar mucho tiempo buscando la sustancia, utilizando la sustancia o recuperándose de sus efectos (Criterio A3). En algunos de los casos más graves de trastornos por consumo de sustancias, prácticamente todas las actividades diarias de la persona giran en torno a la sustancia. El anhelo (Criterio A4) se manifiesta por un intenso deseo o impulso de tomar la droga que puede ocurrir en cualquier momento, aunque es más probable que se dé cuando la persona se encuentra en un ambiente donde anteriormente obtenía o consumía la droga. Se ha demostrado que el anhelo también implica un condicionamiento clásico y está asociado con la activación de estructuras de recompensa específicas en el cerebro. El anhelo puede sonsacarse preguntando si ha habido alguna vez un momento en el que hubo impulsos tan fuertes de tomar la droga que la persona no podía pensar en otra cosa. El anhelo actual a menudo se utiliza como medida del resultado del tratamiento, ya que puede ser señal de recaída inminente. Referencia: DSM-5-TR, Introducción al capítulo; Trastornos por consumo de sustancias / Características diagnósticas (pp. 545-546).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Una mujer de 27 años se presenta para una evaluación psiquiátrica después de casi atropellar a alguien con su coche mientras conducía bajo los efectos de la marihuana. Informa que su marido la instó a buscar tratamiento. Él le ha dicho que su consumo contino de marihuana supone una gran tensión en el matrimonio; sin embargo, ella continúa fumando dos porros al día y conduciendo bajo los efectos de la marihuana. ¿Cuál es el diagnóstico apropiado?', '["Abuso de cannabis.", "Dependencia del cannabis.", "Intoxicación por cannabis.", "Trastorno por consumo de cannabis."]', 3, 'El trastorno por consumo de cannabis se define por los mismos 11 criterios que definen los otros trastornos por consumo de sustancias, respaldados por una considerable evidencia empírica. El conjunto de síntomas conductuales y físicos que componen estos criterios conduce a deterioro o malestar clínicamente significativos y puede incluir abstinencia, tolerancia, anhelo, dedicar mucho tiempo a actividades relacionadas con la sustancia y consumo peligroso (por ejemplo, conducir bajo su influencia). Referencia: DSM-5-TR, Trastorno por consumo de cannabis / Características diagnósticas (p. 576-577).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Un hombre de 35 años con una larga historia de consumo excesivo de alcohol es referido a una evaluación psiquiátrica después de su reciente ingreso en el hospital por hepatitis aguda. El paciente informa que bebía 2-3 copas diarias en la universidad. Durante los últimos 10 años ha aumentado gradualmente su ingesta nocturna de alcohol de un solo paquete de seis a dos paquetes de 12 cervezas. A menudo se queda dormido y no llega al trabajo. Ha intentado moderar su consumo de alcohol en numerosas ocasiones con poco éxito, especialmente después de desarrollar complicaciones asociadas a la cirrosis alcohólica. El paciente admite que se pone ansioso y le tiemblan las manos cuando no bebe. ¿De cuál de los siguientes diagnósticos cumple los criterios este paciente?', '["Abuso de alcohol.", "Dependencia del alcohol.", "Trastorno por consumo de alcohol, grave.", "Trastorno por consumo de alcohol, moderado."]', 2, 'El trastorno por consumo de alcohol se define por un conjunto de síntomas conductuales y físicos, como la abstinencia, la tolerancia y el anhelo. La abstinencia de alcohol se caracteriza por síntomas de abstinencia que se desarrollan aproximadamente 4-12 horas después de reducir la dosis tras una ingesta prolongada y masiva de alcohol. Debido a que la abstinencia de alcohol puede ser desagradable e intensa, los individuos pueden continuar consumiendo alcohol a pesar de las consecuencias adversas, a menudo para evitar o aliviar los síntomas de abstinencia. Algunos síntomas de abstinencia (por ejemplo, problemas de sueño) pueden persistir a intensidades más bajas durante meses y contribuir a la recaída. Una vez que se desarrolla un patrón de uso repetitivo e intenso, las personas con trastorno por consumo de alcohol pueden dedicar períodos sustanciales de su tiempo a obtener y consumir bebidas alcohólicas. La gravedad del trastorno se basa en el número de criterios diagnósticos cumplidos. En un individuo dado, los cambios de la gravedad del trastorno por consumo de alcohol a lo largo del tiempo también se reflejan en las reducciones de la frecuencia (por ejemplo, días de consumo al mes) o la dosis (por ejemplo, número de bebidas estándar al día) de alcohol consumidas, según lo evaluado por el autoinforme del individuo, el informe de terceros que lo conocen, las observaciones del clínico y, si procede, las pruebas biológicas (por ejemplo, elevaciones de parámetros hematoséricos, como se describe en el apartado "Marcadores diagnósticos" de este trastorno). Referencia: DSM-5-TR, Trastorno por consumo de alcohol / Características diagnósticas (p. 555); Especificadores (p. 555).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de las siguientes es la afirmación más precisa sobre la predicción de la abstinencia del alcohol o sus consecuencias?', '["Menos del 10% de las personas que pasan por la abstinencia de alcohol experimentan síntomas dramáticos como hiperactividad autonómica grave, temblores o delirium tremens.", "Todos los síntomas de la abstinencia de alcohol cesan después de 7 días.", "La abstinencia de alcohol varía ampliamente entre los grupos etnorraciales de Estados Unidos.", "Las convulsiones tónico-clónicas ocurren en aproximadamente el 25% de las personas que cumplen los criterios de la abstinencia de alcohol."]', 0, 'La abstinencia de alcohol se caracteriza por síntomas de abstinencia que se desarrollan aproximadamente 4-12 horas después de reducir la cantidad ingerida tras una ingesta prolongada y masiva de alcohol. Debido a que la abstinencia de alcohol puede ser desagradable e intensa, los individuos pueden continuar consumiendo alcohol a pesar de las consecuencias adversas, a menudo para evitar o aliviar los síntomas de abstinencia. Algunos síntomas de abstinencia (por ejemplo, problemas de sueño) pueden persistir a intensidades más bajas durante meses y contribuir a la recaída. Menos del 10% de las personas que desarrollan abstinencia de alcohol experimentarán síntomas dramáticos (por ejemplo, hiperactividad autonómica grave, temblores, delirium tremens). Las convulsiones tónico-clónicas ocurren en menos del 3% de las personas. Se estima que aproximadamente el 50% de las personas de clase media y altamente funcionales con trastorno por consumo de alcohol en Estados Unidos han experimentado alguna vez un síndrome de abstinencia de alcohol completo. Entre las personas con trastorno por consumo de alcohol que están hospitalizadas o sin hogar, la tasa de abstinencia de alcohol puede ser mayor del 80%. Menos del 10% de las personas en abstinencia presentan delirium tremens o convulsiones por abstinencia. La prevalencia de los síntomas de abstinencia de alcohol no parece variar entre los grupos etnorraciales de Estados Unidos. Referencia: DSM-5-TR, Trastorno por consumo de alcohol / Características diagnósticas (p. 555); Prevalencia (p. 556); Abstinencia de alcohol / Criterios diagnósticos (p. 553-554).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuántos especificadores de remisión se incluyen en los criterios diagnósticos del DSM-5-TR para el trastorno por consumo de alcohol?', '["Uno.", "Dos.", "Tres.", "Cuatro."]', 1, 'Hay dos especificadores de remisión: * En remisión temprana: después de haberse cumplido todos los criterios del trastorno por consumo de alcohol, ninguno de los criterios del trastorno por consumo de alcohol se ha cumplido en al menos 3 meses pero menos de 12 meses (con la excepción de que el Criterio A4, "anhelo, ansia o impulso de consumir alcohol", sí puede cumplirse). * En remisión sostenida: después de haberse cumplido todos los criterios del trastorno por consumo de alcohol, ninguno de los criterios del trastorno por consumo de alcohol se ha cumplido en ningún momento en un período de 12 meses o más (con la excepción de que el Criterio A4, "anhelo, ansia o impulso de consumir alcohol", sí puede cumplirse). Referencia: DSM-5-TR, Trastorno por consumo de alcohol / Criterios diagnósticos (pp. 553-554).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿En cuál de las siguientes situaciones se consideraría que el especificador para un paciente en remisión es "en un entorno controlado"?', '["Alistado en las fuerzas armadas de Estados Unidos.", "Trabaja en un barco de carga en alta mar.", "Recluído en una cárcel de la ciudad.", "Paciente interno en una unidad hospitalaria cerrada."]', 3, 'En un entorno controlado se aplica como especificador adicional de remisión si el individuo está tanto en remisión como en un entorno controlado (es decir, en remisión temprana en un entorno controlado o en remisión sostenida en un entorno controlado). Ejemplos de estos entornos son las prisiones, las comunidades terapéuticas y las unidades hospitalarias cerradas que están estrechamente supervisadas y libres de sustancias. Referencia: DSM-5-TR, Trastorno por consumo de alcohol / Especificadores (p. 555).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de las siguientes sustancias es más probable que se asocie con el uso de múltiples drogas?', '["Alcohol.", "Tabaco.", "3, 4-metilendioximetanfetamina (MDMA [éxtasis]).", "Metanfetamina."]', 2, 'El trastorno por consumo de otros alucinógenos está altamente asociado con el trastorno por consumo de cocaína, el trastorno por consumo de estimulantes, el trastorno por consumo de otras sustancias, el trastorno por consumo de tabaco (nicotina), cualquier trastorno de la personalidad, el trastorno de estrés postraumático y los ataques de pánico. Referencia: DSM-5-TR, Trastorno por consumo de otros alucinógenos / Comorbilidad (p. 594).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Para cuál de las siguientes sustancias podría ser poco fiable la prueba de laboratorio?', '["Dietilamida del ácido lisérgico (LSD).", "Cocaína.", "Alcohol.", "Opioides."]', 0, 'Los alucinógenos comprenden un grupo diverso de sustancias que, a pesar de tener diferentes estructuras químicas y, posiblemente, diferentes mecanismos moleculares, producen alteraciones similares de la percepción, el estado de ánimo y la cognición en los usuarios. Los alucinógenos incluidos son las fenilalquilaminas (por ejemplo, mescalina, 2,5-dimetoxi-4-metilanfetamina [DOM] y 3,4-metilendioximetanfetamina [MDMA] también llamada éxtasis o molly]); las indolaminas, como la psilocibina (y su metabolito psilocina, el compuesto principalmente responsable de los efectos psicodélicos de los hongos alucinógenos) y la dimetiltriptamina (DMT), y las ergolinas, como el LSD y las semillas de gloria de la mañana. Además, se clasifican como alucinógenos otros compuestos etnobotánicos diversos, de los cuales Salvia divinorum y el estramonio son dos ejemplos. Las pruebas de laboratorio pueden ser útiles para distinguir entre los diferentes alucinógenos; sin embargo, debido a que algunos agentes (por ejemplo, el LSD) son tan potentes que con tan solo 75 mg pueden producir reacciones graves, el típico examen toxicológico no siempre revelará qué sustancia se ha utilizado. La fenciclidina puede detectarse en la orina hasta 8 días o incluso más tiempo a dosis muy altas. Los resultados de las pruebas toxicológicas rutinarias de orina suelen ser positivos para las drogas opioides en los individuos con trastorno por consumo de opioides. Los resultados de las pruebas de orina permanecen positivos para la mayoría de los opioides (por ejemplo, heroína, morfina, codeína, oxicodona, propoxifeno) durante 12-36 horas después de la administración. Casi todas las sustancias sedantes, hipnóticas y ansiolíticas pueden identificarse mediante análisis de orina o sangre (estos últimos pueden cuantificar las cantidades de estos agentes en el cuerpo). Los resultados de las pruebas de orina probablemente seguirán siendo positivos hasta aproximadamente 1 semana después del consumo de las sustancias de acción prolongada como el diazepam o el flurazepam. La benzoilecgonina, un metabolito de la cocaína, normalmente permanece en la orina durante 1-3 días después de una sola dosis y puede estar presente durante 7-12 días en los individuos que consumen dosis altas repetidas. La prueba más directa disponible para medir el consumo de alcohol de manera transversal es la concentración de alcohol en sangre, que también puede utilizarse para juzgar la tolerancia al alcohol. Por ejemplo, un individuo con una concentración de 150 mg de etanol por decilitro (dL) de sangre que no muestra signos de intoxicación puede considerarse que ha adquirido al menos algún grado de tolerancia al alcohol. Con 200 mg/dL, la mayoría de los individuos no tolerantes demuestran una intoxicación marcada. En cuanto a las pruebas de laboratorio, un indicador de laboratorio sensible al consumo masivo es una elevación modesta o niveles altos-normales (> 35 unidades) de gamma-glutamiltransferasa (GGT). Este puede ser el único hallazgo de laboratorio. Al menos el 70% de los individuos con un nivel alto de GGT son grandes bebedores persistentes (es decir, consumen ocho o más bebidas diariamente de manera regular). Referencia: DSM-5-TR, Trastorno por consumo de alcohol / Marcadores diagnósticos (pp. 558-559); Trastorno por consumo de fenciclidina / Marcadores diagnósticos (p. 589); Trastorno por consumo de otros alucinógenos / Características diagnósticas (p. 592); Marcadores diagnósticos (p. 593); Trastorno por consumo de opioides / Marcadores diagnósticos (p. 612); Trastorno por consumo de sedantes, hipnóticos o ansiolíticos / Marcadores diagnósticos (p. 625); Trastorno por consumo de estimulantes / Marcadores diagnósticos (p. 638).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Qué signo del Criterio C tienen en común la intoxicación con alcohol, la intoxicación con fenciclidina, la intoxicación con cannabis y la intoxicación con inhalantes?', '["Reflejos deprimidos.", "Debilidad muscular generalizada.", "Nistagmo.", "Deterioro de la atención o la memoria."]', 2, 'El nistagmo es el único de estos signos que se encuentra en el Criterio C de la intoxicación con alcohol, cannabis, inhalantes o fenciclidina. Referencia: DSM-5-TR, Varios: Criterios diagnósticos de la intoxicación con alcohol (p. 561); Intoxicación con inhalantes (pp. 605-606); Cannabis (pp. 582-583); Intoxicación con fenciclidina (pp. 594-595).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Un estudiante de medicina de 25 años se presenta al servicio de salud del estudiante a las 7:00 quejándose de tener un "ataque de pánico" y de haber vomitado dos veces. Informa que se quedó despierto toda la noche estudiando para su examen final de anatomía descriptiva. El examen comienza en 1 hora, pero se siente demasiado ansioso para asistir. El paciente está inquieto y parece sonrojado, con contracciones musculares visibles. Está orinando excesivamente y tiene taquicardia, y su electrocardiograma muestra complejos ventriculares prematuros. Sus pensamientos y su discurso parecen ser divagantes. El análisis toxicológico de orina es negativo. ¿Cuál es el diagnóstico más probable?', '["Trastorno de pánico.", "Intoxicación con anfetamina, sustancia anfetamínica.", "Intoxicación por cafeína.", "Intoxicación con cocaína."]', 2, 'Este paciente muestra signos de inquietud, cara sonrojada, trastorno gastrointestinal, contracciones musculares, diuresis, habla divagante y anomalías cardíacas, todos los cuales son compatibles con la intoxicación por cafeína. Aunque un episodio de pánico podría asociarse a taquicardia o malestar gastrointestinal, no causaría contracciones musculares ni arritmias cardíacas. La intoxicación con estimulantes como la anfetamina o la cocaína se manifestaría de manera muy similar con agitación psicomotora y arritmias cardíacas, pero estas sustancias no causarían diuresis y se esperaría que aparecieran en un análisis toxicológico de orina. La abstinencia de alcohol también podría manifestarse de manera similar, pero generalmente se caracteriza por temblor, en lugar de contracciones musculares, y tampoco causa diuresis. Referencia: DSM-5-TR, Intoxicación por cafeína / Criterios diagnósticos; Características diagnósticas (pp. 569-570).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál es la sustancia psicoactiva ilícita más prevalente en Estados Unidos?', '["3 4-metilendioximetanfetamina (MDMA [éxtasis]).", "Fenciclidina.", "Cannabis.", "Dietilamida del ácido lisérgico (LSD)."]', 2, 'Los cannabinoides, especialmente el cannabis, son las sustancias psicoactivas ilícitas más utilizadas en Estados Unidos. Los siguientes datos de prevalencia se obtienen de los estudios basados en Estados Unidos, a menos que se indique lo contrario. Entre los jóvenes (de 12 a 17 años), la prevalencia en el último año del trastorno por consumo de cannabis del DSM-IV es del 2,7-3,1 %. Entre los adultos de 18 años en adelante, la prevalencia es del 1,5-2,9 %. Entre los usuarios de cannabis, la prevalencia del trastorno por consumo de cannabis del DSM-IV es del 20,4% entre los jóvenes y del 30,6 % entre los adultos. Para el trastorno por consumo de cannabis del DSM-5, la prevalencia a 12 meses es aproximadamente del 2,5% entre los adultos (1,4, 0,6 y 0,6% en los niveles leve, moderado y grave, respectivamente). Referencia: DSM-5-TR, Trastorno por consumo de cannabis / Prevalencia (p. 578).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de las siguientes pruebas de laboratorio se puede utilizar en combinación con la gamma-glutamiltransferasa (GGT) para monitorear la abstinencia de alcohol?', '["Alanina-aminotransferasa (ALT).", "Fosfatasa alcalina.", "Transferrina deficiente en carbohidratos (CDT).", "Volumen corpuscular medio (MCV)."]', 2, 'En cuanto a las pruebas de laboratorio, un indicador de laboratorio sensible del consumo excesivo de alcohol es la elevación modesta o los niveles altos-normales (> 35 unidades) de GGT. Este puede ser el único hallazgo de laboratorio. Al menos el 70% de los individuos con un alto nivel de GGT son grandes bebedores persistentes (es decir, consumen ocho o más bebidas diariamente de manera regular). Una segunda prueba con niveles comparables o incluso más altos de sensibilidad y especificidad es la CDT, siendo los niveles de 20 unidades o más útiles para identificar a los individuos que consumen regularmente ocho o más bebidas diarias. Dado que tanto los niveles de GGT como los de CDT vuelven a la normalidad en días o semanas después de dejar de beber, ambos marcadores de estado pueden ser útiles para monitorear la abstinencia, especialmente cuando el clínico observa aumentos, en lugar de disminuciones, de estos valores a lo largo del tiempo, hallazgo que indica que el individuo probablemente ha vuelto a beber mucho. La combinación de los análisis de CDT y GGT puede tener incluso niveles más altos de sensibilidad y especificidad que cualquiera de estas pruebas por separado. Referencia: DSM-5-TR, Trastorno por consumo de alcohol / Marcadores diagnósticos (p. 559).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Un paciente acude a la clínica de salud estudiantil después de 1 semana bebiendo varias latas de cola ocho veces al día durante 1 semana para cumplir una apuesta que perdió. La última la consumió ayer. El paciente se queja de la aparición repentina de fatiga extrema. ¿Con cuál de los siguientes síntomas es más probable que se presente?', '["Vómitos.", "Somnolencia.", "Síntomas similares a los de la gripe.", "Dolor de cabeza."]', 3, 'La característica esencial de la abstinencia de cafeína es la presencia de un síndrome de abstinencia característico que se desarrolla después de la interrupción abrupta (o reducción sustancial) de la ingesta diaria prolongada de cafeína (Criterio B). Debido a que las personas pueden no ser conscientes de la amplia variedad de fuentes de cafeína aparte del café, las colas y las bebidas energéticas (por ejemplo, analgésicos de venta libre y remedios para el resfriado, ayudas para la pérdida de peso, chocolate), quizá no relacionen la ingestión de estas sustancias con los síntomas de la abstinencia de cafeína. El síndrome de abstinencia de cafeína se indica por tres o más de los siguientes síntomas (Criterio B): dolor de cabeza; fatiga marcada o somnolencia; estado de ánimo disfórico, estado de ánimo deprimido o irritabilidad; dificultad para concentrarse, y síntomas similares a los de la gripe (náuseas, vómitos o dolor/rigidez muscular). El síndrome de abstinencia causa malestar clínicamente significativo o deterioro en las áreas sociales, ocupacionales u otras áreas importantes del funcionamiento (Criterio C). Los síntomas no deben estar asociados con los efectos fisiológicos de otra afección médica y no se explican mejor por otro trastorno mental (Criterio D). El dolor de cabeza es la característica distintiva de la abstinencia de cafeína y puede ser difuso, gradual en su desarrollo, pulsátil, intenso y sensible al movimiento. Sin embargo, los otros síntomas de la abstinencia de cafeína pueden ocurrir en ausencia del dolor de cabeza. Referencia: DSM-5-TR, Abstinencia de cafeína / Características diagnósticas (p. 572).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuánto aumenta el trastorno por consumo de cannabis el riesgo de que un adulto tenga cualquier otro trastorno por sustancias?', '["Una vez.", "Cinco veces.", "Nueve veces.", "Veinte veces."]', 2, 'El trastorno por consumo de cannabis es altamente comórbido con otros trastornos por consumo de sustancias (por ejemplo, alcohol, cocaína, opioides). Por ejemplo, en comparación con los adultos sin trastorno por consumo de cannabis, tener este trastorno multiplica el riesgo de cualquier otro trastorno por sustancias por un factor de aproximadamente nueve. El cannabis se ha considerado normalmente como una droga "de inicio" porque los individuos que consumen cannabis tienen considerablemente más probabilidades que los no usuarios de consumir posteriormente otras sustancias de mayor riesgo durante la vida (por ejemplo, opioides, cocaína). Entre los adultos que buscan tratamiento para un trastorno por consumo de cannabis, muchos (63%) refieren el uso problemático de sustancias secundarias o terciarias, como alcohol, cocaína, metanfetamina/anfetamina y heroína u otros opiáceos, y el trastorno por consumo de cannabis es a menudo un problema secundario o terciario entre aquellos con diagnóstico principal de otros trastornos por consumo de sustancias. Referencia: DSM-5-TR, Trastorno por consumo de cannabis / Comorbilidad (p. 581).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Un paciente se presenta en el servicio de urgencias quejándose de vómitos que "vienen y van". ¿Qué droga es probable que esté tomando el paciente regularmente?', '["Tabaco.", "Alcohol.", "Cannabis.", "Cocaína."]', 2, 'En cuanto a las dolencias médicas, el síndrome de hiperemesis cannabinoide es un síndrome de náuseas y vómitos cíclicos asociado al consumo habitual de cannabis que se ve cada vez más en los servicios de urgencias a medida que aumenta la prevalencia del consumo de cannabis. Referencia: DSM-5-TR, Trastorno por consumo de cannabis / Comorbilidad (pp. 581-582).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Qué grupo etnorracial adulto tiene la mayor prevalencia del trastorno por consumo de cannabis?', '["Asiáticos e isleños del Pacífico.", "Indios americanos/nativos de Alaska.", "Afroamericanos.", "Blancos."]', 1, 'Según la edad, la prevalencia del trastorno por consumo de cannabis en Estados Unidos es mayor entre los individuos de 18 a 29 años (6,9%) y menor entre los individuos de 45 años en adelante (0,8%). Las tasas del trastorno por consumo de cannabis son mayores en los hombres que en las mujeres (3,5 frente a 1,7%) y en los chicos que en las chicas de 12 a 17 años (3,4 frente a 2,8%), aunque las diferencias de género han ido disminuyendo en las cohortes de nacimientos recientes en varios países. En cuanto a las diferencias etnorraciales, para los adolescentes de 12 a 17 años, las tasas son más altas entre los hispanoamericanos (3,8%), seguidos de los blancos (3,1%), los afroamericanos (2,9%) y otros grupos etnorraciales (2,3%). Entre los adultos, la prevalencia del trastorno por consumo de cannabis es del 5,3% en los indios americanos y nativos de Alaska, del 4,5% en los afroamericanos, del 2,6% en los hispanoamericanos, del 2,2% en los blancos y del 1,3% en los asiáticos e isleños del Pacífico. Referencia: DSM-5-TR, Trastorno por consumo de cannabis / Prevalencia (p. 578).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de las siguientes drogas que pueden tener efectos alucinógenos no se considera en las clases químicas de alucinógenos del DSM-5-TR?', '["Mescalina.", "3 4-metilendioximetanfetamina (MDMA [éxtasis]).", "Cannabis.", "Psilocibina."]', 2, 'Los alucinógenos comprenden un grupo diverso de sustancias que, a pesar de tener diferentes estructuras químicas y posiblemente diferentes mecanismos moleculares, producen alteraciones similares de la percepción, el estado de ánimo y la cognición en los usuarios. Los alucinógenos incluidos sonas fenilalquilaminas (por ejemplo, mescalina, 2,5-dimetoxi-4-metilanfetamina [DOM] y MDMA [también llamada éxtasis o molly]); las indolaminas, como la psilocibina (y su metabolito psilocina, el compuesto principalmente responsable de los efectos psicodélicos de los hongos alucinógenos) y la dimetiltriptamina; y las ergolinas, como dietilamida del ácido lisérgico (LSD) y las semillas de gloria de la mañana. Además, otros varios compuestos etnobotánicos se clasifican como alucinógenos, de los cuales Salvia divinorum y el estramonio son dos ejemplos. Excluidos del grupo de alucinógenos están el cannabis y su compuesto activo, delta-9-tetrahidrocannabinol (THC; véase el capítulo "Trastornos relacionados con el cannabis"). Estas sustancias pueden tener efectos alucinógenos, pero se diagnostican por separado. Referencia: DSM-5-TR, Trastorno por consumo de otros alucinógenos / Características diagnósticas (p. 592).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿El uso de cuál de las siguientes drogas es más probable que provoque el desarrollo de un trastorno por consumo de alucinógenos?', '["Dietilamida del ácido lisérgico (LSD).", "Psilocibina.", "Dimetiltriptamina.", "3, 4-metilendioximetanfetamina (MDMA [éxtasis])."]', 3, 'El MDMA / éxtasis, como alucinógeno, puede tener efectos distintivos atribuibles a sus propiedades tanto alucinógenas como estimulantes. Los consumidores de éxtasis tienen más riesgo de desarrollar un trastorno por consumo de alucinógenos que aquellos que usan otros alucinógenos. Entre los usuarios adolescentes y adultos de éxtasis y los usuarios de otros alucinógenos, los criterios del trastorno por consumo de alucinógenos reportados más frecuentemente son la tolerancia, el uso peligroso, el uso a pesar de problemas emocionales o de salud, el abandono de actividades a causa del consumo y pasar mucho tiempo obteniendo, consumiendo o recuperándose de los efectos del consumo. Como se ha observado con otras sustancias, los criterios diagnósticos del trastorno por consumo de otros alucinógenos se disponen a lo largo de un solo continuo de gravedad. Referencia: DSM-5-TR, Trastorno por consumo de otros alucinógenos / Características diagnósticas (p. 592).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Para cuál de los siguientes alucinógenos hay evidencia de un síndrome de abstinencia?', '["Dietilamida del ácido lisérgico (LSD).", "3, 4-metilendioximetanfetamina (MDMA [éxtasis]).", "Psilocibina.", "Fenciclidina."]', 1, 'Dado que no se ha documentado sistemáticamente un síndrome de abstinencia clínicamente significativo en los seres humanos, el diagnóstico de síndrome de abstinencia de alucinógenos no está incluido en el DSM-5-TR y, por lo tanto, no es parte de los criterios diagnósticos del trastorno por consumo de alucinógenos. Sin embargo, puede haber evidencia sobre la abstinencia de MDMA, con presencia de dos o más síntomas de abstinencia (por ejemplo, malestar, alteración del apetito, cambios de humor [ansioso, deprimido, irritable], mala concentración, alteración del sueño) o evitación de la abstinencia, observada en más de la mitad de los individuos de diversas muestras de consumidores de éxtasis en Estados Unidos e internacionalmente. Referencia: DSM-5-TR, Trastorno por consumo de otros alucinógenos / Características diagnósticas (p. 592).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Qué distingue los trastornos mentales inducidos por sustancias/medicamentos de los trastornos por consumo de sustancias?', '["Ocurren solo durante los períodos de intoxicación.", "Los síntomas continúan a pesar del cese del consumo de la sustancia.", "Los síntomas cognitivos y conductuales contribuyen al uso continuado.", "Ocurren solo si el medicamento se toma a dosis más altas de las sugeridas."]', 2, 'Los trastornos mentales inducidos por sustancias/medicamentos son síndromes del SNC potencialmente graves, generalmente temporales pero a veces persistentes, que se desarrollan en el contexto de los efectos de las sustancias de abuso, los medicamentos y algunas toxinas. Se distinguen de los trastornos por consumo de sustancias en que hay un conjunto de síntomas cognitivos, conductuales y fisiológicos que contribuyen al consumo continuado de la sustancia a pesar de los problemas significativos relacionados con ella. Los trastornos mentales inducidos por sustancias se desarrollan en el contexto de la intoxicación con o la abstinencia de sustancias de abuso, mientras que los trastornos mentales inducidos por medicamentos pueden verse en relación con los medicamentos recetados o de venta libre que se toman a las dosis sugeridas. Ambas afecciones son generalmente temporales y es probable que desaparezcan antes de transcurrido 1 mes o así del cese de la abstinencia aguda, la intoxicación intensiva o el uso del medicamento. Referencia: DSM-5-TR, Trastornos mentales inducidos por sustancias / medicamentos (p. 550); Desarrollo y curso (pp. 551-552).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Qué dos grupos de agentes inhalantes no están entre las sustancias reconocidas para el diagnóstico de trastorno por consumo de inhalantes del DSM-5-TR?', '["Encendedores de butano y tolueno.", "Xileno y butano.", "Tricloroetano y hexano.", "Óxido nitroso y gases de nitrito."]', 3, 'Ejemplos de sustancias inhalantes son los hidrocarburos volátiles, que comprenden gases tóxicos de pegamentos, combustibles, pinturas y otros compuestos volátiles. Siempre que sea posible, se debe nombrar la sustancia involucrada (por ejemplo, trastorno por uso de tolueno). Sin embargo, la mayoría de los compuestos que se inhalan son una mezcla de varias sustancias que pueden producir efectos psicoactivos y a menudo es difícil determinar la sustancia exacta responsable del trastorno. A menos que haya evidencia clara de que se ha utilizado una única sustancia sin mezclar, debe usarse el término general inhalante al registrar el diagnóstico. Los trastornos que surgen de la inhalación de óxido nitroso o de amilo, butilo o isobutilnitrito se diagnostican como trastorno por consumo de otra sustancia (o sustancia desconocida). Referencia: DSM-5-TR, Trastorno por consumo de inhalantes / Características diagnósticas (pp. 602-6053).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', 'Un estudiante universitario de 22 años acude a su médico de atención primaria quejándose del empeoramiento progresivo de una sensación de adormecimiento, hormigueo y debilidad en ambas piernas que padece durante las últimas semanas. Su marcha es inestable y tiene dificultades para agarrar objetos con las manos. No había consumido ninguna sustancia el día de la presentación, pero admite que durante los últimos 3 meses ha estado tomando una determinada sustancia a diario. ¿Qué trastorno por consumo de sustancias es el más probable que explique los síntomas de este paciente?', '["Trastorno por consumo de otra sustancia (o sustancia desconocida).", "Trastorno por consumo de otros alucinógenos.", "Trastorno por consumo de inhalantes.", "Trastorno por consumo de opioides."]', 0, 'La clase diagnóstica trastornos relacionados con otras sustancias (o desconocidas) se aplica a las sustancias que no están incluidas en ninguna de las nueve clases de sustancias presentadas anteriormente en este capítulo (es decir, alcohol, cafeína, cannabis, alucinógenos [fenciclidina y otros], inhalantes, opioides, sedantes, hipnóticos y ansiolíticos, estimulantes y tabaco). Dichas sustancias incluyen esteroides anabólicos, medicamentos antiinflamatorios no esteroideos, corticosteroides, medicamentos antiparkinsonianos, antihistamínicos, óxido nitroso ("gas de la risa"), amilo, butilo o isobutilnitritos, nuez de betel, que se mastica en muchas regiones geográficas para producir una leve euforia y sensación de flotación, y kava (de una planta de pimienta del Pacífico Sur), que produce leve euforia, sedación, incoordinación y pérdida de peso, así como efectos negativos sobre la salud (por ejemplo, hepatitis leve, anomalías pulmonares). Téngase en cuenta que las sustancias gaseosas se incluyen en la categoría de los inhalantes solo si son agentes hidrocarbonados; otras sustancias gaseosas (como el óxido nitroso, mencionado anteriormente) se incluyen en la categoría de otra sustancia (o sustancia desconocida). Los trastornos relacionados con sustancias desconocidas son los asociados a sustancias no identificadas, como las intoxicaciones en las que el individuo no puede identificar la droga ingerida, o los trastornos por consumo de sustancias tales como las drogas nuevas del mercado negro aún no identificadas o las drogas conocidas vendidas ilegalmente bajo nombres falsos. La pertenencia a ciertas poblaciones con acceso al óxido nitroso puede asociarse al uso frecuente de esta sustancia y posiblemente al diagnóstico de trastorno por consumo de óxido nitroso. El papel de este gas como agente anestésico lleva al mal uso por parte de algunos profesionales médicos y dentales, y su uso como propelente en productos comerciales (por ejemplo, dispensadores de crema batida) contribuye al mal uso por parte de los trabajadores de servicios de alimentos. El mal uso del óxido nitroso por parte de adolescentes y adultos jóvenes es significativo, y algunos individuos con consumo muy frecuente pueden presentar complicaciones médicas y afecciones mentales graves, como mieloneuropatía, degeneración combinada subaguda de la médula espinal, neuropatía periférica y psicosis. Referencia: DSM-5-TR, Trastorno por consumo de otra sustancia / Características diagnósticas y asociadas (p. 654).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Qué sistema de órganos o función anatómica se ve más comúnmente afectado por el uso crónico de 3,4-metilendioximetanfetamina (MDMA [éxtasis])?', '["Neurológico.", "Respiratorio.", "Cardiopulmonar.", "Cavidad oral."]', 0, 'Existe evidencia de que el MDMA puede producir efectos neurotóxicos persistentes como deterioros de la memoria, la función psicológica y la función neuroendocrina, disfunción del sistema de serotonina y trastornos del sueño, así como efectos adversos sobre la microvasculatura cerebral y la maduración de la sustancia blanca, y daño axonal. Referencia: DSM-5-TR, Trastorno por consumo de otros alucinógenos / Consecuencias funcionales del trastorno por consumo de otros alucinógenos (p. 594).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Qué porcentaje de los individuos que experimentan abstinencia de sedantes, hipnóticos o ansiolíticos sin tratamiento sufren una convulsión de gran mal?', '["510%.", "10-20%.", "20-30%.", "30-40%."]', 2, 'La característica esencial de la abstinencia de sedantes, hipnóticos o ansiolíticos es la presencia de un síndrome característico que se desarrolla después de una disminución marcada o del cese de su consumo al cabo de varias semanas o más de uso regular (Criterios A y B). Este síndrome de abstinencia se caracteriza por dos o más síntomas (similares a los de la abstinencia de alcohol) entre los que se incluyen la hiperactividad autonómica (por ejemplo, aumento de la frecuencia cardíaca, la frecuencia respiratoria, la presión arterial o la temperatura corporal, junto con sudoración), el temblor de las manos, el insomnio, las náuseas, a veces acompañadas de vómitos, la ansiedad y la agitación psicomotora. Puede producirse una crisis de gran mal en quizás hasta el 20-30% de los individuos que experimentan abstinencia no tratada de estas sustancias. En la abstinencia grave pueden ocurrir alucinaciones o ilusiones visuales, táctiles o auditivas, pero generalmente se encuentran en el contexto de un delirio de abstinencia. Referencia: DSM-5-TR, Abstinencia de sedantes, hipnóticos o ansiolíticos / Características diagnósticas (p. 629).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál es la vía de administración de estimulantes más prevalente entre los individuos que están en tratamiento por trastorno por consumo de estimulantes?', '["Oral.", "Intranasal.", "Fumada.", "Intravenosa."]', 2, 'Algunas personas comienzan a usar estimulantes para controlar el peso o para mejorar el rendimiento en la escuela, el trabajo o los deportes. El uso inicial puede incluir la obtención de medicamentos como el metilfenidato o las sales de anfetamina, recetados a otros para el tratamiento del trastorno de déficit de atención/hiperactividad. Entre las admisiones primarias para tratamiento del consumo de sustancias de tipo anfetamínico en Estados Unidos, el 61 % refirieron que las fumaban, el 26% que se las inyectaban y el 9% que las esnifaban, lo que sugiere que el trastorno por consumo de estimulantes puede desarrollarse a partir de múltiples modos de administración. Referencia: DSM-5-TR, Trastorno por consumo de estimulantes / Desarrollo y curso (p. 637).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál es el diagnóstico psiquiátrico coexistente más común entre los individuos con historial de exposición prenatal significativa al alcohol?', '["Trastorno de depresión mayor.", "Trastorno de ansiedad generalizada.", "Trastorno de déficit de atención/hiperactividad (TDAH).", "Trastorno negativista desafiante."]', 2, 'Se han identificado problemas de salud mental en más del 90% de los individuos con antecedentes de exposición prenatal significativa al alcohol. El diagnóstico coexistente más común es el TDAH, pero la investigación ha demostrado que los individuos con trastorno neurocomportamental asociado a la exposición prenatal al alcohol (ND-PAE) difieren en cuanto a sus características neuropsicológicas y su respuesta a las intervenciones farmacológicas. Otros trastornos coexistentes con gran probabilidad son el trastorno negativista desafiante y el trastorno de la conducta, pero la idoneidad de estos diagnósticos debe evaluarse en el contexto de los significativos deterioros del funcionamiento intelectual general y la función ejecutiva que a menudo se asocian con la exposición prenatal al alcohol. Se han descrito síntomas anímicos como los del trastorno bipolar y los trastornos depresivos. La historia de exposición prenatal al alcohol se asocia a un riesgo aumentado de los trastornos por consumo de tabaco, de alcohol y de otras sustancias más adelante. Referencia: DSM-5-TR, Afecciones que necesitan más estudio / Trastorno neurocomportamental asociado a la exposición prenatal al alcohol / Comorbilidad (p. 920).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Qué adicción se ha incluido en el DSM-5-TR como posible diagnóstico?', '["Adicción al sexo.", "Adicción al ejercicio.", "Adicción a las compras.", "Adicción a los videojuegos."]', 3, 'Además de los trastornos relacionados con sustancias, este capítulo también incluye el trastorno de juego, reflejando la evidencia de que los comportamientos de juego activan sistemas de recompensa similares a los activados por las drogas de abuso y producen algunos síntomas conductuales que parecen comparables a los producidos por los trastornos por consumo de sustancias. También se han descrito otros patrones de comportamiento excesivo, como el juego por Internet (véase "Afecciones que necesitan más estudio "), pero la investigación sobre estos y otros síndromes conductuales es menos clara. Por lo tanto, hay grupos de comportamientos repetitivos, a veces denominados adicciones conductuales (con subcategorías como la adicción al sexo, la adicción al ejercicio y la adicción a las compras), que no están incluidos porque no hay suficiente evidencia revisada por pares para establecer los criterios diagnósticos y las descripciones del curso que son necesarios para identificar estos comportamientos como trastornos mentales. El trastorno de juego es actualmente el único trastorno no relacionado con sustancias incluido en el capítulo de la Sección II del DSM-5-TR "Trastornos relacionados con sustancias y trastornos adictivos". Sin embargo, hay otros trastornos conductuales que muestran algunas similitudes con los trastornos por consumo de sustancias y el trastorno de juego para los que la palabra adicción se utiliza comúnmente en los contextos no médicos, y la única afección con bibliografía considerable es el juego compulsivo por Internet. El juego por Internet ha sido definido como una "adicción" por el Gobierno chino y se considera una amenaza para la salud pública en Corea del Sur, donde se han establecido sistemas de tratamiento y prevención. Se han publicado informes sobre el tratamiento de esta afección en revistas médicas, principalmente de países asiáticos, pero también en Estados Unidos y otros países de altos ingresos. El uso excesivo de Internet distinto de los videojuegos en línea (por ejemplo, el uso excesivo de redes sociales como Facebook o TikTok, la visualización de pornografía en línea) no se considera análogo al trastorno de juego por Internet, y las futuras investigaciones sobre otros usos excesivos de Internet tendrían que seguir pautas similares a las sugeridas en el DSM-5-TR. Referencia: DSM-5-TR, Trastornos relacionados con sustancias y trastornos adictivos / Introducción al capítulo (p. 543); Afecciones que necesitan más estudio / Trastorno de juego por Internet (pp. 913-916).'),
('DSM-5-TR', 'Trastornos relacionados con sustancias y trastornos adictivos', '¿Cuál de las siguientes es una de las consecuencias médicas más comunes del consumo de alcohol en las personas con trastorno por consumo de alcohol?', '["Cirrosis.", "Cardiomiopatía.", "Hipertensión.", "Pancreatitis."]', 2, 'La ingestión repetida de altas dosis de alcohol puede afectar a casi todos los sistemas de órganos, especialmente al tracto gastrointestinal, el sistema cardiovascular y los sistemas nerviosos central y periférico. Los efectos gastrointestinales incluyen gastritis, úlceras estomacales o duodenales y, en aproximadamente el 15% de los individuos que consumen alcohol en exceso, cirrosis hepática y/o pancreatitis. También hay una mayor tasa de cáncer de esófago, estómago y otras partes del tracto gastrointestinal. Una de las condiciones más comúnmente asociadas es la hipertensión de grado bajo. La cardiomiopatía y otras miopatías son menos comunes, pero la tasa es mayor entre aquellos que beben mucho. Estos factores, junto con notables aumentos de los niveles de triglicéridos y colesterol unido a lipoproteínas de baja densidad, contribuyen a un riesgo elevado de enfermedad cardíaca. La neuropatía periférica puede evidenciarse por debilidad muscular, parestesias y disminución de la sensación periférica. Los efectos más persistentes en el sistema nervioso central son los déficits cognitivos, como el deterioro grave de la memoria y cambios degenerativos en el cerebelo. Estos efectos están relacionados con los efectos directos del alcohol, los traumatismos o las deficiencias de vitaminas (particularmente de las vitaminas B, incluida la tiamina). Un efecto devastador sobre el sistema nervioso central es el relativamente raro trastorno amnésico persistente inducido por alcohol, o síndrome de Wernicke-Korsakoff, en el cual la capacidad de codificar nuevos recuerdos está gravemente dañada. Esta entidad se describe ahora en el capítulo "Trastornos neurocognitivos" y se denomina trastorno neurocognitivo inducido por sustancias/medicamentos. Referencia: DSM-5-TR, Trastorno por consumo de alcohol / Características asociadas (pp. 555-556).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'El rasgo esencial del diagnóstico de delirium en el DSM-5-TR es una alteración de la atención/conciencia y de la cognición que se desarrolla en un corto período de tiempo, representa un cambio respecto a la línea de base y tiende a fluctuar en cuanto a gravedad durante el transcurso de 1 día. ¿Cuál de las siguientes condiciones adicionales debe aplicarse?', '["Debe haber evidencia de laboratorio de una demencia en evolución.", "La alteración debe estar asociada a una perturbación del ciclo sueño-vigilia.", "La alteración no debe ocurrir en el contexto de un nivel de excitación seriamente reducido, como el coma.", "La alteración no debe estar superpuesta a un trastorno neurocognitivo preexistente."]', 2, 'La característica principal del delirium es una alteración de la atención o la conciencia (Criterio A) que va acompañada de un cambio en la cognición de base (Criterio C) y que no puede explicarse mejor por un trastorno neurocognitivo preexistente o en evolución (Criterio D). La capacidad de evaluar la cognición para diagnosticar el delirium depende de que haya un nivel de excitación suficiente como para responder a la estimulación verbal; por lo tanto, el delirium no debe diagnosticarse en el contexto de un coma (Criterio D). La alteración se desarrolla en un corto período de tiempo, generalmente de horas a unos pocos días, y tiende a fluctuar en términos de gravedad durante el transcurso del día (Criterio B). Hay evidencia a partir de la historia, el examen físico o los hallazgos de laboratorio de que la alteración es consecuencia fisiológica de otra afección médica subyacente, una intoxicación o abstinencia de sustancias, el uso de un medicamento o la exposición a una toxina, o una combinación de estos factores (Criterio E). Tanto los trastornos neurocognitivos (TNC) mayores como los leves pueden aumentar el riesgo de delirium y complicar su curso. El problema de diagnóstico diferencial más común al evaluar la confusión en los adultos mayores es desenmarañar los síntomas de delirium y de demencia. El clínico debe determinar si el individuo tiene delirium, un delirium superpuesto a un TNC preexistente, como el debido a la enfermedad de Alzheimer, o un TNC sin delirium. La distinción tradicional entre delirium y demencia según la agudeza del inicio y el curso temporal es particularmente difícil en aquellos individuos mayores con un TNC previo que quizá no esté diagnosticado o que desarrollan un deterioro cognitivo persistente después de un episodio de delirium. Referencia: DSM-5-TR, Delirium / Criterios diagnósticos (p. 672); Características diagnósticas (p. 675); Diagnóstico diferencial (pp. 677-678).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Tanto los trastornos neurocognitivos mayores como los leves pueden aumentar el riesgo de delirium y complicar su curso. El delirium se distingue de la demencia según las características clave de inicio agudo, deterioro de la atención y ¿cuál de las siguientes opciones?', '["Curso fluctuante.", "Curso estable.", "Presencia de depresión.", "Movimientos de rueda dentada."]', 0, 'Según el Criterio B del delirium, la alteración se desarrolla en un corto período de tiempo, generalmente de horas a unos pocos días, y tiende a fluctuar durante el transcurso del día, a menudo empeorando por la tarde y por la noche cuando disminuyen los estímulos orientadores externos. Referencia: DSM-5-TR, Delirium / Características diagnósticas (p. 675).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Una mujer de 79 años con antecedentes de depresión está siendo evaluada en un hogar de ancianos por sospecha de infección del tracto urinario. Se distrae fácilmente, persevera en las respuestas a las preguntas, hace la misma pregunta repetidamente, no puede concentrarse y no puede responder a las preguntas sobre la orientación. Los cambios del estado mental evolucionaron en un solo día. Su familia informa que pensaron que la paciente "no era ella misma" cuando la vieron la noche anterior, pero el informe de enfermería de esta mañana indica que la paciente se mostraba cordial y de forma apropiada. ¿Cuál es el diagnóstico más probable?', '["Trastorno de depresión mayor, episodio recurrente.", "Trastorno depresivo debido a otra afección médica.", "Delirium.", "Trastorno de depresión mayor, con ansiedad."]', 2, 'Los síntomas de esta paciente están relacionados proximalmente con la infección del tracto urinario: sus cambios del estado mental tuvieron un curso temporal fluctuante con alteración de la atención y la cognición. Estas son las características diagnósticas del delirium. Referencia: DSM-5-TR, Delirium / Criterios diagnósticos (pp. 672-674).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Los criterios diagnósticos del trastorno neurocognitivo mayor o leve con cuerpos de Lewy (TNCCL) incluyen el cumplimiento de los criterios del trastorno neurocognitivo mayor o leve y la presencia de una combinación de características diagnósticas centrales y características diagnósticas sugeridas para el trastorno neurocognitivo probable o posible con cuerpos de Lewy. Otra característica necesaria para el diagnóstico es que la alteración no se explique mejor por patología cerebrovascular, otra enfermedad neurodegenerativa, los efectos de una sustancia u otro trastorno mental, neurológico o sistémico. ¿Cuál de las siguientes opciones completa la lista de características necesarias para el diagnóstico?', '["Un inicio agudo y una progresión rápida.", "Un inicio insidioso y una progresión gradual.", "Un inicio insidioso y una progresión rápida.", "Una presentación en aumento y disminución."]', 1, 'El TNCCL incluye no solo un deterioro cognitivo progresivo (con cambios tempranos de la atención compleja y la función ejecutiva en lugar del aprendizaje y la memoria), sino también alucinaciones visuales complejas recurrentes, síntomas concurrentes de trastorno del comportamiento del sueño REM (que puede ser una manifestación muy temprana) y alucinaciones en otras modalidades sensoriales, depresión, apatía, ansiedad y delirios. Los síntomas fluctúan en un patrón que puede parecerse al delirium, pero no se puede encontrar una causa subyacente adecuada. La presentación variable de los síntomas del TNCCL reduce la probabilidad de que se observen todos los síntomas en una visita clínica breve y requiere una evaluación exhaustiva de las observaciones del cuidador. El uso de escalas de evaluación específicamente diseñadas para evaluar la fluctuación puede ayudar en el diagnóstico. Otra característica central es el parkinsonismo espontáneo, que debe comenzar después del inicio del deterioro cognitivo; por convención, se observan déficits cognitivos importantes al menos 1 año antes de los síntomas motores. El TNCCL es un trastorno gradualmente progresivo de inicio insidioso; sin embargo, a menudo hay una historia prodrómica de episodios confusos (delirium) de inicio agudo, con frecuencia precipitados por alguna enfermedad o cirugía. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve con cuerpos de Lewy / Criterios diagnósticos (pp. 699-700); Desarrollo y curso (p. 701); Diagnóstico diferencial (p. 702).'),
('DSM-5-TR', 'Trastornos neurocognitivos', '¿Cuál de los siguientes no es un criterio diagnóstico, característica o marcador del trastorno neurocognitivo mayor o leve con cuerpos de Lewy (TNCCL)?', '["Síntomas concurrentes de trastorno del comportamiento del sueño REM.", "Alta captación del transportador de dopamina estriatal en los ganglios basales, demostrada por tomografía computarizada de emisión de fotón único (SPECT) o tomografía por emisión de positrones (PET).", "Baja captación del transportador de dopamina estriatal en los ganglios basales, demostrada por SPECT o PET.", "Sensibilidad neuroléptica grave."]', 1, 'La enfermedad neurodegenerativa subyacente en el TNCCL es principalmente una sinucleinopatía debido a una mala formación y agregación de la a-sinucleína. Es posible que se necesite realizar pruebas cognitivas más allá del uso de un instrumento de cribado breve para definir claramente los déficits. Las escalas de evaluación desarrolladas para medir la fluctuación pueden ser útiles. El trastorno del comportamiento del sueño REM asociado puede diagnosticarse mediante un estudio formal de sueño o identificándolo al preguntar al paciente o al informante sobre los síntomas relevantes. La sensibilidad a los neurolépticos (prueba de provocación) no se recomienda como marcador diagnóstico pero, si se observa, genera sospechas de TNCCL. Una característica sugerente del diagnóstico es la baja captación del transportador de dopamina estriatal en la tomografía SPECT o PET. Los biomarcadores que respaldan el TNCCL, pero con evidencia de valor diagnóstico limitado, son los que se indican a continuación: conservación del volumen temporal medial en relación con la enfermedad de Alzheimer en las imágenes de la RM, baja captación generalizada en la tomografía SPECT/PET de perfusión con actividad occipital reducida con o sin el signo de la isla cingulada (preservación de la corteza cingulada posterior en relación con la precuña más la cuña en la imagen de fluorodesoxiglucosa-PET) y actividad de ondas lentas prominente en el electroencefalograma con fluctuaciones periódicas en el rango pre-alfa/teta. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve con cuerpos de Lewy / Marcadores diagnósticos (p. 701).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Un hombre de 72 años sin antecedentes de trastornos por consumo de alcohol u otras sustancias y sin antecedentes psiquiátricos es llevado a la sala de urgencias debido a episodios transitorios de pérdida de conciencia inexplicados. Su esposa informa que ha experimentado caídas repetidas y síncopes durante el último año, así como alucinaciones auditivas y visuales. Un examen cardíaco exhaustivo no ha encontrado evidencia de enfermedad cardíaca estructural o arritmias. En la sala de urgencias se encuentra que tiene disfunción autonómica grave con hipotensión ortostática e incontinencia urinaria. ¿Cuál es el mejor diagnóstico provisional para este paciente?', '["Esquizofrenia de inicio reciente.", "Posible trastorno neurocognitivo mayor o leve con cuerpos de Lewy (TNCCL).", "Posible trastorno neurocognitivo mayor o leve debido a la enfermedad de Alzheimer.", "Trastorno comicial de inicio reciente."]', 1, 'Se debe obtener más información sobre la cognición, el marco temporal y otras etiologías, pero el mejor diagnóstico provisional con la información limitada disponible es el de TNCCL. Las personas con TNCCL frecuentemente experimentan caídas repetidas, síncopes y episodios transitorios de pérdida de conciencia inexplicados. También se puede observar una marcada disfunción autonómica con hipotensión ortostática e incontinencia urinaria. Las alucinaciones auditivas y otras no visuales son comunes, al igual que los delirios sistematizados, la desidentificación delirante y la depresión. El paciente tiene alucinaciones auditivas y visuales, pero ninguna otra característica de la esquizofrenia, y la edad de inicio, junto con los síntomas neurológicos asociados, sugiere un trastorno neurodegenerativo, en lugar de una esquizofrenia. Entre los trastornos neurocognitivos, la prominencia de las alucinaciones, la pérdida episódica de la conciencia y los síntomas autonómicos, en lugar de un deterioro marcado de la memoria, durante las primeras fases son argumentos en contra del trastorno neurocognitivo debido a la enfermedad de Alzheimer y a favor del TNCCL. El paciente tiene una de las características diagnósticas centrales de TNCCL: las alucinaciones visuales, que justifican un nivel de certeza "posible" para el diagnóstico. Un trastorno comicial podría causar pérdida episódica de la conciencia, pero no explicaría fácilmente las alucinaciones y los síntomas autonómicos. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve con cuerpos de Lewy / Características diagnósticas y Características asociadas (p. 700).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Los criterios diagnósticos del trastorno neurocognitivo (TNC) debido a la infección por VIH incluyen el cumplimiento de los criterios del TNC mayor o leve y la infección documentada por el VIH (confirmada por los métodos de laboratorio establecidos). ¿Cuál de las siguientes es una característica destacada del TNC debido a la infección por VIH?', '["Deterioro del funcionamiento ejecutivo.", "Delirios y alucinaciones significativas al inicio del trastorno.", "Dificultad marcada para recordar la información aprendida.", "Progresión rápida hacia un deterioro neurocognitivo profundo."]', 0, 'El TNC asociado a la infección por VIH generalmente muestra un "patrón subcortical" con deterioro prominente de la función ejecutiva, ralentización de la velocidad de procesamiento, problemas con las tareas de atención más exigentes y dificultad para aprender nueva información, pero menos problemas con el recuerdo de la información ya aprendida. En el TNC mayor, la ralentización puede ser prominente. Las dificultades del lenguaje, como la afasia, son poco comunes, aunque se pueden observar reducciones de la fluidez. Los procesos patogénicos del VIH pueden afectar a cualquier parte del cerebro; por lo tanto, son posibles otros patrones. Un TNC debido a infección por VIH puede resolverse, mejorar, empeorar lentamente o tener un curso fluctuante. La progresión rápida hacia un deterioro neurocognitivo profundo es poco común en el contexto del tratamiento antiviral combinado actualmente disponible; por lo tanto, un cambio abrupto del estado mental en una persona con VIH provocará la evaluación de otros orígenes médicos del cambio cognitivo, incluidas las infecciones 5 E secundarias. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve debido a la infección por VIH / Características diagnósticas; Desarrollo y curso (pp. 718-719).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Además de la infección documentada por el VIH y el cumplimiento de los criterios del trastorno neurocognitivo (TNC) mayor o leve, ¿qué otro requisito debe cumplirse para merecer un diagnóstico de TNC mayor o leve debido a la infección por VIH?', '["Presencia de VIH en el líquido cefalorraquídeo.", "Un patrón de deterioro cognitivo caracterizado por predominio temprano de afasia y memoria deteriorada para la información previamente aprendida.", "Incapacidad de atribuir el TNC a afecciones no relacionadas con el VIH (incluidas las enfermedades cerebrales secundarias), otra afección médica o un trastorno mental.", "Presencia de anillos de Kayser-Fleischer."]', 2, 'Además de requerir el cumplimiento de los criterios del TNC mayor o leve y la infección documentada por el VIH) los criterios diagnósticos del TNC debido a infección por VIH estipulan que el TNC no se explique mejor por afecciones no relacionadas con el VIH, incluida la patología cerebral secundaria como la leucoencefalopatía multifocal progresiva o la meningitis criptocócica, no se atribuya a otra afección médica y no se explique mejor por un trastorno mental. Un TNC debido a infección por VIH generalmente muestra un "patrón subcortical" con deterioro prominente de la función ejecutiva, ralentización de la velocidad de procesamiento, problemas con las tareas de atención más exigentes y dificultad para aprender nueva información, pero menos problemas con el recuerdo de la información ya aprendida. En el TNC mayor, la ralentización puede ser prominente. Las dificultades del lenguaje, como la afasia, son poco comunes, aunque se pueden observar reducciones de la fluidez. Los procesos patogénicos del VIH pueden afectar a cualquier parte del cerebro; por lo tanto, son posibles otros patrones. El TNC debido al VIH es más prevalente en los individuos con altas cargas virales en el líquido cefalorraquídeo, pero este no es un criterio diagnóstico. Los anillos de Kayser-Fleischer se observan en la enfermedad de Wilson, no en el VIH. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve debido a la infección por VIH / Criterios diagnósticos y Características diagnósticas (pp. 717-718); Características asociadas (p. 718).'),
('DSM-5-TR', 'Trastornos neurocognitivos', '¿Cuál de las siguientes características caracteriza al trastorno neurocognitivo mayor o leve inducido por alcohol, tipo amnésico-confabulatorio?', '["Amnesia de nueva información y confabulación.", "Convulsiones.", "Amnesia de información previamente aprendida y parálisis de la mirada hacia abajo.", "Anosognosia y apraxia."]', 0, 'El trastorno neurocognitivo inducido por alcohol se manifiesta frecuentemente con una combinación de deterioros de la función ejecutiva y de los dominios de la memoria y el aprendizaje. Las características del trastorno neurocognitivo amnésico-confabulatorio inducido por alcohol (síndrome de Korsakoff) incluyen amnesia prominente (dificultad marcada para aprender nueva información, con olvido rápido) y tendencia a confabular. Estas manifestaciones pueden coexistir con signos de encefalopatía por tiamina (encefalopatía de Wernicke), con características asociadas como el nistagmo y la ataxia. La oftalmoplejia de la encefalopatía de Wernicke se caracteriza típicamente por parálisis de la mirada lateral. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve inducido por sustancias / medicamentos / Características diagnósticas (pp. 714-715).'),
('DSM-5-TR', 'Trastornos neurocognitivos', '¿Cuál de las siguientes afirmaciones sobre el diagnóstico del trastorno neurocognitivo debido a la enfermedad de Huntington (TNCEH) es verdadera?', '["El TNCEH es un diagnóstico/trastorno basado en los estudios de laboratorio.", "El TNCEH requiere neuroimágenes positivas para el diagnóstico.", "El TNCEH es un diagnóstico clínico basado en hallazgos físicos anormales y antecedentes familiares/hallazgos genéticos.", "El TNCEH es un diagnóstico que se define mejor como el de pacientes que tienen un temblor de \"amasar píldoras\"."]', 2, 'La prueba genética es la principal prueba de laboratorio para determinar la enfermedad de Huntington, que es un trastorno autosómico dominante con penetrancia completa. Se da un diagnóstico en firme de enfermedad de Huntington en presencia de anomalías motoras extrapiramidales inequívocas en un individuo con antecedentes familiares de enfermedad de Huntington o pruebas genéticas que muestren la expansión de repeticiones trinucleótidas CAG en el gen HTT, ubicado en el cromosoma 4. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve debido a la enfermedad de Huntington / Características diagnósticas (p. 727); Marcadores diagnósticos (p. 728).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'La depresión, la irritabilidad, la ansiedad, los síntomas obsesivo-compulsivos y la apatía se asocian frecuentemente con la enfermedad de Huntington y a menudo preceden al inicio de los síntomas motores. La psicosis raramente precede al inicio de los síntomas motores. ¿Cuál de las siguientes es una característica central del trastorno neurocognitivo mayor o leve debido a la enfermedad de Huntington?', '["Deterioro cognitivo progresivo con cambios tempranos de la función ejecutiva.", "Deterioro de la memoria temprano y prominente que afecta principalmente a la memoria a corto plazo.", "Psicosis en las primeras etapas, con alucinaciones olfativas marcadas.", "Movimientos bruscos voluntarios."]', 0, 'Una característica central de la enfermedad de Huntington es el deterioro cognitivo progresivo con cambios tempranos de la función ejecutiva (es decir, velocidad de procesamiento, organización y planificación), en lugar del aprendizaje y de la memoria. Los cambios cognitivos y de comportamiento asociados a menudo preceden a la aparición de las típicas anomalías motoras de bradicinesia (es decir, ralentización del movimiento voluntario) y corea (es decir, movimientos bruscos involuntarios). Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve debido a la enfermedad de Huntington / Características diagnósticas; Características asociadas (p. 727).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'La prueba genética es la principal prueba de laboratorio para la determinación de la enfermedad de Huntington. ¿Cuál de las siguientes opciones caracteriza mejor la naturaleza genética de la enfermedad de Huntington?', '["Herencia recesiva ligada al cromosoma X con penetrancia incompleta.", "Herencia autosómica recesiva con penetrancia completa.", "Herencia autosómica dominante con penetrancia completa.", "Herencia dominante ligada al cromosoma X."]', 2, 'La base genética de la enfermedad de Huntington es una expansión autosómica dominante y de penetrancia completa del trinucleótido CAG, a menudo llamada repetición de CAG, en el gen de la huntingtina. Una longitud de 40 o más repeticiones de CAG se asocia invariablemente a la enfermedad de Huntington, siendo las longitudes de repetición más largas las que se asocian a una edad temprana de inicio. Una longitud de repeticiones de CAG en el rango de 36-39 se considera parcialmente penetrante, lo que significa que esta longitud puede o no llevar a la enfermedad de Huntington. Si la enfermedad de Huntington ocurre con longitudes de repetición en este rango, a menudo se asocia a un inicio tardío en la vida (diagnóstico después de los 70 años). Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve debido a la enfermedad de Huntington / Factores de riesgo y pronóstico; Marcadores diagnósticos (p. 728).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'El trastorno neurocognitivo (TNC) mayor o leve debido a enfermedad por priones comprende los TNC asociados con un grupo de encefalopatías espongiformes subagudas causadas por agentes transmisibles conocidos como priones. ¿Cuál es la enfermedad priónica más común?', '["Enfermedad de Creutzfeldt-Jakob.", "Encefalopatía espongiforme bovina.", "Enfermedad de Huntington.", "Neurosífilis."]', 0, 'Las enfermedades priónicas son la enfermedad de Creutzfeldt-Jakob esporádica, genética y yatrogénica, la variante de la enfermedad de Creutzfeldt-Jakob, la prionopatía sensible a proteasas variable, el kuru, el síndrome de Gerstmann-Sträussler-Scheinker y el insomnio fatal. El tipo más común es la enfermedad de Creutzfeldt-Jakob esporádica, generalmente llamada enfermedad de Creutzfeldt-Jakob (EC). (La ECJ variante es mucho más rara y se asocia a la transmisión de la encefalopatía espongiforme bovina, también llamada "enfermedad de las vacas locas"). Típicamente, los individuos con ECJ presentan déficits neurocognitivos, ataxia y movimientos anormales como mioclonías, corea o distonía; el reflejo de sobresalto también es común. Típicamente, la historia revela una rápida progresión hacia el TNC mayor en tan solo unos 6 meses y, por lo tanto, el trastorno se ve típicamente solo en el grado mayor. Sin embargo, muchas personas con el trastorno pueden tener presentaciones atípicas y la enfermedad solo puede confirmarse mediante biopsia o durante la autopsia. El síndrome de Wernicke-Korsakoff, la neurosífilis y la enfermedad de Huntington no son enfermedades priónicas; el síndrome de Wernicke-Korsakoff es secundario a la deficiencia de tiamina, la enfermedad de Huntington es secundaria a un defecto genético y la neurosífilis está causada por una infección de transmisión sexual. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve debido a enfermedad por priones / Características diagnósticas (pp. 721-722).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Se ha informado de que la enfermedad priónica ocurre en individuos de todas las edades, desde la adolescencia hasta la vejez. ¿Cuál de las siguientes opciones caracteriza mejor el marco de tiempo de la progresión de la enfermedad?', '["En unos pocos meses.", "En varios días.", "En varias semanas.", "En 5 años."]', 0, 'La enfermedad priónica puede desarrollarse a cualquier edad en los adultos. La edad de mayor incidencia de la enfermedad de Creutzfeldt-Jakob esporádica es a los 67 años, aunque se ha observado que también puede ocurrir en individuos desde la adolescencia hasta la vejez. Los blancos no latinos presentan una edad media de inicio más avanzada en comparación con las otras poblaciones étnicas y raciales de Estados Unidos. Los síntomas prodrómicos de la enfermedad priónica pueden incluir fatiga, ansiedad, alteraciones del apetito o el sueño, o problemas de concentración. Después de varias semanas, estos síntomas pueden ir seguidos de incoordinación, visión alterada o anomalías de la marcha u otros movimientos, que pueden ser de tipo mioclónico, coreoatetoide o balísmico, junto con demencia rápidamente progresiva. La enfermedad típicamente progresa muy rápidamente hacia un nivel mayor de deterioro en varios meses. Más raramente puede progresar durante 2 años y parecer similar en su curso a otros trastornos neurocognitivos. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve debido a enfermedad por priones / Desarrollo y curso (p. 722).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Los trastornos neurocognitivos (TNC) mayores y leves existen a lo largo de un espectro de deterioro cognitivo y funcional. ¿Cuál de los siguientes constituye un umbral importante que diferencia los dos diagnósticos?', '["Si el individuo está preocupado por el declive de la función cognitiva.", "Si hay deterioro del rendimiento cognitivo medido con pruebas estandarizadas o la evaluación clínica.", "Si el deterioro cognitivo es suficiente como para interferir en la realización independiente de las actividades de la vida diaria.", "Si los déficits cognitivos ocurren exclusivamente en el contexto de un delirium."]', 2, 'El Criterio B (del TNC mayor y leve) atiende al nivel de independencia del individuo en el funcionamiento diario. Los individuos con TNC mayor tendrán un deterioro de suficiente gravedad como para interferir en su independencia, de manera que otros tendrán que hacerse cargo de ciertas tareas que los individuos antes podían completar por sí mismos. Los individuos con TNC leve tendrán preservada su independencia, aunque puede haber sutiles interferencias en el funcionamiento, o pueden referir que las tareas requieren mayor esfuerzo o más tiempo que antes. La distinción entre TNC mayor y leve es inherentemente arbitraria, y los trastornos existen a lo largo de un continuo. Por lo tanto, es difícil determinar umbrales precisos. Se requiere una cuidadosa anamnesis, observación e integración de la historia con otros hallazgos, y se deben considerar las implicaciones del diagnóstico cuando las manifestaciones clínicas de un individuo se encuentren en un límite. La característica central de los TNC tanto leves como mayores, el Criterio A, requiere evidencia de declive cognitivo basada en 1) la preocupación por parte del paciente, un informante conocedor o un clínico de que ha habido tal declive, y 2) deterioro del rendimiento cognitivo documentado por pruebas neurológicas estandarizadas u otra evaluación objetiva. Para el TNC mayor se especifican declive significativo y deterioro sustancial; para el TNC leve se utilizan las palabras modesto y leve. Se requieren tanto la preocupación como la evidencia objetiva porque son complementarias. Las pruebas neuropsicológicas, con un rendimiento comparado con el normativo apropiado para la edad, el sexo, el nivel de educación y el trasfondo cultural de los individuos, forman parte de la evaluación estandarizada de los TNC y son particularmente críticas en la evaluación del TNC leve. Ambos trastornos pueden ocurrir con delirio comórbido, pero no pueden diagnosticarse si el deterioro cognitivo ocurre solo en el contexto de un delirium (Criterio C). Ambos trastornos pueden ocurrir en pacientes con otros trastornos significativos, pero para hacer el diagnóstico los déficits cognitivos no deben ser principalmente atribuibles a otro trastorno (Criterio D). Referencia: DSM-5-TR, Trastornos neurocognitivos mayores y leves / Criterios diagnósticos (A y B) (pp. 679-680); Características diagnósticas (pp. 685-686).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Expresado en percentiles, ¿cuál es el rendimiento típico en las pruebas neuropsicológicas de los individuos con trastorno neurocognitivo (TNC) mayor?', '["Percentil 60 o inferior.", "Percentil 50 o inferior.", "Percentil 16 o inferior.", "Percentil 3 o inferior."]', 3, 'Las pruebas neuropsicológicas, comparando el rendimiento con el normativo apropiado para la edad, el nivel de educación y el trasfondo cultural del paciente, forman parte de la evaluación estándar de los TNC. En el TNC mayor, el rendimiento típicamente está 2 o más desviaciones estándar por debajo del normal (percentil 3 o inferior). En el TNC leve, el rendimiento típicamente se encuentra en el rango de 1-2 desviaciones estándar (entre los percentiles 3 y 16). Referencia: DSM-5-TR, Trastornos neurocognitivos mayores y leves / Características diagnósticas (p. 685).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Un cardiólogo semirretirado de 68 años con responsabilidad en la interpretación de electrocardiogramas (ECG) en su hospital comunitario es referido por el Programa de Asistencia al Empleado del hospital a una evaluación clínica debido a las preocupaciones expresadas por otros médicos de que ha estado cometiendo muchos errores en sus interpretaciones de ECG durante los últimos meses. El paciente revela síntomas de tristeza persistente desde la muerte de su esposa 6 meses antes de la evaluación, con pensamientos frecuentes de muerte, problemas para dormir y un uso creciente de sedantes-hipnóticos y alcohol. Tiene algunos problemas para concentrarse, pero ha sido capaz de mantener su hogar, pagar sus facturas, hacer la compra y preparar las comidas por sí mismo sin dificultad. Obtiene 28/30 en el miniexamen del estado mental (MEEM). ¿Cuál de las siguientes sería la consideración principal en el diagnóstico diferencial?', '["Trastorno neurocognitivo (TNC) leve.", "Trastorno de adaptación.", "Trastorno de depresión mayor.", "Sin diagnóstico."]', 2, 'No se ha proporcionado suficiente información como para saber con certeza si este paciente cumple los criterios de un diagnóstico específico de trastorno del estado de ánimo o de un diagnóstico de trastorno por consumo de sustancias, pero se puede descartar el TNC mayor. Aunque la puntuación del paciente en el MEEM está dentro del rango normal, sí cumple el Criterio A del TNC mayor, ya que ha surgido la preocupación por el declive de la función cognitiva debido a una mayor tasa de errores en la interpretación de ECG. En cuanto al Criterio B del TNC mayor, el paciente no presenta pérdida de la capacidad de realizar las actividades de la vida diaria de forma independiente y, por lo tanto, no reúne los requisitos diagnósticos del TNC mayor. Cumple el Criterio C, ya que no muestra signos de delirium. El hecho de que sus dificultades se hayan hecho evidentes solo en el contexto de problemas anímicos sugiere fuertemente que un trastorno depresivo y/o por consumo de sustancias podría explicar sus déficits de rendimiento laboral; por lo tanto, es probable que no cumpla el Criterio D del TNC. Aunque podría cumplir el Criterio B del TNC leve, un trastorno del estado de ánimo sería la consideración más prominente en el diagnóstico diferencial. Referencia: DSM-5-TR, Trastornos neurocognitivos mayores y leves / Criterios diagnósticos (pp. 679-680).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Un radiólogo semirretirado de 69 años con responsabilidad en la interpretación de radiografías de tórax en su centro médico académico ha sido referido por el Programa de Asistencia al Empleado del hospital a una evaluación clínica debido a las preocupaciones expresadas por otros médicos de que ha estado cometiendo muchos errores en sus interpretaciones de radiografías durante los últimos meses. La evaluación revela una historia remota de dependencia del alcohol con sobriedad durante los últimos 20 años y un episodio depresivo tras la muerte de su esposa 9 años antes del problema actual, tratado con terapia cognitivo-conductual con resolución completa de los síntomas después de 6 meses y sin recurrencia. Reconoce tener algunos problemas para concentrarse, pero no otros síntomas, y minimiza los supuestos problemas de interpretación de radiografías. No puede indicar la fecha correcta ni el día de la semana y no puede recordar los sucesos de las noticias del día anterior, pero puede describir en gran detalle los momentos destacados de su larga carrera médica. La historia colateral de sus hijos revela que, en varias ocasiones durante el último año, los vecinos de su edificio de apartamentos se habían quejado de que olvidó apagar los fogones mientras cocinaba, lo que llenó de humo el apartamento. Obtiene 21/30 en el miniexamen del estado mental. ¿Qué diagnóstico se ajusta mejor a este cuadro clínico?', '["Trastorno neurocognitivo (TNC) mayor.", "TNC leve.", "Trastorno depresivo mayor.", "Sin diagnóstico."]', 0, 'Existe ya preocupación por el deterioro cognitivo que afecta al funcionamiento de este paciente y su rendimiento en las pruebas es muy anormal, por lo que claramente cumple el Criterio A del TNC mayor. Olvidar controlar lo que se está cocinando en el fogón, hasta el punto de que los vecinos tengan que intervenir debido al humo, es un buen ejemplo de incapacidad para realizar las actividades de la vida diaria de forma independiente, por lo que cumple el Criterio B del TNC mayor en lugar del TNC leve. No está delirando, por lo que cumple el Criterio C. Ni su historia remota de dependencia del alcohol ni su historia remota de depresión explican sus problemas cognitivos y no hay evidencia de otro trastorno mental, por lo que probablemente también cumpla el Criterio D. Referencia: DSM-5-TR, Trastornos neurocognitivos mayores y leves / Criterios diagnósticos (pp. 679-680).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'En un paciente con trastorno neurocognitivo (TNC) leve, ¿cuál de las siguientes opciones distinguiría el Alzheimer probable del posible?', '["Evidencia de una mutación genética causante de la enfermedad de Alzheimer a través de pruebas genéticas o la historia familiar.", "Evidencia clara de disminución de la memoria y el aprendizaje.", "No hay evidencia de etiología mixta.", "Inicio después de los 80 años."]', 0, 'La única forma de diagnosticar un TNC leve debido a una enfermedad de Alzheimer probable es comprobar si hay evidencia de una mutación genética causante de la enfermedad de Alzheimer a través de pruebas genéticas o del historial familiar. El TNC leve debido a una enfermedad de Alzheimer posible se diagnostica por la presencia de todos los criterios clínicos descritos en las opciones B-D anteriores. La edad de inicio no es un criterio diagnóstico. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve debido a la enfermedad de Alzheimer / Criterios diagnósticos (pp. 690-691).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'En el trastorno neurocognitivo frontotemporal mayor o leve, ¿cuál de las siguientes es una característica diagnóstica de la variante de lenguaje?', '["Deterioro marcado de la memoria semántica.", "Deficiencias graves de la función perceptivo-motora.", "Dificultad con la gramática, la búsqueda de palabras o la generación de palabras.", "Hiperoralidad."]', 2, 'El diagnóstico de la variante de lenguaje requiere específicamente un empeoramiento de la función del lenguaje con al menos un respeto relativo del aprendizaje y la memoria y de la función perceptivo-motora. La hiperoralidad es una característica diagnóstica de la variante de déficit conductual. Los signos de la variante de lenguaje o de la variante conductual también pueden ocurrir en pacientes en quienes la otra variante es predominante y el diagnóstico se basaría en las características predominantes. Referencia: DSM-5-TR, Trastorno neurocognitivo frontotemporal mayor o leve / Criterios diagnósticos (pp. 695-69%).'),
('DSM-5-TR', 'Trastornos neurocognitivos', '¿Cuál de los siguientes trastornos neurocognitivos (TNC) se caracteriza especialmente por déficits en dominios como la producción del habla, la búsqueda de palabras, la denominación de objetos o la comprensión de palabras, mientras que la memoria episódica, las habilidades perceptivo-motoras y la función ejecutiva están relativamente preservadas?', '["Trastorno neurocognitivo mayor o leve debido a la enfermedad de Alzheimer.", "Trastorno neurocognitivo mayor o leve con cuerpos de Lewy.", "Trastorno neurocognitivo frontotemporal mayor o leve, variante de comportamiento.", "Trastorno neurocognitivo frontotemporal mayor o leve, variante de lenguaje."]', 3, 'El trastorno neurocognitivo frontotemporal mayor o leve comprende varias variantes sindrómicas caracterizadas por el desarrollo progresivo de cambios en el comportamiento y la personalidad y/o deterioro del lenguaje. La variante conductual y las dos variantes de lenguaje (semántica y agramática/no fluida) exhiben patrones distintos de atrofia cerebral y alguna neuropatología distintiva. Para hacer el diagnóstico se deben cumplir los criterios de la variante conductual o de lenguaje, pero muchos individuos presentan características de ambas. Las personas con trastorno neurocognitivo frontotemporal mayor o leve, variante de lenguaje, presentan afasia progresiva primaria de inicio gradual, con dos subtipos comúnmente descritos (variante semántica y variante agramática/no fluida) y cada variante tiene características distintivas y su neuropatología correspondiente. Una tercera forma de deterioro progresivo del lenguaje, llamada afasia progresiva logopénica, se asocia a disfunción temporoparietal izquierda y a menudo está causada por la patología de la enfermedad de Alzheimer. Las personas con trastorno neurocognitivo frontotemporal mayor o leve, variante conductual, presentan diversos grados de apatía o desinhibición. Pueden perder interés en la socialización, el autocuidado y las responsabilidades personales o mostrar comportamientos socialmente inapropiados. La percepción suele estar deteriorada, y esto a menudo retrasa la consulta médica. La primera derivación suele ser a un psiquiatra. Las personas pueden desarrollar cambios en el estilo social y en las creencias religiosas y políticas, con movimientos repetitivos, acumulación, cambios del comportamiento alimentario e hiperoralidad. En etapas posteriores puede haber pérdida del control de los esfínteres. El deterioro cognitivo es menos prominente y las pruebas formales pueden mostrar relativamente pocos déficits en las primeras etapas. Los síntomas neurocognitivos comunes son la falta de planificación y organización, la distracción y el mal juicio. Los déficits de la función ejecutiva, como el rendimiento deficiente en las pruebas de flexibilidad mental, razonamiento abstracto e inhibición de la respuesta, están presentes, pero el aprendizaje y la memoria están relativamente preservados, y las habilidades perceptivo-motoras casi siempre se conservan en las primeras etapas. Referencia: DSM-5-TR, Trastorno neurocognitivo frontotemporal mayor o leve / Características diagnósticas (pp. 696-697).'),
('DSM-5-TR', 'Trastornos neurocognitivos', '¿Cuál de las siguientes es una característica central del trastorno neurocognitivo mayor o leve con cuerpos de Lewy?', '["Fluctuación cognitiva con variaciones pronunciadas de la atención y la alerta.", "Alucinaciones auditivas recurrentes.", "Cumplimiento de los criterios del trastorno del comportamiento del sueño REM.", "Evidencia de baja captación del transportador de dopamina en los ganglios basales, demostrada por tomografía computarizada de emisión de fotón único (SPECT) o tomografía por emisión de positrones (PET)."]', 0, 'Las alucinaciones visuales bien formadas y recurrentes (no las alucinaciones auditivas) y el parkinsonismo que surge después (no antes) del deterioro cognitivo son las otras características centrales del trastorno neurocognitivo mayor o leve con cuerpos de Lewy. El trastorno del comportamiento del sueño REM y la sensibilidad excesiva a los agentes neurolépticos son características diagnósticas sugerentes; la baja captación del transportador de dopamina en los ganglios basales es un marcador diagnóstico, pero no está incluido en los criterios diagnósticos. Referencia: DSM-5-TR, Trastorno neurocognitivo mayor o leve con cuerpos de Lewy / Criterios diagnósticos; Marcadores diagnósticos (pp. 699-701).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Un hombre de 67 años previamente sano es llevado a la sala de urgencias por su familia. Está experimentando un cambio agudo del estado mental. No hay signos en la historia inicial, el examen físico o los estudios de laboratorio que indiquen intoxicación o abstinencia de sustancias o que sugieran otro problema médico como la causa de su estado mental alterado. Durante el transcurso de 1 hora de observación, su nivel de alerta varía desde alerta pero distraído, con alucinaciones auditivas y visuales aparentes, hasta somnoliento; tiene dificultad para mantener la atención en el examinador y no puede realizar tareas simples como restar en serie o deletrear palabras al revés. ¿Cuál es el diagnóstico más apropiado?', '["Delirium.", "Delirium debido a otra afección médica.", "Delirium debido a una intoxicación con sustancias.", "Delirium no especificado."]', 3, 'Este hombre cumple los criterios de algún tipo de delirium, pero en este punto del curso de su enfermedad todavía no se puede determinar cuál es la causa. La categoría de delirium no especificado puede utilizarse cuando el médico elige no especificar una causa concreta, cuando los criterios diagnósticos del delirium no se cumplen completamente o cuando no se puede determinar el subtipo diagnóstico específico de delirium. Referencia: DSM-5-TR, Delirium no especificado (p. 678).'),
('DSM-5-TR', 'Trastornos neurocognitivos', 'Un hombre de 35 años lleva a su padre de 60 años a una evaluación de deterioro cognitivo y funcional, afirmando que cree que su padre tiene demencia; el hijo también está preocupado por la posibilidad de una enfermedad hereditaria. La médica nota que el paciente tiene un deterioro cognitivo considerable y características sugestivas del diagnóstico de trastorno neurocognitivo mayor debido a la enfermedad de Huntington, pero no está segura de la causa del trastorno neurocognitivo. También nota que el hijo del paciente parece extremadamente ansioso. Tiene una agenda apretada y no puede programar una sesión de asesoramiento para el hijo del paciente hasta el día siguiente. ¿Cuál es el diagnóstico más apropiado a registrar en el formulario para el seguro que el hijo del paciente presentará en nombre de su padre?', '["Trastorno del sistema nervioso central (SNC) no especificado.", "Trastorno neurocognitivo no especificado.", "Trastorno neurocognitivo leve no especificado.", "Enfermedad de Huntington."]', 1, 'La categoría de trastorno neurocognitivo no especificado se aplica a las presentaciones en las que predominan los síntomas característicos de un trastorno neurocognitivo y que causan malestar clínicamente significativo o deterioro en lo social, laboral u otras áreas importantes del funcionamiento, pero sin cumplir todos los criterios de ninguno de los trastornos de la clase diagnóstica de los trastornos neurocognitivos. La categoría de trastorno neurocognitivo no especificado también se utiliza en aquellas situaciones en las que no se puede determinar la etiología precisa con suficiente certeza como para hacer una atribución etiológica. En este caso se sospecha de la enfermedad de Huntington, pero no está demostrada. El trastorno del SNC no especificado no es un diagnóstico del DSM-5 y sería insuficientemente específico para la condición del paciente. La aparente gravedad de los déficits excluye el diagnóstico de trastorno neurocognitivo leve o la designación de código V de problema relacionado con vivir solo. Referencia: DSM-5-TR, Trastorno neurocognitivo no especificado (p. 732).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de los siguientes diagnósticos de trastorno de la personalidad del DSM-IV ya no está presente en el DSM-5-TR?', '["Trastorno antisocial de la personalidad.", "Trastorno de la personalidad por evitación.", "Trastorno límite de la personalidad.", "Trastorno de la personalidad no especificado (NOS)."]', 3, 'Los siguientes trastornos de la personalidad están incluidos en el capítulo "Trastornos de la personalidad" del DSM-5-TR: trastorno de la personalidad paranoide, trastorno de la personalidad esquizoide, trastorno de la personalidad esquizotípica, trastorno de la personalidad antisocial (la opción A es incorrecta), trastorno de la personalidad límite (la opción C es incorrecta), trastorno de la personalidad histriónica, trastorno de la personalidad narcisista, trastorno de la personalidad evitativa (la opción B es incorrecta), trastorno de la personalidad dependiente, trastorno de la personalidad obsesivo-compulsiva, cambio de personalidad debido a otra afección médica, otro trastorno de la personalidad especificado y trastorno de la personalidad no especificado. Por lo tanto, la opción D es correcta. Referencia: DSM-5-TR, Introducción al capítulo (pp. 733-734).'),
('DSM-5-TR', 'Trastornos de la personalidad', 'Mientras colaboran en una presentación para sus clientes, los miembros de un equipo de ventas se frustran cada vez más con su líder de equipo, quien insiste en que los miembros del equipo sigan reglas estrictas para desarrollar el proyecto. Esto implica abordar la tarea de manera secuencial, de modo que no se puede comenzar una nueva tarea hasta que la anterior esté perfeccionada. Cuando otros miembros sugieren enfoques alternativos, el líder se enfada e insiste en que el equipo se apegue a su enfoque. Aunque los resultados son indiscutiblemente de alta calidad, el equipo está convencido de que no terminarán a tiempo para la presentación programada. ¿Cuál de los siguientes trastornos explicaría mejor el comportamiento de este líder de equipo?', '["Trastorno de la personalidad narcisista.", "Trastorno obsesivo-compulsivo (TOC).", "Trastorno de la personalidad esquizoide.", "Trastorno de la personalidad obsesivo-compulsiva (TPOC)."]', 3, 'La característica esencial del TPOC es una preocupación por el orden, el perfeccionismo y el control mental e interpersonal a expensas de la flexibilidad, la apertura y la eficiencia. Las personas con TPOC intentan mantener su sensación de control a través de una atención meticulosa a las reglas, los detalles triviales, los procedimientos, las listas, los horarios o las formas, hasta el punto de perder el objetivo principal de la actividad. Son excesivamente cuidadosas y propensas a la repetición, prestan una atención extraordinaria a los detalles y revisan lo hecho repetidamente en busca de posibles errores, perdiendo la noción del tiempo en el proceso. Pueden obligarse a sí mismas y a los demás a seguir principios morales rígidos y estándares de rendimiento muy estrictos (la opción D es correcta). A pesar de la similitud en los nombres, el TOC suele distinguirse fácilmente del TPOC por la presencia de verdaderas obsesiones y compulsiones en el TOC (la opción B es incorrecta). Las personas con trastorno de la personalidad narcisista también pueden profesar un compromiso con el perfeccionismo y creer que los demás no pueden hacer las cosas tan bien, pero estas personas son más propensas a creer que han alcanzado la perfección, mientras que las personas con TPOC suelen ser autocríticas (la opción A es incorrecta). Tanto el trastorno de la personalidad esquizoide como el TPOC pueden caracterizarse por una aparente formalidad y desapego social. En el TPOC, esto se deriva de la incomodidad con las emociones y de la dedicación excesiva al trabajo, mientras que en el trastorno de la personalidad esquizoide hay una falta fundamental de capacidad para la intimidad (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad obsesivo-compulsiva / Características diagnósticas (pp. 772-773); Diagnóstico diferencial (pp. 774-775).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Por la necesidad de cuál de las siguientes opciones están motivadas principalmente las personas con trastorno de la personalidad obsesivo-compulsiva (TPOC)?', '["Eficiencia.", "Admiración.", "Control.", "Intimidad."]', 2, 'La característica esencial del TPOC es la preocupación por el orden, el perfeccionismo y el control mental y personal (la opción C es correcta) a expensas de la flexibilidad, la apertura y la eficiencia (la opción A es incorrecta). El trastorno de la personalidad narcisista es un patrón de grandiosidad, necesidad de admiración y falta de empatía (la opción B es incorrecta). Tanto el trastorno de la personalidad esquizoide como el TPOC pueden caracterizarse por una aparente formalidad y desapego social. En el TPOC, esto se deriva de la incomodidad con las emociones y de la dedicación excesiva al trabajo, mientras que en el trastorno de la personalidad esquizoide hay una falta fundamental de capacidad para la intimidad (la opción D es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (pp. 733-734); Trastorno de la personalidad obsesivo-compulsiva / Características diagnósticas (pp. 772-773); Diagnóstico diferencial (pp. 774-775).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de los siguientes hallazgos descartaría el diagnóstico de trastorno de la personalidad obsesivo-compulsiva (TPOC)?', '["Un diagnóstico concurrente de trastorno obsesivo-compulsivo (TOC).", "Un diagnóstico concurrente de trastorno de acumulación.", "Un diagnóstico concurrente de trastorno de la personalidad narcisista.", "Evidencia de que los patrones de comportamiento reflejan estilos interpersonales culturalmente sancionados."]', 3, 'Al evaluar a un individuo para ver si tiene TPOC, el clínico no debe incluir comportamientos que reflejen hábitos, costumbres o estilos interpersonales que estén culturalmente sancionados por el grupo de referencia del individuo. Tales comportamientos no deben considerarse indicaciones de TPOC por sí solos (la opción D es correcta). Cuando se cumplen los criterios del TPOC y el TOC, ambos diagnósticos deben registrarse (la opción A es incorrecta). De manera similar, cuando se cumplen los criterios del TPOC y del trastorno de acumulación, ambos diagnósticos deben registrarse (la opción B es incorrecta). Si un individuo tiene características de personalidad que cumplen los criterios de uno o más trastornos de la personalidad además del TPOC, todos pueden diagnosticarse (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad obsesivo-compulsiva / Aspectos diagnósticos relacionados con la cultura (p. 774); Diagnóstico diferencial (pp. 774-775).'),
('DSM-5-TR', 'Trastornos de la personalidad', 'A pesar de trabajar en una empresa durante muchos años, una empleada de 36 años no ha avanzado más allá de un puesto de nivel inicial. Recibe buenas críticas y trabaja muchas horas, pero no ha pedido un ascenso porque siente que no es tan buena como otros empleados y, por lo tanto, no merece ser promovida. Explica que trabaja muchas horas porque no es muy inteligente y necesita revisar todo su trabajo porque teme que la gente se burle de cualquier error. ¿Cuál de los siguientes trastornos de la personalidad explicaría mejor la falta de avance laboral de esta mujer?', '["Trastorno de la personalidad dependiente.", "Trastorno de la personalidad evitativa.", "Trastorno paranoide.", "Trastorno de la personalidad esquizoide."]', 1, 'La característica esencial del trastorno de la personalidad evitativa es un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa que comienza en la juventud y se manifiesta en distintos contextos. Las ofertas de promoción laboral pueden rechazarse porque no lograr manejar las nuevas responsabilidades podría dar lugar a críticas de los compañeros de trabajo (la opción B es correcta). Tanto el trastorno de la personalidad evitativa como el trastorno de la personalidad dependiente se caracterizan por sentimientos de insuficiencia, hipersensibilidad a la crítica y necesidad de consuelo. Comportamientos similares (por ejemplo, falta de asertividad) y atributos parecidos (por ejemplo, baja autoestima y baja confianza en uno mismo) pueden observarse tanto en el trastorno de la personalidad dependiente como en el trastorno de la personalidad evitativa, aunque otros comportamientos son notablemente divergentes, como la evitación de la proximidad social en el trastorno de la personalidad evitativa y la búsqueda de la proximidad en el trastorno de la personalidad dependiente. Las motivaciones de comportamientos similares pueden ser bastante diferentes. Por ejemplo, la falta de asertividad en el trastorno de la personalidad evitativa se describe como más íntimamente relacionada con el miedo a ser rechazado o humillado, mientras que en el trastorno de la personalidad dependiente está motivada por el deseo de evitar tener que valerse por uno mismo (la opción A es incorrecta). Al igual que el trastorno de la personalidad evitativa, los trastornos de la personalidad esquizoide y esquizotípica se caracterizan por el aislamiento social. Sin embargo, las personas con trastorno de la personalidad evitativa quieren tener relaciones con otros y sienten su soledad profundamente, mientras que aquellas con trastorno de la personalidad esquizoide o esquizotípica pueden estar contentas e incluso preferir su aislamiento social (la opción D es incorrecta). El trastorno de la personalidad paranoide y el trastorno de la personalidad por evitación se caracterizan ambos por la renuencia a confiar en los demás. Sin embargo, en el trastorno de la personalidad por evitación, esta renuencia se atribuye más al miedo a la humillación o a ser considerado deficiente que a un miedo a la intención maliciosa de los demás (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad evitativa / Características diagnósticas (p. 765) / Diagnóstico diferencial (p. 767).'),
('DSM-5-TR', 'Trastornos de la personalidad', 'Una cardióloga solicita una consulta psiquiátrica para su paciente, un hombre de 46 años, debido a que "parece un loco". En la evaluación, el paciente evita el contacto visual, tiende a divagar y utiliza palabras inusuales. Va modestamente desaliñado y viste ropa de colores que no combinan. Expresa creencias extrañas en fenómenos sobrenaturales, pero estas creencias no parecen ser de intensidad delirante. La información de un hermano revela que el paciente "siempre ha sido así: raro, solitario y le gusta ser así". ¿Cuál de las siguientes afecciones explica mejor los comportamientos y creencias extrañas de este paciente?', '["Trastorno de la personalidad esquizoide.", "Trastorno de la personalidad esquizotípica.", "Trastorno delirante.", "Esquizofrenia."]', 1, 'La característica esencial del trastorno de la personalidad esquizotípica es la presencia de déficits sociales e interpersonales generalizados, marcados por gran incomodidad y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento. Los individuos con personalidad esquizotípica a menudo se consideran extraños o excéntricos debido a sus manierismos inusuales, una forma de vestir a menudo descuidada que no encaja del todo y falta de atención a las convenciones sociales habituales. Experimentan las relaciones interpersonales como problemáticas y se sienten incómodos al relacionarse con otras personas (la opción B es correcta). Estas personas a menudo tienen ideas de referencia (es decir, interpretaciones incorrectas de incidentes casuales y eventos externos, como si tuvieran un significado particular e inusual específico para la persona) (Criterio A1). Las ideas de referencia deben distinguirse de los delirios de referencia, en los que las creencias se mantienen con convicción delirante. Las personas con trastorno de la personalidad esquizotípica pueden ser supersticiosas o preocuparse por fenómenos paranormales que están fuera de las normas de su subcultura (Criterio A?). El trastorno de la personalidad esquizotípica se puede distinguir del trastorno delirante, la esquizofrenia y el trastorno bipolar o depresivo con características psicóticas porque todos estos trastornos se caracterizan por un período de síntomas psicóticos persistentes (por ejemplo, delirios y alucinaciones). Para dar un diagnóstico de trastorno de la personalidad esquizotípica, el trastorno de la personalidad debe haber estado presente antes del inicio de los síntomas psicóticos y persistir cuando los síntomas psicóticos están en remisión (las opciones C y D son incorrectas). Aunque el trastorno de la personalidad esquizoide también puede caracterizarse por el desapego social y la afectividad restringida, el trastorno de la personalidad esquizotípica se puede distinguir de este diagnóstico por la presencia de distorsiones cognitivas o perceptivas y de excentricidad o rareza marcadas (la opción A es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad esquizotípica / Características diagnósticas (pp. 745-746) / Diagnóstico diferencial (pp. 747-748).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes afirmaciones describe más exactamente el desarrollo, el curso y el pronóstico del trastorno de la personalidad límite (TPL)?', '["Los intentos de suicidio aumentan con la edad.", "Los antecedentes de negligencia en la infancia, en lugar de abusos, son inusuales.", "Los estudios de seguimiento prospectivo han encontrado que las remisiones estables de hasta 8 años son muy comunes.", "Los síntomas afectivos remiten más rápidamente que los síntomas impulsivos."]', 2, 'Durante mucho tiempo se ha considerado que el TPL es un trastorno de mala evolución sintomática que tiende a disminuir en cuanto a su gravedad a medida que las personas con TPL entran en la treintena o la cuarentena. Sin embargo, los estudios de seguimiento prospectivo han encontrado que las remisiones estables de 1a8 años son muy comunes (la opción C es correcta). Un estudio de individuos con TPL seguidos durante 10 años encontró que el comportamiento suicida recurrente era una característica definitoria del TPL, asociada a tasas decrecientes de intentos de suicidio, del 79 al 13%, con el tiempo (la opción A es incorrecta). Se ha encontrado que el TPL se asocia a altas tasas de diversas formas de abusos en la infancia y a negligencia emocional (la opción B es incorrecta). Los síntomas impulsivos del TPL remiten más rápidamente, mientras que los síntomas afectivos remiten a un ritmo sustancialmente más lento (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad límite / Desarrollo y curso (p. 755); Factores de riesgo y pronóstico (p. 755); Asociación a pensamientos o conductas suicidas (p. 756).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes es una característica del trastorno de la personalidad narcisista (TPN?', '["Necesidad de mucha atención de cualquier tipo.", "Agresividad impulsiva y engaño.", "Inmersión en el perfeccionismo relacionado con el orden y la rigidez.", "Un patrón generalizado de grandiosidad."]', 3, 'La característica esencial del TPN es un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía que comienza en la juventud y se manifiesta en varios contextos (la opción D es correcta). Aunque las personas con trastorno de la personalidad límite, histriónica o narcisista pueden requerir mucha atención, aquellas con TPN específicamente necesitan que esa atención sea admirativa (la opción A es incorrecta). Las personas con trastorno de la personalidad antisocial o narcisista comparten la tendencia a ser duros, elocuentes, superficiales, explotadores y carentes de empatía. Sin embargo, el TPN no necesariamente incluye características de agresividad impulsiva y engaño (la opción B es incorrecta). Tanto en el TPN como en el trastorno de la personalidad obsesivo-compulsiva, el individuo puede estar comprometido con el perfeccionismo y creer que los demás no pueden hacer las cosas tan bien. Sin embargo, mientras que aquellos con trastorno de la personalidad obsesivo-compulsiva tienden a estar más inmersos en el perfeccionismo relacionado con el orden y la rigidez, las personas con TPN tienden a establecer altos estándares perfeccionistas, especialmente con respecto a la apariencia y el rendimiento, y a estar críticamente preocupadas si no están a la altura (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad narcisista / Características diagnósticas (pp. 761-762); Diagnóstico diferencial (pp. 763-764).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuáles las siguientes alteraciones cognitivas o perceptivas es más característica del trastorno de la personalidad límite (TPL)?', '["Respuestas excesivamente concretas o excesivamente abstractas.", "Ideas de referencia.", "Superstición o preocupación por fenómenos paranormales.", "Ideas paranoides transitorias durante períodos de estrés."]', 3, 'Durante los períodos de estrés extremo pueden surgir ideas paranoides transitorias o síntomas disociativos (por ejemplo, despersonalización) (Criterio 9), pero generalmente son de gravedad o duración insuficientes como para justificar un diagnóstico adicional. Las ideas paranoides o las ilusiones pueden estar presentes tanto en el TPL como en el trastorno de la personalidad esquizotípica, pero estos síntomas son más transitorios, reactivos interpersonalmente y receptivos a la estructuración externa en el TPL. Las personas con trastorno de la personalidad esquizotípica a menudo tienen ideas de referencia (la opción B es incorrecta). Estos individuos pueden ser supersticiosos o estar preocupados por fenómenos paranormales que están fuera de las normas de su subcultura (la opción C es incorrecta). Las respuestas pueden ser excesivamente concretas o excesivamente abstractas (la opción A es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Diagnóstico diferencial (pp. 756-757); Trastorno de la personalidad esquizotípica / Características diagnósticas (pp. 745-746).'),
('DSM-5-TR', 'Trastornos de la personalidad', 'Un guardia de seguridad de almacén de 43 años acude a la consulta quejándose de vagos sentimientos de depresión durante los últimos meses, sin ninguna sensación especial de miedo o ansiedad. Siente poco deseo de relacionarse, pero nota que sus compañeros de trabajo parecen más felices y tienen muchas relaciones. Nunca se ha sentido cómodo con otras personas, ni siquiera con la familia. Ha vivido solo desde la juventud y es autosuficiente. Casi siempre trabaja en turnos nocturnos para evitar interacciones con otras personas. Intenta mantener un perfil bajo y pasar desapercibido para desalentar a los demás a iniciar conversaciones. El examen del estado mental es notable por un afecto significativamente constreñido y sin emociones. No se presentan alteraciones cognitivas o perceptivas. ¿Qué trastorno de la personalidad encajaría mejor con esta presentación?', '["Paranoide.", "Esquizoide.", "Esquizotípica.", "Evitativa."]', 1, 'La característica esencial del trastorno de la personalidad esquizoide es un patrón generalizado de desapego de las relaciones sociales y un rango restringido de emociones en los entornos interpersonales. Las personas con trastorno de la personalidad esquizoide parecen carecer de deseo de intimidad, parecen indiferentes a las oportunidades de desarrollar relaciones cercanas y no parecen obtener mucha satisfacción de ser parte de una familia u otro grupo social (Criterio A1; la opción B es correcta). Aunque las características de aislamiento social y afectividad restringida son comunes a los trastornos de la personalidad esquizoide, esquizotípica y paranoide, el trastorno de la personalidad esquizoide se puede distinguir del trastorno de la personalidad esquizotípica por la falta de distorsiones cognitivas y perceptivas, y del trastorno de la personalidad paranoide por la falta de sospechas e ideación paranoide (las opciones A y C son incorrectas). El aislamiento social del trastorno de la personalidad esquizoide se puede distinguir del que se observa en el trastorno de la personalidad evitativa en que este se atribuye al miedo a sentirse avergonzado o deficiente y a la excesiva anticipación del rechazo. En cambio, las personas con trastorno de la personalidad esquizoide tienen un desapego más generalizado y un deseo limitado de intimidad social (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad esquizoide / Características diagnósticas (p. 742); Diagnóstico diferencial (pp. 743-744).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de los siguientes comportamientos o estados sería menos probable que ocurriera en una persona con trastorno de la personalidad esquizoide?', '["Un estallido de ira hacia un colega que critica su trabajo.", "Rechazar una invitación a una fiesta.", "Falta de deseo de experiencias sexuales.", "Ir a la deriva con respecto a las metas de la vida."]', 0, 'La característica esencial del trastorno de la personalidad esquizoide es un patrón generalizado de desapego de las relaciones sociales y un rango restringido de emociones en los entornos interpersonales. Las personas con trastorno de la personalidad esquizoide pueden tener especial dificultad para expresar la ira, incluso en respuesta a una provocación directa, lo que contribuye a la impresión de que carecen de emoción (la opción A es correcta). Prefieren pasar tiempo solos en lugar de estar con otras personas. A menudo parecen estar socialmente aislados o ser "solitarios" y casi siempre eligen actividades o pasatiempos solitarios que no incluyen la interacción con otros (Criterio A2; la opción B es incorrecta). El Criterio A3 establece que las personas con trastorno de la personalidad esquizoide pueden tener poco o ningún interés en tener experiencias sexuales con otras personas (la opción C es incorrecta). Sus vidas a veces parecen carecer de dirección y puede parecer que "se dejan llevar a la deriva" en relación con sus metas (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad esquizoide / Criterios diagnósticos (pp. 741-742); Características diagnósticas (p. 742).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál es la relación entre un historial de trastorno de la conducta antes de los 15 años y el diagnóstico de personalidad antisocial después de los 18 años?', '["Un historial de algunos síntomas de trastorno de la conducta antes de los 15 años es uno de los criterios requeridos para el diagnóstico del trastorno de la personalidad antisocial en la adultez.", "El inicio del trastorno de la conducta en la infancia no tiene relación con la probabilidad de desarrollar un trastorno de la personalidad antisocial en la vida adulta.", "Tanto el trastorno de la personalidad antisocial como el trastorno de la conducta pueden diagnosticarse antes de los 18 años.", "Tanto el trastorno de la personalidad antisocial como el trastorno de la conducta pueden diagnosticarse en individuos mayores de 18 años."]', 0, 'La característica esencial del trastorno de la personalidad antisocial es un patrón generalizado de desprecio y violación de los derechos de los demás que comienza en la infancia o en la adolescencia temprana y continúa en la adultez. El Criterio C del diagnóstico de trastorno de la personalidad antisocial requiere específicamente evidencia de un trastorno de la conducta con inicio antes de los 15 años (la opción A es correcta). La probabilidad de desarrollar el trastorno de la personalidad antisocial en la vida adulta se incrementa si el individuo experimentó el inicio del trastorno de la conducta en la infancia (antes de los 10 años) y tenía un trastorno de déficit de atención/hiperactividad acompañante (la opción B es incorrecta). Por definición, el trastorno de la personalidad antisocial no puede diagnosticarse antes de los 18 años (la opción C es incorrecta). En los individuos mayores de 18 años, el diagnóstico de trastorno de la conducta solo se realiza si no se cumplen los criterios del trastorno de la personalidad antisocial (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad antisocial / Criterios diagnósticos (p. 748); Características diagnósticas (pp. 748-749); Desarrollo y curso (p. 750); Diagnóstico diferencial (pp. 751-752); Comorbilidad (p. 752).'),
('DSM-5-TR', 'Trastornos de la personalidad', 'Un paciente de 25 años tiene una historia infantil de repetidos casos de tortura a animales, incendios provocados, robos, fugas de casa y absentismo escolar, comenzando a los 9 años. Como adulto, miente repetidamente a los demás; participa en pequeños robos, estafas y peleas frecuentes (incluyendo episodios en que usa los objetos que tiene a mano -llaves de tubo, sillas, cuchillos de carne para herir a otros), y usa alias para evitar pagar la manutención de sus hijos. No hay antecedentes de síntomas maníacos, depresivos o psicóticos. El paciente viste ropa cara y muestra un reloj de pulsera caro por el que exige admiración. Expresa sentimientos de ser especial y de tener derechos especiales, y admite que cree merecer la exención de las reglas ordinarias, así como sentimientos de ira porque sus talentos especiales no han sido adecuadamente reconocidos por los demás. Infravalora, desprecia y carece de empatía hacia los demás y no siente remordimiento por sus comportamientos. No hay signos de psicosis. ¿Cuál es el diagnóstico apropiado según el DSM-5-TR?', '["Trastorno de la personalidad antisocial.", "Trastorno de la personalidad narcisista.", "Trastorno de la personalidad antisocial y trastorno de la personalidad narcisista.", "Otro trastorno de la personalidad especificado (características de personalidad mixtas)."]', 2, 'Este individuo cumple los criterios diagnósticos del trastorno de la personalidad antisocial. El Criterio A especifica un patrón generalizado de desprecio y violación de los derechos de los demás, que ocurre desde los 15 años, indicado por tres (o más) de los siguientes: 1) no sigue las normas sociales con respecto a los comportamientos legales; 2) engaños; 3) impulsividad o ausencia de planificación previa; 4) irritabilidad y agresividad; 5) desprecio imprudente por la seguridad de uno mismo o de los demás; 6) irresponsabilidad constante, y 7) falta de remordimiento. Este comportamiento antisocial no ocurre exclusivamente durante el curso de la esquizofrenia o el trastorno bipolar (Criterio D). El individuo tiene al menos 18 años (Criterio B) y hay evidencia de un trastorno de la conducta con inicio antes de los 15 años (Criterio C). El paciente también cumple los criterios diagnósticos del trastorno de la personalidad narcisista: un patrón generalizado de grandiosidad (en fantasía o comportamiento), necesidad de admiración y falta de empatía que comienza en la juventud y se presenta en varios contextos (Criterio A), indicado por cinco (o más) de los siguientes: 1) sentido grandioso de autoimportancia; 2) dedicación a fantasías de éxito ilimitado, poder, brillantez, belleza o amor ideal; 3) creencia de ser "especial" y único y de que solo puede ser entendido por, o debería asociarse con, otras personas especiales o de alto estatus (o instituciones); 4) necesidad de admiración excesiva; 5) sentido de privilegio; 6) explotación interpersonal de los demás; 7) falta de empatía; 8) envidia de los demás o creencia de que los demás le envidian, y 9) comportamientos o actitudes arrogantes y altivos. El trastorno de la personalidad narcisista puede confundirse con el trastorno de la personalidad antisocial porque ambos trastornos tienen ciertas características en común. Por lo tanto, es importante distinguir entre ellos según las diferencias existentes entre sus características distintivas. Sin embargo, si un individuo tiene características de personalidad que cumplen os criterios de uno o más trastornos de la personalidad además del trastorno de la personalidad antisocial, todos pueden diagnosticarse. Las personas con trastorno de la personalidad antisocial y trastorno de la personalidad narcisista comparten cierta tendencia a ser duros de mente, elocuentes, superficiales y explotadores, y a carecer de empatía. Debido a que este paciente cumple los criterios diagnósticos de ambos trastornos de la personalidad, la opción C es correcta. La categoría otro trastorno de la personalidad especificado se aplica a las presentaciones en que predominan síntomas característicos de un trastorno de la personalidad que causan malestar o deterioro clínicamente significativos en el funcionamiento social, ocupacional u otras áreas importantes del funcionamiento, pero sin cumplir los criterios completos de ninguno de los trastornos de la clase diagnóstica de los trastornos de la personalidad. La categoría otro trastorno de la personalidad especificado se utiliza en aquellas situaciones en las que el clínico elige comunicar la razón específica por la que la presentación no cumple los criterios de ningún trastorno de la personalidad específico. Esto se hace registrando "otro trastorno de la personalidad especificado" seguido de la razón específica (por ejemplo, "características de personalidad mixtas") (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad antisocial / Criterios diagnósticos (p. 748); Diagnóstico diferencial (pp. 751-752); Trastorno de la personalidad narcisista / Criterios diagnósticos (p. 760); Otro trastorno de la personalidad especificado (p. 778).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de los siguientes es uno de los criterios generales del trastorno de la personalidad en el DSM-5-TR?', '["El patrón de experiencia interna se desvía notablemente de las expectativas de la cultura del individuo.", "El patrón de experiencia interna es flexible y se limita a una única situación personal o social.", "El patrón de experiencia interna es fluctuante y de corta duración.", "El patrón de experiencia interna es egosintónico y no provoca malestar."]', 0, 'Un trastorno de la personalidad es un patrón duradero de experiencia interna y comportamiento que se desvía notablemente de las expectativas de la cultura del individuo, es generalizado e inflexible (la opción B es incorrecta), tiene su inicio en la adolescencia o la juventud, es estable en el tiempo (la opción C es incorrecta) y produce malestar o deterioro (la opción D es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (pp. 733-734).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad histriónica?', '["Una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación.", "Un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada.", "Un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía.", "Un patrón generalizado de excesiva emotividad y búsqueda de atención."]', 3, 'La característica esencial del trastorno de la personalidad histriónica es una emotividad generalizada y excesiva y un comportamiento de búsqueda de atención (la opción D es correcta). La característica esencial del trastorno de la personalidad límite es un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos e impulsividad marcada (la opción B es incorrecta). La característica esencial del trastorno de la personalidad narcisista es un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía (la opción C es incorrecta). La característica esencial del trastorno de la personalidad dependiente es una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación (la opción A es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad histriónica / Características diagnósticas (pp. 757-758); Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Trastorno de la personalidad narcisista / Características diagnósticas (pp. 761-762); Trastorno de la personalidad dependiente / Características diagnósticas (pp. 768-769).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad límite?', '["Una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación.", "Un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada.", "Un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía.", "Emotividad generalizada y excesiva, y búsqueda de atención."]', 1, 'La característica esencial del trastorno de la personalidad límite es un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos e impulsividad marcada (la opción B es correcta). La característica esencial del trastorno de la personalidad dependiente es una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación (la opción A es incorrecta). La característica esencial del trastorno de la personalidad narcisista es un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía (la opción C es incorrecta). La característica esencial del trastorno de la personalidad histriónica es una emotividad generalizada y excesiva, y un comportamiento de búsqueda de atención (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Trastorno de la personalidad histriónica / Características diagnósticas (pp. 757-758); Trastorno de la personalidad narcisista / Características diagnósticas (pp. 761-762); Trastorno de la personalidad dependiente / Características diagnósticas (pp. 768-769).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad dependiente?', '["Una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación.", "Un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada.", "Un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía.", "Un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa."]', 0, 'La característica esencial del trastorno de la personalidad dependiente es una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación (la opción A es correcta). La característica esencial del trastorno de la personalidad límite es un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos e impulsividad marcada (la opción B es incorrecta). La característica esencial del trastorno de la personalidad narcisista es un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía (la opción C es incorrecta). La característica esencial del trastorno de la personalidad evitativa es un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad dependiente / Características diagnósticas (pp. 768-769); Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Trastorno de la personalidad narcisista / Características diagnósticas (pp. 761-762); Trastorno de la personalidad evitativa / Características diagnósticas (p. 765).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad evitativa?', '["Un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa.", "Un patrón generalizado de déficits sociales e interpersonales marcados por malestar agudo y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento.", "Una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación.", "Un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada."]', 0, 'La característica esencial del trastorno de la personalidad evitativa es un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa (la opción A es correcta). La característica esencial del trastorno de la personalidad esquizotípica es un patrón generalizado de déficits sociales e interpersonales marcados por malestar agudo y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento (la opción B es incorrecta). La característica esencial del trastorno de la personalidad dependiente es una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación (la opción C es correcta). La característica esencial del trastorno de la personalidad límite es un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos e impulsividad marcada (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad evitativa / Características diagnósticas (p. 765); Trastorno de la personalidad esquizotípica / Características diagnósticas (pp. 745-746); Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Trastorno de la personalidad dependiente / Características diagnósticas (pp. 768-769).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad esquizotípica?', '["Un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa.", "Un patrón generalizado de déficits sociales e interpersonales marcados por malestar agudo y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento.", "Una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y a miedo a la separación.", "Un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada."]', 1, 'La característica esencial del trastorno de la personalidad esquizotípica es un patrón generalizado de déficits sociales e interpersonales marcados por malestar agudo y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento (la opción B es correcta). La característica esencial del trastorno de la personalidad evitativa es un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa (la opción A es incorrecta). La característica esencial del trastorno de la personalidad dependiente es una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación (la opción C es incorrecta). La característica esencial del trastorno de la personalidad límite es un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad esquizotípica / Características diagnósticas (pp. 745-746); Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Trastorno de la personalidad evitativa / Características diagnósticas (p. 765); Trastorno de la personalidad dependiente / Características diagnósticas (pp. 768-769).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad paranoide?', '["Un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa.", "Un patrón de desconfianza y sospecha generalizado hacia los demás de manera que sus motivos se interpretan como malintencionados.", "Una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación.", "Un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada."]', 1, 'La característica esencial del trastorno de la personalidad paranoide es un patrón de desconfianza y sospecha generalizado hacia los demás de manera que sus motivos se interpretan como malintencionados (la opción B es correcta). La característica esencial del trastorno de la personalidad evitativa es un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa (la opción A es incorrecta). La característica esencial del trastorno de la personalidad dependiente es una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación (la opción C es incorrecta). La característica esencial del trastorno de la personalidad límite es un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos e impulsividad marcada (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad paranoide / Características diagnósticas (pp. 738-739); Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Trastorno de la personalidad evitativa / Características diagnósticas (p. 765); Trastorno de la personalidad dependiente / Características diagnósticas (pp. 768-769).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad narcisista?', '["Un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa.", "Una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación.", "Un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada.", "Un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía."]', 3, 'La característica esencial del trastorno de personalidad narcisista es un patrón generalizado de grandiosidad, necesidad de admiración y falta de empatía (la opción D es correcta). La característica esencial del trastorno de la personalidad evitativa es un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa (la opción A es incorrecta). La característica esencial del trastorno de la personalidad dependiente es una necesidad generalizada y excesiva de ser cuidado que conduce a un comportamiento sumiso y dependiente, y miedo a la separación (la opción B es incorrecta). La característica esencial del trastorno de la personalidad límite es un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad narcisista / Características diagnósticas (pp. 761-762); Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Trastorno de la personalidad evitativa / Características diagnósticas (p. 765); Trastorno de la personalidad dependiente / Características diagnósticas (pp. 768-769).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad esquizoide?', '["Un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa.", "Un patrón generalizado de déficits sociales e interpersonales marcado por malestar agudo y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento.", "Un patrón generalizado de distanciamiento de las relaciones sociales y una gama restringida de expresiones emocionales en los entornos interpersonales.", "Un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada."]', 2, 'La característica esencial del trastorno de la personalidad esquizoide es un patrón generalizado de distanciamiento de las relaciones sociales y una gama restringida de expresiones emocionales en los entornos interpersonales (la opción C es correcta). La característica esencial del trastorno de la personalidad esquizotípica es un patrón generalizado de déficits sociales e interpersonales marcado por malestar agudo y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento (la opción B es incorrecta). La característica esencial del trastorno de la personalidad evitativa es un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa (la opción A es incorrecta). La característica esencial del trastorno de la personalidad límite es un patrón generalizado de inestabilidad en las relaciones interpersonales, la autoimagen y los afectos, e impulsividad marcada (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad esquizoide / Características diagnósticas (p. 742); Trastorno de la personalidad esquizotípica / Características diagnósticas (pp. 745-746); Trastorno de la personalidad límite / Características diagnósticas (pp. 753-754); Trastorno de la personalidad evitativa / Características diagnósticas (p. 765).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad antisocial?', '["Preocupación por el orden, el perfeccionismo y el control mental e interpersonal a expensas de la flexibilidad, la apertura y la eficiencia.", "Un patrón generalizado de distanciamiento de las relaciones sociales y una gama restringida de expresiones emocionales en los entornos interpersonales.", "Un patrón de desconfianza y sospecha generalizado hacia los demás de manera que sus motivos se interpretan como malintencionados.", "Un patrón generalizado de desprecio y violación de los derechos de los demás."]', 3, 'La característica esencial del trastorno de la personalidad antisocial es un patrón generalizado de desprecio y violación de los derechos de los demás (la opción D es correcta). La característica esencial del trastorno de la personalidad obsesivo-compulsiva es una preocupación por el orden, el perfeccionismo y el control mental e interpersonal a expensas de la flexibilidad, la apertura y la eficiencia (la opción A es incorrecta). La característica esencial del trastorno de la personalidad esquizoide es un patrón generalizado de distanciamiento de las relaciones sociales y una gama restringida de expresiones emocionales en los entornos interpersonales (la opción B es incorrecta). La característica esencial del trastorno de la personalidad paranoide es un patrón de desconfianza y sospecha generalizado hacia los demás de manera que sus motivos se interpretan como malintencionados (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad antisocial / Características diagnósticas (pp. 748-749); Trastorno de la personalidad paranoide / Características diagnósticas (pp. 738-739); Trastorno de la personalidad esquizoide / Características diagnósticas (p. 742); Trastorno de la personalidad obsesivo-compulsiva / Características diagnósticas (pp. 772-773).'),
('DSM-5-TR', 'Trastornos de la personalidad', '¿Cuál de las siguientes presentaciones es característica del trastorno de la personalidad obsesivo-compulsiva?', '["Un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa.", "Un patrón generalizado de déficits sociales e interpersonales marcado por malestar agudo y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento.", "Preocupación por el orden, el perfeccionismo y el control mental e interpersonal a expensas de la flexibilidad, la apertura y la eficiencia.", "Un patrón generalizado de distanciamiento de las relaciones sociales y una gama restringida de expresiones emocionales en los entornos interpersonales."]', 2, 'La característica esencial del trastorno de la personalidad obsesivo-compulsiva es la preocupación por el orden, el perfeccionismo y el control mental e interpersonal a expensas de la flexibilidad, la apertura y la eficiencia (la opción C es correcta). La característica esencial del trastorno de la personalidad evitativa es un patrón generalizado de inhibición social, sentimientos de insuficiencia e hipersensibilidad a la evaluación negativa (la opción A es incorrecta). La característica esencial del trastorno de la personalidad esquizotípica es un patrón generalizado de déficits sociales e interpersonales marcado por malestar agudo y capacidad reducida para las relaciones cercanas, así como por distorsiones cognitivas o perceptivas y excentricidades en el comportamiento (la opción B es incorrecta). La característica esencial del trastorno de la personalidad esquizoide es un patrón generalizado de distanciamiento de las relaciones sociales y una gama restringida de expresiones emocionales en los entornos interpersonales (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad obsesivo-compulsiva / Características diagnósticas (pp. 772-773); Trastorno de la personalidad esquizoide / Características diagnósticas (p. 742); Trastorno de la personalidad esquizotípica / Características diagnósticas (pp. 745-746); Trastorno de la personalidad evitativa / Características diagnósticas (p. 765).'),
('DSM-5-TR', 'Trastornos parafílicos', '¿Cuál de las siguientes no es una clasificación de los trastornos parafílicos en el DSM-5-TR?', '["Preferencias de actividad anómalas.", "Trastornos del cortejo.", "Trastornos algolágnicos.", "Trastornos asincrónicos."]', 3, 'En este capítulo, el orden de presentación de los trastornos parafílicos que se describen corresponde en general al de los habituales esquemas de clasificación de estas afecciones. El primer grupo de trastornos se basa en las preferencias de actividad anómalas. Estos trastornos se subdividen en trastornos del cortejo, que se asemejan a componentes distorsionados del comportamiento humano de cortejo (trastornos de voyeurismo, de exhibicionismo y de frotteurismo), y trastornos algolágnicos, que implican dolor y sufrimiento (trastorno de masoquismo sexual y trastorno de sadismo sexual). El segundo grupo de trastornos se basa en preferencias de objetivo anómalas. Estos trastornos incluyen uno dirigido a otros seres humanos (trastorno de pedofilia) y dos dirigidos a otros objetos (trastorno de fetichismo y trastorno de travestismo). No existe ningún esquema de clasificación de trastornos asincrónicos. Referencia: DSM-5-TR, Introducción del capítulo (p. 779).'),
('DSM-5-TR', 'Trastornos parafílicos', '¿Cuál de las siguientes afirmaciones no es cierta sobre las parafilias?', '["La presencia de una parafilia no siempre justifica la intervención clínica.", "La mayoría de las parafilias se pueden dividir en aquellas que implican una actividad inusual y aquellas que implican un objetivo inusual.", "Las parafilias pueden coexistir con intereses sexuales normofílicos.", "Es raro que un individuo manifieste más de una parafilia."]', 3, 'El término parafilia denota cualquier interés sexual intenso y persistente distinto del interés sexual por la estimulación genital o las caricias preparatorias con parejas humanas fenotípicamente normales, físicamente maduras y consentidoras. En algunas circunstancias, los criterios intenso y persistente pueden ser difíciles de aplicar, como en la evaluación de las personas muy mayores o enfermas que quizá no tengan intereses sexuales "intensos" de ningún tipo. En tales circunstancias, el término parafilia puede definirse como cualquier interés sexual mayor o igual que los intereses sexuales no parafílicos. También hay parafilias específicas que generalmente se describen mejor como intereses sexuales preferenciales que como intereses sexuales intensos. No es raro que un individuo manifieste dos o más parafilias. En algunos casos, los focos parafílicos están estrechamente relacionados y la conexión entre las parafilias es intuitivamente comprensible (por ejemplo, fetichismo de pies y fetichismo de zapatos). En otros casos, la conexión entre las parafilias no es obvia y la presencia de múltiples parafilias puede ser coincidente o estar relacionada con alguna vulnerabilidad generalizada a las anomalías del desarrollo psicosexual. En cualquier caso, pueden justificarse los diagnósticos separados de trastornos parafílicos concurrentes si hay más de una parafilia que esté causando sufrimiento al individuo o daño a terceros. Referencia: DSM-5-TR, Introducción del capítulo (p. 779).'),
('DSM-5-TR', 'Trastornos parafílicos', '¿Cuál de los siguientes no es un trastorno parafílico?', '["Trastorno de masoquismo sexual.", "Trastorno de travestismo.", "Trastorno transexual.", "Trastorno de voyeurismo."]', 2, 'El transexualismo no es un trastorno y no está incluido en el capítulo de "Trastornos parafílicos" del DSM-5-TR. Transexual, término histórico, denota al individuo que busca, está pasando por o ha pasado por una transición social de hombre a mujer o de mujer a hombre, que en muchos casos, pero no en todos, también implica una transición somática mediante un tratamiento hormonal de afirmación de género y cirugía genital, de mamas o afirmadora del género de otro tipo (históricamente denominada cirugía de reasignación de sexo). Referencia: DSM-5-TR, Introducción del capítulo sobre disforia de género (pp. 511-512); Introducción del capítulo "Trastornos parafílicos" (p. 779).'),
('DSM-5-TR', 'Trastornos parafílicos', '¿Cuál de las siguientes afirmaciones sobre una persona con trastorno de pedofilia es verdadera?', '["El trastorno de pedofilia se encuentra en el 10-12% de la población masculina.", "No hay evidencia de que la perturbación del neurodesarrollo in utero incremente la probabilidad de que se desarrolle una orientación pedófila.", "Los hombres adultos con pedofilia siempre refieren que abusaron de ellos cuando eran niños.", "El individuo tiene al menos 16 años y es al menos 5 años mayor que el niño o los niños."]', 3, 'La prevalencia poblacional de los individuos cuyas presentaciones cumplen los criterios completos del trastorno de pedofilia se desconoce, aunque probablemente sea inferior al 3% entre los hombres en los estudios internacionales. La prevalencia poblacional del trastorno de pedofilia en las mujeres es aún más incierta, y probablemente sea una pequeña fracción de la prevalencia en los hombres. Dado que la pedofilia es una condición necesaria para el trastorno de pedofilia, cualquier factor que aumente la probabilidad de la pedofilia también incrementará el riesgo del trastorno de pedofilia. Hay evidencia de que la perturbación del neurodesarrollo in utero aumenta la probabilidad de que se desarrolle el interés pedófilo. Los hombres adultos con pedofilia a veces informan que fueron objeto de abusos sexuales cuando eran niños; sin embargo, no está claro si esta correlación refleja una influencia causal del abuso sexual en la infancia sobre la pedofilia adulta. Referencia: DSM-5-TR, Trastorno de pedofilia / Criterios diagnósticos (pp. 792-793); Prevalencia; Desarrollo y curso; Factores de riesgo y pronóstico (pp. 794-795).'),
('DSM-5-TR', 'Trastornos parafílicos', '¿Cuál de las siguientes afirmaciones sobre el trastorno de pedofilia es verdadera?', '["El uso extenso de pornografía que represente a niños prepúberes o pubescentes tempranos no es un indicador diagnóstico útil del trastorno de pedofilia.", "El trastorno de pedofilia es estable a lo largo de la vida.", "Existe una asociación entre el trastorno de pedofilia y el trastorno de la personalidad antisocial.", "Aunque el interés sexual normofílico disminuye con la edad, el interés sexual pedófilo permanece constante."]', 2, 'Parece haber una interacción entre la pedofilia y rasgos de la personalidad antisocial como la insensibilidad, la impulsividad y la disposición a correr riesgos sin una adecuada consideración de las consecuencias. Los hombres con interés pedófilo y rasgos de personalidad antisocial tienen más probabilidades de actuar sexualmente con los niños y, por lo tanto, de cumplir los requisitos diagnósticos del trastorno de pedofilia. Por lo tanto, el trastorno de la personalidad antisocial puede considerarse un factor de riesgo del trastorno de pedofilia en los hombres con pedofilia. Las medidas de laboratorio del interés sexual, en términos de respuestas psicofisiológicas a los estímulos sexuales que representan a niños, que a veces son útiles para diagnosticar el trastorno de pedofilia en los hombres, no necesariamente son útiles para diagnosticar este trastorno en las mujeres, pues se han realizado investigaciones muy limitadas sobre el modo de evaluar el interés sexual pedófilo en las mujeres. Las medidas psicofisiológicas del interés sexual pueden ser útiles a veces cuando la historia de un individuo sugiere la posible presencia del trastorno de pedofilia pero el individuo niega sentir una atracción fuerte o preferencial hacia los niños. La más investigada y más empleada de estas medidas es la pletismografía peneana, aunque la sensibilidad y especificidad del diagnóstico pueden variar de un centro a otro, ya que con frecuencia utilizan estímulos, procedimientos y puntuaciones diferentes. La pedofilia per se parece ser una entidad de por vida. Sin embargo, el trastorno de pedofilia necesariamente incluye otros elementos que pueden cambiar con el tiempo, cono sin tratamiento: malestar subjetivo (por ejemplo, culpa, vergüenza, intensa frustración sexual, sentimientos de aislamiento) o deterioro psicosocial, o propensión a actuar sexualmente con niños, o ambas cosas. Por lo tanto, el curso del trastorno de pedofilia puede fluctuar y la intensidad puede aumentar o disminuir con la edad. Los adultos con trastorno de pedofilia pueden referir que ya eran conscientes de su interés sexual por los niños antes de llevar a cabo conductas sexuales con niños o de reconocer que son individuos con pedofilia. La edad avanzada probablemente disminuirá la frecuencia de las conductas sexuales en relación con niños del mismo modo que lo hace con los demás comportamientos sexuales, motivados o no por parafilias. Referencia: DSM-5-TR, Trastorno de pedofilia (pp. 794-795).'),
('DSM-5-TR', 'Trastornos parafílicos', 'Una mujer de 35 años le cuenta a su terapeuta que recientemente se ha sentido intensamente excitada al ver películas en las que se tortura a personas y que regularmente fantasea con torturar a personas mientras se masturba. No se siente angustiada por estos pensamientos y niega haber actuado nunca según estas nuevas fantasías; sin embargo, fantasea sobre estas actividades varias veces al día. ¿Cuál de las siguientes opciones resume mejor las implicaciones diagnósticas de la presentación de esta paciente?', '["Cumple con todos los criterios del trastorno de sadismo sexual.", "No cumple los criterios del trastorno de sadismo sexual porque las fantasías no son de naturaleza sexual.", "No cumple los criterios del trastorno de sadismo sexual porque nunca ha actuado según las fantasías.", "No cumple los criterios del trastorno de sadismo sexual porque el interés y la excitación comenzaron después de los 35 años."]', 2, 'Los criterios diagnósticos del trastorno de sadismo sexual especifican la presencia de excitación sexual recurrente e intensa ante el sufrimiento físico o psicológico de otra persona, manifestada por fantasías, impulsos o comportamientos, durante un período de al menos 6 meses (Criterio A). El individuo ha actuado según estos impulsos sexuales con una persona no consentidora o los impulsos o fantasías sexuales causan angustia o deterioro clínicamente significativos en el ámbito social, ocupacional u otras áreas importantes del funcionamiento (Criterio B). Los criterios diagnósticos del trastorno de sadismo sexual están destinados a aplicarse tanto a los individuos que admiten libremente tener tales intereses parafílicos como a aquellos que niegan cualquier interés sexual por el sufrimiento físico o psicológico de otro individuo a pesar de tenerse evidencia objetiva sustancial en contra. Los individuos que reconocen abiertamente un interés sexual intenso por el sufrimiento físico o psicológico de otros se denominan individuos admitentes. Si estos individuos también refieren dificultades psicosociales debido a su atracción o sus preferencias sexuales por el sufrimiento físico o psicológico de otro individuo, pueden diagnosticarse de trastorno de sadismo sexual. En cambio, si los individuos admitentes no refieren malestar, ejemplificado por ansiedad, obsesiones, culpa o vergiienza, acerca de estos impulsos parafílicos y no se ven obstaculizados por ellos en la persecución de otros objetivos, y sus historias autoinformadas, psiquiátricas o legales indican que no actúan con personas no consentidoras, entonces podría decirse que tienen un interés sexual sádico, aunque su presentación no cumpliría los criterios del trastorno de sadismo sexual. Referencia: DSM-5-TR, Trastornos parafílicos / Trastorno de sadismo sexual (pp. 790-791).'),
('DSM-5-TR', 'Trastornos parafílicos', 'Durante una celebración de Mardi Gras (Martes de Carnaval), una mujer de 19 años se levanta la blusa y el sujetador mientras pasa una carroza para conseguir collares de cuentas. El evento aparece en un programa de noticias por cable visto por amigos de sus padres, quienes informan a sus padres. Estos insisten en que se haga una evaluación psiquiátrica 2 meses después de las vacaciones. La joven niega cualquier otro suceso similar en su vida, pero admite que la experiencia fue "algo sexi". Actualmente está extremadamente ansiosa y angustiada por la ira de sus padres hacia ella y su negativa a permitirle asistir a fiestas o irse de vacaciones hasta que se haga una evaluación. Informa que no puede asistir a clase ni concentrarse en su trabajo en la universidad. ¿Cuál es el diagnóstico más apropiado?', '["Trastorno de exhibicionismo.", "Trastorno de frotteurismo.", "Trastorno de voyeurismo.", "Trastorno de adaptación."]', 3, 'El episodio único de esta mujer de exponerse a sí misma mientras estaba intoxicada no la hace merecedora de un diagnóstico de trastorno exhibicionista porque no cumple los criterios diagnósticos, específicamente, una historia de 6 meses de excitación sexual recurrente e intensa por la exposición de los genitales propios a una persona desprevenida, manifestada por fantasías, impulsos o comportamientos (Criterio A). Los criterios diagnósticos del trastorno exhibicionista pueden aplicarse tanto a los individuos que revelan más o menos libremente esta parafilia como a aquellos que niegan categóricamente cualquier excitación sexual al exponer sus genitales a personas desprevenidas a pesar de tenerse evidencia objetiva sustancial en contra. Si los individuos que se exhiben también refieren dificultades psicosociales debido a sus atracciones o preferencias sexuales por exponerse, pueden diagnosticarse de trastorno de exhibicionismo. En cambio, si dicen no sentir malestar (ejemplificado por ansiedad, obsesiones y culpa o vergiienza acerca de estos impulsos parafílicos) y no están limitados por este interés sexual en otras áreas importantes de funcionamiento, y sus historias autoinformadas, psiquiátricas o legales indican que no actúan según estos, podría decirse que tienen un interés sexual exhibicionista, aunque no diagnosticarse de trastorno de exhibicionismo. Se desconoce la prevalencia poblacional de los individuos que cumplen los criterios completos del trastorno de exhibicionismo, aunque el trastorno es muy poco común en las mujeres. Sin embargo, los actos exhibicionistas no son infrecuentes, y los actos exhibicionistas sexualmente excitantes se dan hasta la mitad de las veces en mujeres. La angustia actual de esta joven no está relacionada con el acto exhibicionista, sino con la actitud y el comportamiento de sus padres. Su nivel de malestar es desproporcionado con respecto a las restricciones que le imponen sus padres, y esto interfiere en su funcionamiento. Cumple los criterios de un trastorno de adaptación (Criterios A y B). Referencia: DSM-5-TR, Trastorno de exhibicionismo / Criterios diagnósticos; Desarrollo y curso; Aspectos diagnósticos relacionados con el género y el sexo; Diagnóstico diferencial (pp. 783-785); Trastornos de adaptación / Criterios diagnósticos (p. 319).'),
('DSM-5-TR', 'Trastornos parafílicos', 'Un chico de 16 años le cuenta a su terapeuta que puede ver el dormitorio de una mujer desde su edificio de apartamentos. Ha estado observándola desde que se mudó al apartamento hace 6 meses. Puede ver a la mujer vistiéndose y desvistiéndose, lo cual le resulta sexualmente excitante. Tiene fantasías sobre la mujer obligándolo a tener relaciones sexuales con ella. No siente culpa por esto porque la mujer no tiene cortina en la ventana. El terapeuta solicita una consulta psiquiátrica para evaluar si el paciente tiene una parafilia. ¿Cuál de los siguientes es el diagnóstico correcto?', '["Trastorno de voyeurismo.", "Trastorno parafílico no especificado.", "Otro trastorno parafílico especificado.", "Comportamiento sexual adolescente normal."]', 3, 'La adolescencia y la pubertad generalmente aumentan la curiosidad y la actividad sexual. Para reducir el riesgo de patologizar el interés y el comportamiento sexual normativos durante la adolescencia puberal, la edad mínima para el diagnóstico de trastorno de voyeurismo son los 18 años (Criterio C). Los individuos con voyeurismo experimentan excitación sexual recurrente e intensa al observar a una persona desprevenida que está desnuda, desvistiéndose o participando en alguna actividad sexual. A menos que el individuo actúe según estos impulsos con una persona desprevenida (por ejemplo, espiar subrepticiamente a través de la ventana de un vecino) o a menos que haya malestar o deterioro clínicamente significativos en el ámbito social, ocupacional u otras áreas importantes del funcionamiento, no se justifica el diagnóstico de trastorno de voyeurismo. Referencia: DSM-5-TR, Trastorno de voyeurismo / Características diagnósticas / Diagnóstico diferencial (pp. 781-782).'),
('DSM-5-TR', 'Trastornos parafílicos', 'Durante una visita a urgencias por asma, un hombre muestra signos de haber sido azotado. Cuando se le pregunta por las marcas, informa que se autoflageló durante una ceremonia religiosa. Se solicita una consulta psiquiátrica y el hombre admite que a menudo fantasea con ser golpeado y ve pornografía de personas siendo golpeadas, lo que le resulta sexualmente excitante. Pide a su pareja que le golpee y no puede conseguir una erección si no lo golpean o humillan. ¿Cuál de las siguientes opciones describe la situación con mayor precisión?', '["Trastorno de sadismo sexual.", "Trastorno de masoquismo sexual.", "Trastorno de voyeurismo.", "Trastorno de la personalidad masoquista."]', 1, 'Los criterios diagnósticos del trastorno de masoquismo sexual están destinados a aplicarse a aquellos individuos que admiten libremente tener tales intereses parafílicos. Estos individuos reconocen abiertamente su intensa excitación sexual al ser humillados, golpeados, atados o vejados de cualquier manera, manifestada por fantasías, impulsos o comportamientos. Si estos individuos también refieren dificultades psicosociales debido a sus atracciones o preferencias sexuales por ser objeto de humillación, golpes, ataduras u otro tipo de vejaciones, pueden diagnosticarse de trastorno de masoquismo sexual. El término bondage-dominación-sadismo-masoquismo (BDSM) se utiliza ampliamente para referirse a una amplia gama de comportamientos en los que participan individuos con masoquismo y/o sadismo sexual (así como otros individuos con intereses sexuales similares) usando ataduras o sujeciones, castigos, azotes, bofetadas, privaciones sensoriales (por ejemplo, mediante vendas en los ojos) y juegos de rol de dominación-sumisión con temas como los de amo/esclavo, dueño/mascota o secuestrador/víctima. El uso extenso de pornografía sobre personas humilladas, golpeadas, atadas o vejadas de otro modo es a veces una característica asociada al trastorno de masoquismo sexual. Es importante distinguir los comportamientos de autolesión que ocurren durante las prácticas religiosas y espirituales colectivamente aceptadas de los comportamientos sadomasoquistas realizados para lograr la excitación sexual. Por ejemplo, los rituales colectivos de varias religiones y sociedades incluyen la suspensión de ganchos, la autoflagelación, la automortificación y otras pruebas dolorosas. El papel de la excitación sexual o el placer en estas prácticas sigue siendo desconocido. No existe ningún diagnóstico de trastorno de la personalidad masoquista en el DSM-5-TR. Referencia: DSM-5-TR, Trastorno de masoquismo sexual / Características diagnósticas / Características asociadas / Aspectos diagnósticos relacionados con la cultura (pp. 788-789); Trastornos de la personalidad (p. 733).'),
('DSM-5-TR', 'Trastornos parafílicos', 'Después de un episodio de síncope, un hombre es examinado en el departamento de urgencias y se descubre que lleva ropa interior de mujer. No puede dar una explicación y se contacta con su esposa. Cuando se le pregunta sobre la ropa de su marido, ella informa que ha llevado ropa interior de mujer de manera intermitente durante años, lo cual le resulta angustioso. Señala que no pueden tener relaciones sexuales si él no se viste de mujer. Excepto por llevar la ropa ocasionalmente fuera de casa y antes del sexo, afirma que por lo demás es un "tipo normal". ¿Cuál de los siguientes diagnósticos sería el más apropiado?', '["Trastorno de fetichismo.", "Disforia de género.", "Travestismo.", "Trastorno de travestismo."]', 3, 'El diagnóstico de trastorno de travestismo no se aplica a todas las personas que se visten como el sexo opuesto, ni siquiera a aquellas que lo hacen habitualmente. Se aplica a los individuos cuyo travestismo o cuyos pensamientos de travestismo siempre o a menudo van acompañados de excitación sexual (Criterio A) y que se sienten emocionalmente angustiados por este patrón o ven su funcionamiento social o interpersonal afectado por el mismo (Criterio B). El travestismo puede implicar solo una o dos prendas de vestir (por ejemplo, para los hombres, puede referirse solo a la ropa interior de las mujeres), o puede implicar vestirse completamente con las prendas interiores y exteriores del otro sexo; además, en los hombres puede incluir el uso de pelucas y maquillaje de mujer. En algunos casos, el curso del trastorno de travestismo es continuo y en otros es episódico. No es raro que los hombres con trastorno de travestismo pierdan interés en el travestismo cuando se enamoran por primera vez de una mujer y comienzan una relación, pero tal disminución suele ser temporal. Cuando el deseo de travestismo regresa, también lo hace la angustia asociada. El trastorno de travestismo en los hombres a menudo va acompañado de autoginefilia (es decir, la tendencia parafílica de un hombre a sentirse sexualmente excitado por la idea o la imagen de sí mismo como mujer). Las fantasías y comportamientos autoginefílicos pueden centrarse en la idea de exhibir funciones fisiológicas femeninas (por ejemplo, lactancia, menstruación), de participar en comportamientos estereotípicamente femeninos (por ejemplo, tejer) o de poseer una anatomía femenina (por ejemplo, senos). Algunos casos de trastorno de travestismo progresan a la disforia de género. Los hombres en estos casos, que pueden ser indistinguibles de los demás chicos con trastorno de travestismo en la adolescencia o la infancia temprana, gradualmente desarrollan deseos de permanecer en el papel de mujer durante períodos más largos y de feminizar su anatomía. El desarrollo de la disforia de género suele ir acompañado de una reducción o eliminación (autoinformada) de la excitación sexual asociada con el travestismo. Las personas con travestismo experimentan una excitación sexual recurrente e intensa al travestirse. A menos que las fantasías, los impulsos sexuales o los comportamientos propios del travestismo vayan acompañados de malestar o deterioro clínicamente significativos en las áreas sociales, laborales u otras áreas importantes del funcionamiento, no se justifica el diagnóstico de trastorno travestista. El trastorno de fetichismo puede parecerse al trastorno de travestismo, en particular en los hombres con fetichismo que se ponen ropa interior de mujer mientras se masturban con ella. Distinguir el trastorno de travestismo depende de los pensamientos específicos del individuo durante dicha actividad (por ejemplo, ¿se tiene la idea de ser mujer, de ser como una mujer o de estar vestido como una mujer?) y de la presencia de otros fetiches (por ejemplo, telas suaves y sedosas, ya sean usadas para prendas de vestir o para otra cosa). Las personas con trastorno de travestismo no refieren incongruencia entre el género experimentado y el asignado, ni deseo de ser del otro género; normalmente no tienen antecedentes de comportamientos de género cruzado en la infancia, que sí estarían presentes en las personas con disforia de género. Las personas con un cuadro que cumpla todos los criterios del trastorno de travestismo y de la disforia de género deberán recibir ambos diagnósticos. Referencia: DSM-5-TR, Trastorno de travestismo / Características diagnósticas / Características asociadas / Diagnóstico diferencial (pp. 799-800).'),
('DSM-5-TR', 'Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos', '¿Cuál de los siguientes no es un factor de riesgo constante en el desarrollo del parkinsonismo inducido por medicamentos (PIM)?', '["Sexo masculino.", "Edad avanzada.", "Enfermedad del VIH.", "Historia familiar de la enfermedad de Parkinson."]', 0, 'Los factores de riesgo constantes del PIM son el sexo femenino, la edad avanzada, el deterioro cognitivo, otras afecciones neurológicas concurrentes, la infección por VIH, la historia familiar de enfermedad de Parkinson y la enfermedad psiquiátrica grave. El PIM secundario al uso de antipsicóticos también se ha observado en niños. El riesgo de PIM se reduce si los individuos toman medicamentos anticolinérgicos. Referencia: DSM-5-TR, Parkinsonismo inducido por medicamentos / Diagnóstico diferencial (p. 809).'),
('DSM-5-TR', 'Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos', 'El síndrome neuroléptico maligno es un síndrome potencialmente letal con una tasa de incidencia del 0,01-0,02 % entre los individuos tratados con neurolépticos. ¿Cuál de los siguientes no es un signo o síntoma del síndrome neuroléptico maligno?', '["Hipertermia.", "Rigidez generalizada.", "Creatina-cinasa elevada.", "Estado mental inalterado."]', 3, 'Los individuos con síndrome neuroléptico maligno generalmente han estado expuestos a un antagonista de la dopamina en las 72 horas previas al desarrollo de los síntomas. La hipertermia (> 104 *F o > 38 "C) en al menos dos ocasiones, medida oralmente y asociada a diaforesis profusa, es una característica distintiva del síndrome neuroléptico maligno que lo diferencia de otros efectos secundarios neurológicos de otros medicamentos antipsicóticos y otros agentes bloqueadores de los receptores de dopamina. La rigidez generalizada, descrita como "en tubo de plomo" en su forma más grave y generalmente no receptiva a los agentes antiparkinsonianos, es una característica cardinal del trastorno y puede asociarse a otros síntomas neurológicos (por ejemplo, temblor, sialorrea, acinesia, distonía, trismo, mioclono, disartria, disfagia, rabdomiólisis). La elevación de la creatina-cinasa al menos cuatro veces por encima del límite superior normal se observa con frecuencia. Los cambios del estado mental, caracterizados por delirium o alteración de la conciencia que va desde el estupor hasta el coma, a menudo son un signo temprano del síndrome neuroléptico maligno. Referencia: DSM-5-TR, Síndrome neuroléptico maligno (p. 810).'),
('DSM-5-TR', 'Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos', 'Un paciente de 22 años con esquizofrenia y sin problemas médicos comórbidos es ingresado en una unidad de internación para tratar un primer episodio de psicosis. Se inicia risperidona 1 mg para la paranoia y las alucinaciones auditivas despectivas. Antes de 24 horas, el paciente comienza a experimentar una crisis oculógira. Las contracciones musculares se alivian con una inyección de difenhidramina 50 mg IM. ¿Cuál de las siguientes opciones es la mejor explicación de lo que le ocurrió a este paciente?', '["Síndrome neuroléptico maligno.", "Distonía aguda inducida por medicamentos.", "Acatisia aguda inducida por medicamentos.", "Distonía tardía."]', 1, 'La característica esencial de la distonía aguda inducida por medicamentos es una contracción muscular sostenida (aumento del tono muscular) y posturas anormales que aparecen en relación con el uso de un medicamento conocido por causar distonía aguda. Cualquier medicamento que bloquee los receptores D, de la dopamina puede inducir una reacción distónica aguda (RDA). La mayoría de las veces, las RDA se producen después de la exposición a antipsicóticos y agentes antieméticos y promotores de la movilidad. Las reacciones distónicas afectan más comúnmente a los músculos de la cabeza y el cuello, pero pueden extenderse a las extremidades superiores e inferiores o bien al tronco. Al menos el 50% de los individuos desarrollan signos y síntomas de ADR dentro de las 24-48 horas siguientes a la instauración o un aumento rápido de la dosis de medicación antipsicótica u otro agente bloqueador de los receptores de dopamina, o a la bajada de un medicamento utilizado para tratar o prevenir los síntomas extrapiramidales agudos (por ejemplo, agentes anticolinérgicos). Referencia: DSM-5-TR, Distonía aguda inducida por medicamentos (p. 812).'),
('DSM-5-TR', 'Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos', 'Un paciente de 55 años con trastorno esquizoafectivo se presenta en la sala de urgencias con gran malestar. Como antecedentes, ha tenido ansiedad la última semana, siendo incapaz de relajarse al final del día. No puede quedarse quieto y ha desarrollado insomnio. Se observa que el paciente cambia de posición en la camilla de exploración y mueve ambas piernas durante la exploración. Su historial de medicación incluye risperidona 2 mg v.o. dos veces al día, dosis que se subió a partir de 2 mg diarios 1 semana antes. ¿Cuál de las siguientes opciones explica mejor lo que le ocurre al paciente?', '["Abstinencia de tabaco.", "Trastorno de la personalidad histriónica.", "Acatisia aguda inducida por medicamentos.", "Síndrome de serotonina."]', 2, 'Las características esenciales de la acatisia aguda inducida por medicamentos son las quejas subjetivas de inquietud y al menos uno de los siguientes movimientos observables: movimientos inquietos o de balanceo de las piernas mientras se está sentado, balanceo de un pie a otro o "caminar sin moverse del sitio " mientras se está de pie, caminar para aliviar la inquietud o incapacidad de permanecer sentado o de pie quieto durante al menos varios minutos. Las quejas subjetivas incluyen una sensación de inquietud interna, más a menudo en las piernas, la compulsión de mover las piernas, malestar si se le pide a uno que no mueva las piernas, disforia y ansiedad. Referencia: DSM-5-TR, Acatisia aguda inducida por medicamentos (p. 813).'),
('DSM-5-TR', 'Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos', '¿Cuál de las siguientes afirmaciones es verdadera acerca de las discinesias tardías?', '["Las discinesias tardías no incluyen los movimientos que se desarrollan antes de 1 mes después de suspender un medicamento antipsicótico oral.", "La prevalencia general de la discinesia tardía en individuos que han sido tratados con medicamentos antipsicóticos a largo plazo está entre el 10 y el 20%.", "Los hombres tienen más probabilidades de desarrollar discinesia tardía que las mujeres.", "La discinesia tardía incluye varios tipos diferentes de movimientos."]', 3, 'Las características esenciales de la discinesia tardía son movimientos anormales e involuntarios de la lengua, la mandíbula, el tronco o las extremidades que se desarrollan en relación con el uso de medicamentos bloqueantes de los receptores postsinápticos de dopamina, como los medicamentos antipsicóticos de primera y segunda generación y otros medicamentos como la metoclopramida, usada en los trastornos gastrointestinales. Los movimientos están presentes durante al menos 4 semanas y pueden ser de naturaleza coreiforme (rápidos, bruscos, no repetitivos), atetoide (lentos, sinuosos, continuos) o semirrítmica (por ejemplo, estereotipias); sin embargo, los movimientos son claramente diferentes de los temblores rítmicos (3-6 Hz) comúnmente vistos en el parkinsonismo inducido por medicamentos. La discinesia tardía se desarrolla durante la exposición al medicamento antipsicótico u otro agente bloqueador de la dopamina, o dentro de las 4 semanas siguientes a la retirada de un agente oral (o las 8 semanas de la retirada de un agente inyectable de acción prolongada). La prevalencia general de la discinesia tardía en los individuos que han recibido tratamiento con medicación antipsicótica a largo plazo varía del 20 al 30%. No hay diferencias obvias entre los géneros en cuanto a susceptibilidad a la discinesia tardía, aunque el riesgo puede ser algo mayor en las mujeres posmenopáusicas. Referencia: DSM-5-TR, Discinesia tardía (pp. 814-815).'),
('DSM-5-TR', 'Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos', 'Una paciente de 41 años con depresión recurrente y ansiedad ha estado tomando medicación durante 1 año. Ha estado experimentando "descargas cerebrales", náuseas, dolores de cabeza terribles y ansiedad durante los últimos 3 días. El psiquiatra evalúa la presencia de otros síntomas y pregunta sobre la adherencia a la medicación, descubriendo que la paciente dejó de tomar su antidepresivo "de golpe" hace unos días. ¿Cuál de los siguientes medicamentos es probable que la paciente haya dejado de tomar?', '["Venlafaxina.", "Fluoxetina.", "Hormona tiroidea.", "Litio."]', 0, 'Pueden aparecer síntomas de discontinuación después del tratamiento con todos los tipos de antidepresivos. La incidencia de este síndrome depende de la dosis y la semivida del medicamento que se está tomando, así como de la velocidad con la que se reduce el medicamento. Los antidepresivos de acción corta, paroxetina y venlafaxina, son los agentes más comúnmente asociados con síntomas de discontinuación. Se sabe que la fluoxetina tiene una semivida larga y, por lo tanto, rara vez causa síntomas de discontinuación. Tanto la hormona tiroidea como el litio son potenciadores que se utilizan comúnmente en el tratamiento de la depresión, pero no se utilizan como agentes primarios para tratar la depresión. Referencia: DSM-5-TR, Síndrome de suspensión de antidepresivos (p. 818).'),
('DSM-5-TR', 'Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos', '¿Cuál de los siguientes factores no aumenta el riesgo del temblor por litio?', '["Ansiedad.", "Niveles altos de litio en suero.", "Historial personal o familiar de temblor.", "Edad joven."]', 3, 'Varios factores pueden aumentar el riesgo del temblor por litio. Estos factores son la mayor edad, los niveles altos de litio en suero, el uso concurrente de medicación antidepresiva o antipsicótica u otro agente bloqueador de los receptores de dopamina, el consumo excesivo de cafeína, antecedentes personales o familiares de temblor, presencia del trastorno por consumo de alcohol y ansiedad asociada. Referencia: DSM-5-TR, Temblor postural inducido por medicamentos (p. 817).'),
('DSM-5-TR', 'Trastornos motores inducidos por medicamentos y otros efectos adversos de los medicamentos', '¿Cuál de las siguientes afirmaciones no es cierta acerca del temblor postural inducido por medicamentos?', '["La característica esencial es un temblor fino que ocurre durante los intentos de mantener una postura y aparece en relación con el uso de medicación.", "El temblor es una oscilación regular y rítmica de las extremidades, la cabeza, la boca o la lengua con una frecuencia de entre 3 y 6 HZ.", "No se diagnostica el temblor postural inducido por medicamentos si el temblor se explica mejor por un parkinsonismo inducido por medicación.", "El temblor puede ser una característica temprana del síndrome de serotonina."]', 1, 'El temblor postural inducido por medicamentos es una oscilación rítmica regular de las extremidades (más comúnmente de manos y dedos), la cabeza, la boca o la lengua, la mayoría de las veces con una frecuencia de entre 8 y 12 ciclos por segundo. En cambio, el temblor relacionado con el parkinsonismo inducido por medicamentos suele ser de menor frecuencia (3-6 Hz), es peor en reposo, se suprime durante el movimiento intencional y generalmente se acompaña de otros síntomas de parkinsonismo inducido por medicamentos (por ejemplo, acinesia, rigidez). Referencia: DSM-5-TR, Temblor postural inducido por medicamentos, Diagnóstico diferencial (p. 817).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', '¿Cuál de los siguientes factores sobre el diagnóstico categórico tradicional respalda la incorporación de los conceptos dimensionales?', '["Orientación específica para el tratamiento.", "Diagnósticos estables y definitivos.", "Bajas tasas de comorbilidad.", "Uso frecuente de diagnósticos de otro especificado o no especificado."]', 3, 'Un creciente cuerpo de evidencia científica favorece los conceptos dimensionales en el diagnóstico de los trastornos mentales. Las limitaciones del enfoque categórico del diagnóstico incluyen la incapacidad de encontrar zonas de rareza entre diagnósticos (es decir, la delimitación de los trastornos mentales entre sí por límites naturales), la necesidad de categorías intermedias como el trastorno esquizoafectivo, las altas tasas de comorbilidad, la necesidad de uso frecuente de los diagnósticos de otro especificado o no especificado, la relativa falta de utilidad para avanzar en la identificación de validadores antecedentes únicos para la mayoría de los trastornos mentales y la falta de especificidad del tratamiento para las diversas categorías diagnósticas. Desde ambas perspectivas, clínica e investigación, existe la necesidad de un enfoque más dimensional que pueda combinarse con el conjunto de diagnósticos categóricos del DSM-5-TR para captar mejor la heterogeneidad de la presentación de varios trastornos mentales y por consumo de sustancias. Tal enfoque permite a los clínicos y demás especialistas comunicar mejor la variación particular de las características aplicables a las presentaciones que cumplen los criterios de un trastorno. Dichas características son la gravedad diferencial de los síntomas individuales (incluidos tanto los síntomas que forman parte de las características diagnósticas como aquellos que se asocian al trastorno) medidos en términos de intensidad, duración e impacto sobre el funcionamiento. Este enfoque combinado también permite a los clínicos y demás especialistas identificar afecciones que no cumplen los criterios de ningún trastorno pero que son graves y discapacitantes, y necesitan tratamiento. Referencia: DSM-5-TR, Medidas de evaluación / Introducción del capítulo (p. 841).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', '¿Cuál de las siguientes afirmaciones describe con precisión la Escala de evaluación de la discapacidad de la Organización Mundial de la Salud, versión 2.0 (WHODAS 2.0)?', '["Se centra solo en las discapacidades debidas a enfermedades psiquiátricas.", "Evalúala capacidad del paciente para realizar actividades en seis áreas funcionales.", "No puede cumplimentarse en nombre de un paciente con capacidad deteriorada.", "Mide principalmente la discapacidad física."]', 1, 'La versión autocumplimentable para adultos de la WHODAS 2.no es una medida de 36 ítems que evalúa la discapacidad en los adultos de 18 años en adelante. Ha sido validada en numerosas culturas de todo el mundo y ha demostrado ser sensible a los cambios. Evalúa la discapacidad en seis dominios: comprensión y comunicación, movilidad, autocuidado, interacción con personas, actividades de la vida diaria (por ejemplo, actividades domésticas, laborales y/o escolares) y participación en la sociedad. Si el adulto tiene su capacidad deteriorada y no puede completar el formulario (por ejemplo, un paciente con trastorno neurocognitivo mayor), un informante que lo conozca bien puede completar la versión cumplimentable por terceros de la medida, que está disponible en www.medicapanamericana.com. Referencia: DSM-5-TR, Escala de evaluación de la discapacidad de la Organización Mundial de la Salud 2.0 (p. 854).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', '¿Cuál es la función de la Medida de síntomas transversales de nivel 1 del DSM-5?', '["Evalúa la capacidad del paciente para realizar actividades en seis áreas de la vida diaria.", "Evalúa la presencia y frecuencia de síntomas en 13 dominios psiquiátricos.", "Solo clarifica los síntomas presentes en el momento de la entrevista.", "Está destinada principalmente a ser una herramienta de investigación."]', 1, 'La Medida de síntomas transversales de nivel 1 del D5M-5 es una medida evaluada por el propio paciente o un informante que evalúa los dominios de salud mental que son importantes en todos los diagnósticos psiquiátricos. Está destinada a ayudar a los clínicos a identificar áreas adicionales de investigación que puedan tener un impacto significativo en el tratamiento y pronóstico del individuo. Además, la medida puede usarse para rastrear los cambios de la presentación sintomática del individuo a lo largo del tiempo. La versión para adultos de la Medida de síntomas transversales de nivel 1 del DSM-5 autoevaluada consta de 23 preguntas que evalúan 13 dominios psiquiátricos: depresión, ira, manía, ansiedad, síntomas somáticos, ideación suicida, psicosis, problemas de sueño, memoria, pensamientos y comportamientos repetitivos, disociación, funcionamiento de la personalidad y consumo de sustancias. Cada ítem pregunta en qué medida (o con qué frecuencia) ha perturbado el síntoma específico al individuo durante las últimas 2 semanas. Si el individuo tiene su capacidad deteriorada y no puede completar el formulario (por ejemplo, un individuo con demencia), un informante adulto que lo conozca bien puede completar esta medida. La medida se encontró clínicamente útil y con buena fiabilidad en los ensayos de campo del DSM-5 que se realizaron en muestras clínicas de adultos de Estados Unidos y Canadá. Referencia: DSM-5-TR, Medidas de síntomas transversales / Medida de síntomas transversales de nivel 1 (p. 843).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', 'En la revisión clínica de las puntuaciones de los ítems de la Medida de síntomas transversales de nivel 1 del DSM-5 para un paciente adulto, ¿de cuál de los siguientes dominios una calificación de "leve" requeriría una investigación adicional si se encuentra en cualquier ítem?', '["Depresión.", "Manía.", "Ira.", "Ideación suicida."]', 3, 'En la versión autoevaluada para adultos de la Medida de síntomas transversales de nivel 1 del DSM-5, cada ítem se califica en una escala de 5 puntos (0 = ninguno o nada en absoluto; 1 = leve o raro, menos de 1 02 días; 2 = moderado o varios días; 3 = moderado o más de la mitad de los días; y 4 = grave o casi todos los días). Mientras que en la mayoría de los dominios una calificación de moderado (es decir, 2) o superior para cualquier ítem del dominio es el umbral que decide si hacer o no la investigación adicional, para los dominios de consumo de sustancias, ideación suicida y psicosis una calificación de leve (es decir, 1) o superior es el umbral para realizar dicha investigación adicional y un seguimiento para determinar si se necesita una evaluación más detallada (que puede incluir la evaluación de los síntomas transversales de nivel 2 para ese dominio). Referencia: DSM-5-TR, Medidas de síntomas transversales / Medida de síntomas transversales de nivel 1 / Puntuación e interpretación (pp. 843-846).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', 'Si un padre responde "No sé" a la pregunta "En las últimas DOS (2) SEMANAS, ¿ha consumido su hijo alguna bebida alcohólica (cerveza, vino, licor, etc.)?" de la versión puntuada por los padres/tutores de la Medida de síntomas transversales de nivel 1 del DSM-5, ¿cuál es la respuesta apropiada del clínico?', '["Hacerle al chico preguntas del dominio de consumo de sustancias de la Medida de síntomas transversales de nivel 2 autoevaluada por el interesado.", "Confiar en otras preguntas del dominio de consumo de sustancias y no incorporar esta respuesta a la puntuación final.", "Pedir al padre que pregunte al niño y programar una visita de seguimiento para administrar nuevamente el cuestionario.", "Considerar la posibilidad de denunciar al padre a los servicios de protección infantil."]', 0, 'En la versión evaluada por un progenitor/tutor legal de la Medida de síntomas transversales de nivel 1 del D5SM-5 para menores de 6a 17 años, los ítems de 2 de los 12 dominios -ideación/intentos de suicidio y consumo de sustancias—se califican cada uno en una escala de "Sí, No o No sé". La calificación de "No sé" de un padre o tutor en los ítems de ideación suicida, intento de suicidio y cualquiera de los ítems de consumo de sustancias, especialmente en los menores de 11 a 17 años, justificaría una investigación adicional de los problemas con el menor, incluido el uso de la Medida de síntomas transversales de nivel 2 autoevaluada en relación con el dominio relevante (véase la Tabla 2). Referencia: DSM-5-TR, Medidas de síntomas transversales / Medida de síntomas transversales de nivel 1; Tabla 2 (Medida de síntomas transversales de nivel 1 del DSM-5 evaluada por un progenitor / tutor legal para menores de 6 a 17 años) (pp. 849-850); Medidas de síntomas transversales de nivel 2 (p. 846).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', '¿Cuál de las siguientes opciones no está evaluada por la medida de la Gravedad de los síntomas de las dimensiones de psicosis evaluada por el clínico?', '["Función social.", "Función cognitiva.", "Depresión.", "Manía."]', 0, 'La medida de Gravedad de los síntomas de las dimensiones de psicosis evaluada por el clínico proporciona escalas para la evaluación dimensional de los síntomas primarios de psicosis, como alucinaciones, delirios, discurso desorganizado, comportamiento psicomotor anormal y síntomas negativos. También se incluye una escala para la evaluación dimensional del deterioro cognitivo. Muchos individuos con trastornos psicóticos tienen deterioro en varios dominios cognitivos, que predicen las habilidades funcionales y el pronóstico. Además, se proporcionan escalas de evaluación dimensional de la depresión y la manía, que pueden alertar a los clínicos sobre una patología concurrente del estado de ánimo. La gravedad de los síntomas anímicos en la psicosis tiene valor pronóstico y puede guiar el tratamiento. Referencia: DSM-5-TR, Gravedad de los síntomas de las dimensiones de psicosis evaluada por el clínico (p. 851).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', 'Al revisar las respuestas de un paciente a los ítems de la Escala de evaluación de la discapacidad de la Organización Mundial de la Salud 2.0 (WHODAS 2.0), el clínico nota que, en respuesta a la pregunta "¿Cuánto tiempo pasó en ese estado de salud o sus consecuencias?", el paciente respondió "Casi nada". El clínico, que lleva tratando al paciente varios años, se sorprende al ver esto porque está bastante seguro de que el paciente pasa la mayor parte del día lidiando con problemas de salud. ¿Cuál es la acción apropiada para este clínico?', '["Dejar la respuesta del paciente tal como está y puntuar en consecuencia.", "Indicar en el formulario que el clínico está haciendo una corrección y revisar la puntuación.", "Intentar obtener información adicional de los miembros de la familia para aclarar la discrepancia.", "Tomar el promedio de las puntuaciones diferentes del paciente y del clínico y usarlo para la puntuación final."]', 1, 'La versión autocumplimentable para adultos de la WHODAS 2.no es una medida de 36 ítems que evalúa la discapacidad en los adultos de 18 años en adelante. Ha sido validada en numerosas culturas de todo el mundo y ha demostrado su sensibilidad a los cambios. Se pide al clínico que revise la respuesta del individuo a cada ítem de la medida durante la entrevista clínica y que indique la puntuación otorgada por el paciente a cada ítem en el apartado proporcionado para "Uso exclusivo del clínico". Si el clínico determina que la puntuación de un ítem debería ser diferente conforme a la entrevista clínica y demás informaciones disponibles, puede indicar una puntuación corregida en el cuadro de puntuación del ítem en bruto. Referencia: DSM-5-TR, Escala de evaluación de la discapacidad de la Organización Mundial de la Salud 2.0 (p. 854) / Guía adicional de puntuación e interpretación para usuarios del DSM-5-TR (p. 855).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', '¿En cuál de las siguientes opciones se basan las medidas de síntomas transversales del DSM-5?', '["La Clasificación Internacional del Funcionamiento, la Discapacidad y la Salud.", "La revisión por sistemas de la medicina general.", "La Escala breve de evaluación psiquiátrica.", "La escala global de impresión clínica."]', 1, 'Las medidas de síntomas transversales, modeladas según la revisión por sistemas de la medicina general, pueden servir de estrategia para revisar los dominios psicopatológicos críticos. La revisión por sistemas de la medicina general es crucial para poder detectar cambios sutiles en los diferentes sistemas orgánicos, que podrían facilitar el diagnóstico y el tratamiento. Una revisión similar de varios sistemas mentales (o dominios), que es el objetivo de las medidas de síntomas transversales, puede ayudar a lograr una evaluación más completa del estado mental de los individuos durante la evaluación inicial. La revisión de los sistemas mentales puede dirigir sistemáticamente la atención hacia signos y síntomas de otros dominios de salud mental y del funcionamiento que podrían ser importantes para el manejo del individuo. Referencia: DSM-5-TR, Medidas de evaluación / Introducción del capítulo (pp. 841-842).'),
('DSM-5-TR', 'Medidas de evaluación (Sección III del DSM-5-TR)', '¿Cuál de los siguientes es un uso previsto de las medidas de gravedad en el DSM-5-TR?', '["Evaluar la gravedad de los síntomas transdiagnósticos.", "Cuantificar los efectos secundarios asociados al tratamiento.", "Establecer cualquier diagnóstico psiquiátrico.", "Estimar la gravedad en los pacientes que no cumplen todos los criterios diagnósticos de ningún trastorno en particular."]', 3, 'Las medidas de gravedad son específicas de cada trastorno, correspondiendo estrechamente a los criterios que constituyen la definición del trastorno. Pueden utilizarse con aquellos individuos que han recibido un diagnóstico o tienen un síndrome clínicamente significativo que no cumple todos los criterios diagnósticos (por ejemplo, el uso de la Gravedad de los síntomas de las dimensiones de psicosis evaluada por el clínico en caso de individuos cuyos síntomas cumplen los criterios de la esquizofrenia). Algunas de las evaluaciones son autocumplimentables, mientras que otras son cumplimentadas por el clínico según la observación del individuo. Al igual que las medidas de síntomas transversales, estas medidas pueden evaluarse tanto en la entrevista inicial como a lo largo del tiempo para seguir la gravedad del trastorno y la respuesta del individuo al tratamiento. Estas evaluaciones ayudan a operativizar la frecuencia, la intensidad y la duración de los síntomas, así como la gravedad general de los síntomas o el tipo de síntomas (por ejemplo, depresión, ansiedad, alteración del sueño) de muchos, aunque no todos, los diagnósticos del DSM-5-TR (por ejemplo, trastorno de ansiedad generalizada, trastorno de ansiedad social, trastornos psicóticos, trastorno de estrés postraumático, trastorno del espectro autista, trastorno de comunicación social (pragmático). Los datos obtenidos del uso de estas medidas específicas pueden ayudar con el diagnóstico e informar el seguimiento de los síntomas y la planificación del tratamiento. Referencia: DSM-5-TR, Medidas de evaluación / Introducción del capítulo (p. 842).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', 'Actualizada en el DSM-5-TR, ¿cuál de los siguientes ítems evalúa la ampliada Guía de formulación cultural?', '["Preferencias culturales en las opciones de ocio y entretenimiento.", "Factores de riesgo de determinados diagnósticos psiquiátricos.", "Características culturales de vulnerabilidad y resiliencia.", "Definiciones de grupos culturales y sus estructuras de creencias unificadas."]', 2, 'Aunque los aspectos culturales de la actividad de ocio pueden tener una relevancia distal para la salud mental, la actividad de ocio no es una categoría principal de la Guía de formulación cultural del DSM-5-TR. La identidad cultural del individuo incluye aspectos de los factores étnicos, raciales, lingüísticos y culturales con los que el individuo se identifica. Los conceptos culturales de malestar implican formas culturalmente específicas de entender y afrontar la angustia. Los estresores psicosociales y las características culturales de vulnerabilidad y resiliencia se refieren a los estresores y los sistemas de apoyo social y específicos de la cultura y sus conceptos relacionados, así como a los conceptos culturalmente ligados al trabajo y a la discapacidad. Los enfoques de la relación paciente-médico pueden variar significativamente entre las diferentes culturas. Es esencial entender estas diferencias si se quiere establecer una relación de ayuda. Referencia: DSM-5-TR, Guía de formulación cultural (pp. 860-862).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', 'La identidad cultural del individuo es una de las categorías de la Guía de formulación cultural del DSM-5-TR. ¿Cuál de las siguientes es una característica de la identidad cultural del individuo?', '["Cómo influyen los constructos culturales en la experiencia de los síntomas o problemas psicológicos por parte del individuo.", "Afiliación religiosa y espiritualidad.", "Determinantes sociales de la salud mental.", "Experiencias previas de racismo y discriminación en la atención de salud mental."]', 1, 'En el apartado de identidad cultural del individuo de la Guía de formulación cultural se pide al facultativo que describa las características demográficas del individuo (por ejemplo, edad, género, antecedentes étnico-raciales) u otras características definidas social y culturalmente que puedan influir en las relaciones interpersonales, el acceso a recursos y los desafíos, conflictos o dilemas actuales y durante el desarrollo. Otros aspectos de la identidad clínicamente relevantes pueden ser la afiliación religiosa y la espiritualidad, la clase socioeconómica, la casta, los lugares de nacimiento y crecimiento de la persona y la familia, el estado migratorio, la ocupación y la orientación sexual, entre otros. Se debe tener en cuenta qué aspectos de la identidad son priorizados por el individuo y cómo interactúan (interseccionalidad). En el apartado de los conceptos culturales de malestar se pide a los facultativos que describan los constructos culturales que influyen en cómo experimenta, comprende y comunica sus síntomas o problemas el individuo a los demás. Estos constructos incluyen las expresiones culturales de malestar, las explicaciones culturales o las causas percibidas, y los síndromes culturales. Los apartados de estresores psicosociales y características culturales de vulnerabilidad y resiliencia describen los principales estresores, desafíos y apoyos en el entorno social del individuo (que puede incluir sucesos tanto locales como distantes). Estos incluyen los determinantes sociales de la salud mental del individuo, como el acceso a los recursos (por ejemplo, vivienda, transporte) y las oportunidades (por ejemplo, educación, empleo), la exposición al racismo, la discriminación y la estigmatización institucional sistémica, y la marginación o exclusión social (violencia estructural). Los niveles de funcionamiento, discapacidad y resiliencia deben evaluarse a la luz del trasfondo cultural del individuo. Finalmente, un apartado de la Guía de formulación cultural está dedicado a considerar cómo pueden influir las formas en que los individuos y los clínicos están situados socialmente y se perciben mutuamente, en términos de clases sociales, en el proceso de evaluación. Las experiencias de racismo y discriminación en la sociedad en general pueden dificultar que se genere confianza y seguridad en el encuentro clínico diagnóstico. Referencia: DSM-5-TR, Guía de formulación cultural (pp. 861-862).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿En qué tipo de entorno clínico se supone que se debe usar la Entrevista de formulación cultural (EFC)?', '["Cualquier entorno.", "Clínica ambulatoria.", "Departamento de urgencias.", "Hospitalización."]', 0, 'El apartado "Formulación cultural" presenta una guía de evaluación cultural sistemática centrada en la persona que está diseñada para ser utilizada por cualquier clínico que preste servicios a cualquier individuo en cualquier entorno asistencial. Este apartado también incluye un protocolo de entrevista, la "Entrevista de formulación cultural", que operacionaliza estos componentes. Las presentaciones de síntomas, las interpretaciones de la enfermedad o el apuro que precipitan la atención y las expectativas de búsqueda de ayuda siempre están influenciadas por los antecedentes culturales y los contextos socioculturales de los individuos. Una evaluación cultural centrada en la persona puede ayudar a mejorar la atención de cada individuo, independientemente de su origen. La formulación cultural puede ser especialmente útil para las personas que se ven afectadas por disparidades en la atención sanitaria, motivadas por la desventaja y la discriminación sistémicas. Referencia: DSM-5-TR, Cultura y diagnóstico psiquiátrico / Introducción al capítulo (p. 859).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿En cuál de las siguientes situaciones clínicas se supone que la Entrevista de formulación cultural (EFC) debe ser útil?', '["El clínico y el paciente comparten un sistema de creencias sobre la naturaleza del problema y el enfoque terapéutico apropiado.", "El paciente presenta un complejo de síntomas que es angustioso pero no se ajusta a ningún diagnóstico del DSM-5-TR.", "El clínico y el paciente hablan diferentes idiomas.", "Al clínico le resulta difícil identificar el código correcto del diagnóstico clínico principal del paciente."]', 1, 'La EFC se puede utilizar en la evaluación inicial de los individuos de cualquier edad, en cualquier entorno clínico, independientemente del trasfondo cultural del individuo o del clínico. Los individuos y los clínicos que parecen compartir el mismo trasfondo cultural pueden, sin embargo, diferir en aspectos relevantes para la atención. La EFC puede usarse en su totalidad o se pueden incorporar sus componentes a la evaluación clínica según proceda. La EFC puede ser especialmente útil en la práctica clínica en los casos siguientes: dificultad de la evaluación diagnóstica debido a diferencias significativas entre los trasfondos culturales, religiosos o socioeconómicos del clínico y del individuo; incertidumbre respecto a la correspondencia entre los síntomas culturalmente distintivos y los criterios diagnósticos; dificultad para juzgar la gravedad de la enfermedad o la discapacidad; puntos de vista divergentes sobre los síntomas o las expectativas de atención basadas en la experiencia previa con otros sistemas culturales de curación y atención sanitaria; desacuerdo entre el individuo y el clínico sobre el curso de la atención; desconfianza potencial hacia los servicios e instituciones convencionales por parte de individuos con antecedentes colectivos de trauma y opresión, y limitado compromiso y adherencia con respecto al tratamiento por parte del individuo. Cuando el clínico y el paciente comparten el mismo sistema de creencias acerca de la naturaleza del problema y el enfoque terapéutico apropiado, puede haber menos necesidad de administrar la EFC, pero no porque los factores culturales no estén jugando algún papel, sino porque el clínico y el paciente están incorporando estos factores en sus suposiciones culturales compartidas y, por lo tanto, ya están abordando estos problemas incluso sin un cuestionario formal. Obsérvese que esta respuesta subraya el sistema de creencias compartido y el enfoque acordado del problema actual; sin embargo, no se debe suponer un sistema de creencias compartido solo porque el paciente pertenezca al mismo grupo étnico o religioso. Referencia: DSM-5-TR, Entrevista de formulación cultural (EFC) (pp. 862-863).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿Cuál de las siguientes opciones distingue con precisión el concepto de raza del de etnia?', '["La raza se basa en atributos físicos superficiales, mientras que la etnia se basa en la identidad grupal culturalmente construida.", "La raza es un constructo biológico, mientras que la etnia es un constructo social.", "La raza generalmente es específica de una región, mientras que la etnia es un constructo generalmente llevado a través de las sociedades.", "La raza tiende a ser autoasignada por el grupo identificado, mientras que la etnia es atribuida por los de fuera."]', 0, 'La raza es un constructo social, no biológico, que divide a la humanidad en grupos sobre la base de una serie de rasgos físicos superficiales como el color de la piel, que se han visto falsamente como indicadores de atributos y capacidades que se supone son inherentes a cada grupo. Las categorías y constructos raciales han variado a lo largo de la historia y entre las sociedades, y se han utilizado para justificar sistemas de opresión, esclavitud y genocidio. El constructo de raza es importante para la psiquiatría porque puede llevar a ideologías raciales, racismo, discriminación, opresión social y exclusión, que tienen fuertes efectos negativos en la salud mental. Hay evidencia de que el racismo puede exacerbar muchos trastornos psiquiátricos, contribuyendo a un mal resultado, y que los sesgos raciales pueden afectar a la evaluación diagnóstica. La etnia es una identidad grupal construida culturalmente que se utiliza para definir pueblos y comunidades. Puede tener sus raíces en una historia, ascendencia, geografía, idioma, religión u otras características en común compartidas por un grupo, que distinguen a ese grupo de los demás. La etnia puede ser autoasignada o estar atribuida por los de fuera. La creciente movilidad, los matrimonios mixtos y la mezcla de grupos culturales han definido nuevas identidades étnicas mixtas, múltiples o híbridas. Estos procesos también pueden llevar a la dilución de la identificación étnica. Referencia: DSM-5-TR, Cultura y diagnóstico psiquiátrico / Términos clave (pp. 859-860).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', 'En el DSM-5-TR, ¿qué se incluye en los conceptos culturales de malestar?', '["Nombres alternativos culturalmente específicos para los trastornos psiquiátricos del DSM-5-TR.", "Subtipos culturalmente específicos de trastornos psiquiátricos.", "Explicaciones de los síntomas influenciadas culturalmente.", "Una explicación unificadora de la expresión variable de los síntomas en los trastornos psiquiátricos."]', 2, 'Los conceptos culturales de malestar describen las formas en que los individuos expresan, informan e interpretan las experiencias de enfermedad y malestar. Los conceptos culturales de malestar incluyen expresiones, explicaciones o causas percibidas y síndromes. Los síntomas se expresan y comunican utilizando las expresiones o modismos culturales de malestar: comportamientos o términos lingüísticos, metáforas, frases o formas de hablar sobre los síntomas, los problemas o el sufrimiento que utilizan habitualmente los individuos de trasfondos culturales similares para transmitir una amplia gama de preocupaciones. Dichas expresiones pueden usarse para referirse a un amplio espectro de formas de malestar y pueden no indicar un trastorno psiquiátrico. Expresiones contemporáneas comunes en Estados Unidos son quemado, estresado, colapso nervioso y estar depre, en el sentido de experimentar insatisfacción o desaliento que no cumple los criterios de ningún trastorno psiquiátrico. Las explicaciones y los síndromes específicos de cada cultura también son comunes y están ampliamente distribuidos entre las poblaciones. Este apartado también proporciona algunos ejemplos ilustrativos de modismos, explicaciones y síndromes de diversas regiones geográficas. Los ejemplos se eligieron porque han sido bien estudiados, y su desconocimiento por parte de muchos clínicos estadounidenses resalta la especificidad de estas expresiones verbales y conductuales, así como de su función comunicativa. Referencia: DSM-5-TR, Cultura y diagnóstico psiquiátrico / Introducción al capítulo (p. 859).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿Cuál de las siguientes opciones define mejor las expresiones culturales de malestar?', '["Agrupaciones idiosincrásicas de síntomas restringidas a regiones geográficas específicas.", "Formas colectivas y compartidas de experimentar y discutir las preocupaciones.", "Causas percibidas o modelos explicativos con respecto al malestar.", "Términos culturalmente específicos que corresponden a diagnósticos específicos del DSM-5-TR."]', 1, 'El término conceptos culturales de malestar se refiere a las formas en que los individuos experimentan, comprenden y comunican el sufrimiento, los problemas de comportamiento o los pensamientos y emociones perturbadores. Se pueden distinguir tres tipos principales de conceptos culturales de malestar. Las expresiones culturales de malestar son formas de expresar la angustia que pueden no involucrar síntomas o síndromes específicos, pero que proporcionan formas colectivas y compartidas de experimentar y hablar sobre las preocupaciones personales o sociales. Por ejemplo, hablar cotidianamente sobre "nervios" o "depresión" puede referirse a formas muy variadas de sufrimiento sin incluirlas en ningún conjunto discreto de síntomas, síndrome o trastorno. Las explicaciones culturales o causas percibidas son etiquetas, atribuciones o características de un modelo explicativo que indican un significado o etiología culturalmente reconocidos para los síntomas, la enfermedad o el malestar. Los síndromes culturales son agrupaciones de síntomas y atribuciones que tienden a concurrir entre los individuos de determinados grupos culturales, comunidades o contextos y que están reconocidos localmente como patrones coherentes de experiencia. Estos tres conceptos culturales de angustia—expresiones culturales de malestar, explicaciones culturales y síndromes culturales—son más relevantes para la práctica clínica que la antigua formulación de síndrome ligado a la cultura. Específicamente, el término síndrome ligado a la cultura ignora el hecho de que las diferencias culturales clínicamente importantes a menudo involucran explicaciones o experiencias de angustia, en lugar de configuraciones de síntomas culturalmente distintivas. Además, el término ligado a la cultura hace excesivo hincapié en el grado en que los conceptos culturales de malestar se caracterizan por experiencias altamente idiosincrásicas que están restringidas a regiones geográficas específicas. Referencia: DSM-5-TR, Conceptos culturales de malestar / Relevancia para la evaluación diagnóstica (pp. 871-873).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿Cuál de las siguientes opciones caracteriza con precisión el ataque de nervios?', '["Gran alteración emocional que cursa con ansiedad aguda, ira y dolor, y llanto o gritos y alaridos incontrolables.", "Ansiedad intensa en y evitación de situaciones interpersonales por miedo a no dar la talla o a la ofensa.", "Un suceso aterrador percibido como causante de que el alma abandone el cuerpo, resultando en enfermedad o tristeza.", "Un estado general de vulnerabilidad a los sucesos estresantes de la vida."]', 0, 'El ataque de nervios es un síndrome encontrado en contextos culturales latinos caracterizado por síntomas de gran alteración emocional, incluyendo ansiedad aguda, ira o dolor; gritos y alaridos incontrolables; ataques de llanto; temblores; calor en el pecho que sube a la cabeza, y volverse verbal y físicamente agresivo. Los ataques ocurren con frecuencia como resultado directo de un suceso estresante relacionado con la familia, como noticias de la muerte de un pariente cercano, conflictos con la pareja o los hijos, o presenciar un accidente que involucre a un miembro de la familia. El taijin kyofusho ("trastorno de miedo interpersonal") es un síndrome encontrado en contextos culturales japoneses que se caracteriza por ansiedad y evitación de situaciones interpersonales debido al pensamiento, sentimiento o convicción de que la apariencia y las acciones del individuo en las interacciones sociales son torpes u ofensivas para los demás. El susto es una entidad que, en algunos contextos culturales latinos, se atribuye a un suceso aterrador que hace que el alma abandone el cuerpo y produce infelicidad y enfermedad, así como dificultades para desempeñar los principales roles sociales. Nervios se refiere a un estado general de vulnerabilidad ante las experiencias estresantes de la vida y las circunstancias de vida difíciles. Referencia: DSM-5-TR, Ejemplos de conceptos culturales de malestar (pp. 873-879).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿Cómo se denomina el concepto cultural de malestar, acuñado en el sur de Asia, que implica el miedo de un individuo a que diversos síntomas puedan ser atribuidos a la pérdida de semen?', '["Kufungisisa.", "Síndrome del dhat.", "Maladi dyab.", "Shenjing shuairuo."]', 1, 'El síndrome del dhat es un término que se acuñó en el sur de Asia hace poco más de medio siglo para explicar las presentaciones clínicas de jóvenes que atribuían sus diversos síntomas a la pérdida de semen. A pesar del nombre, no es un síndrome discreto, sino más bien una explicación cultural de malestar que usan individuos que refieren diversos síntomas, como ansiedad, fatiga, debilidad, pérdida de peso, disfunción eréctil, otras múltiples quejas somáticas y estado de ánimo deprimido. La característica principal es la ansiedad y la angustia por la pérdida del dhat en ausencia de cualquier disfunción fisiológica identificable. Los individuos identificaban el dhat como una secreción blanca que se notaba al defecar u orinar. Las ideas sobre esta sustancia están relacionadas con el concepto de dhatu (semen), descrito en el sistema de medicina hindú llamado Ayurveda como uno de los siete fluidos corporales esenciales cuyo equilibrio es necesario para mantener la salud. Aunque el síndrome del dhat se formuló como una categoría clínica para ayudar a informar la práctica clínica local, se ha demostrado que las ideas relacionadas con los efectos nocivos de la pérdida de semen están generalizadas entre la población general, lo que sugiere una disposición cultural a explicar los problemas de salud y los síntomas haciendo referencia a los conceptos relacionados con el dhat. Referencia: DSM-5-TR, Ejemplos de conceptos culturales de malestar / Síndrome del dhat (pp. 874-875).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿Qué representa el término kufungisisa?', '["Expresión de malestar.", "Explicación cultural.", "Ambos.", "Ninguno."]', 2, 'Kufungisisa ("pensar demasiado") es una expresión de malestar y una explicación cultural entre los shona de Zimbabue. Como explicación, se considera causante de ansiedad, depresión y problemas somáticos (por ejemplo, "Me duele el corazón porque pienso demasiado"). Como expresión de angustia psicosocial es indicativa de dificultades interpersonales y sociales (por ejemplo, problemas maritales, no tener dinero para cuidar a los niños, desempleo). Kufungisisa implica rumiar pensamientos perturbadores, particularmente preocupaciones, como inquietud por enfermedades físicas crónicas como los trastornos relacionados con el VIH. Kufungisisa se asocia a diversas psicopatologías, incluyendo síntomas de ansiedad, preocupación excesiva, ataques de pánico, síntomas depresivos, irritabilidad y trastorno de estrés postraumático. Referencia: DSM-5-TR, Ejemplos de conceptos culturales de malestar / Kufungisisa (pp. 876).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿Con qué trastorno psiquiátrico se asocia el hikikomori?', '["Trastorno obsesivo-compulsivo.", "Trastorno por consumo de alcohol.", "Esquizofrenia.", "Trastorno de déficit de atención/hiperactividad."]', 2, 'El hikikomori (un término japonés compuesto por las palabras hiku [retirarse] y moru [aislarse]) es un síndrome de retiro social prolongado y grave observado en Japón, que puede resultar en el cese completo de las interacciones en persona con los demás. La imagen típica del hikikomori es un adolescente o joven adulto de sexo masculino que no sale de su habitación en la casa de sus padres y no tiene interacciones sociales en persona. Este comportamiento puede ser inicialmente egosintónico, pero generalmente produce malestar con el tiempo; a menudo se asocia a un uso de Internet muy intensivo y a intercambios sociales virtuales. Otras características son ausencia de interés o disposición para asistir a la escuela o trabajar. La guía de 2010 del Ministerio de Salud, Trabajo y Bienestar de Japón requiere 6 meses de retiro social para el diagnóstico de hikikomori. El retiro social extremo visto en el hikikomori puede ocurrir en el contexto de un trastorno establecido del DSM-5-TR ("secundario") o puede manifestarse independientemente ("primario"). El hikikomori se asocia al trastorno de ansiedad social, al trastorno depresivo mayor, al trastorno de ansiedad generalizada, al trastorno de estrés postraumático, al trastorno del espectro autista, al trastorno de la personalidad esquizoide, al trastorno de la personalidad evitativa y a la esquizofrenia u otro trastorno psicótico. La afección también puede estar asociada con el trastorno de juego por Internet y, en los adolescentes, con el rechazo escolar. Referencia: DSM-5-TR, Ejemplos de conceptos culturales de malestar / Hikikomori (p. 875).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿Cuál de las siguientes opciones describe con precisión el khyál cap?', '["Retiro social que implica el cese completo de la interacción en persona con los demás.", "Enfermedad física o mental, angustia o disfunción causada por la mala voluntad de otra persona hacia el que sufre.", "Una vulnerabilidad general a los sucesos estresantes de la vida y las experiencias difíciles.", "Un inicio repentino de mareos, palpitaciones, falta de aliento, ansiedad o excitación autonómica."]', 3, 'Los "ataques de khyál" (khyál cap), o "ataques de viento", es un síndrome encontrado en contextos culturales camboyanos. Los síntomas comunes incluyen los propios de los ataques de pánico, como mareos, palpitaciones, falta de aliento y extremidades frías, además de otros síntomas de ansiedad y excitación autonómica (por ejemplo, tinnitus, dolor de cuello). Los ataques de khyál incluyen cogniciones catastróficas centradas en la preocupación de que el khyál (una sustancia similar al viento) pueda subir en el cuerpo, junto con la sangre, y causar una serie de efectos graves (por ejemplo, comprimir los pulmones para causar falta de aliento y asfixia; entrar en el cráneo para causar tinnitus, mareos, visión borrosa y un síncope fatal). Los ataques de khyál pueden ocurrir sin previo aviso, pero a menudo son provocados por desencadenantes como pensamientos preocupantes, levantarse (es decir, ortostasis), olores específicos con asociaciones negativas y señales agorafóbicas como ir a espacios abarrotados o viajar en coche. Los ataques de khyál generalmente cumplen los criterios del ataque de pánico y pueden dar forma a la experiencia de otros trastornos de ansiedad y trastornos relacionados con los traumas y los factores de estrés. Los ataques de khyál pueden asociarse a una discapacidad considerable. Referencia: DSM-5-TR, Ejemplos de conceptos culturales de malestar / Khyál cap (pp. 875-876).'),
('DSM-5-TR', 'Cultura y diagnóstico psiquiátrico (Sección III del DSM-5-TR)', '¿Cómo se relacionan los conceptos culturales de malestar con la nosología del DSM-5-TR?', '["Correspondencia uno a uno.", "Proporcionan criterios diagnósticos específicos.", "Correspondencia estática a lo largo del tiempo y la geografía.", "Pueden aplicarse a múltiples trastornos."]', 3, 'Los conceptos culturales de malestar surgen de sistemas diagnósticos locales, populares o profesionales, para el malestar mental y emocional, y también pueden reflejar la influencia de los conceptos biomédicos. Los conceptos culturales de malestar tienen cuatro características clave en relación con la nosología del DSM-5-TR: 1) rara vez existe una correspondencia unívoca entre un concepto cultural de angustia y una entidad diagnóstica del DSM; es más probable que la correspondencia sea de uno a muchos en cualquier dirección; 2) los conceptos culturales de malestar pueden aplicarse a un amplio rango de gravedad de los síntomas y la funcionalidad, incluyendo presentaciones que no cumplen los criterios del DSM-5-TR para ningún trastorno mental; 3) en el uso común, el mismo término cultural denota frecuentemente más de un tipo de concepto cultural de malestar (por ejemplo, "depresión" puede usarse para describir un síndrome, una expresión de malestar o una explicación o causa percibida), y 4) al igual que la cultura y el propio DSM, los conceptos culturales de malestar pueden cambiar con el tiempo en respuesta a influencias locales y globales. Referencia: DSM-5-TR, Conceptos culturales de malestar / Relevancia para la evaluación diagnóstica (pp. 871-872).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', '¿Cuál de los siguientes términos describe mejor el enfoque diagnóstico propuesto en el modelo alternativo del DSM-5 para los trastornos de la personalidad?', '["Categórico.", "Dimensional.", "Híbrido.", "Evolutivo."]', 2, 'Propuesto como alternativa a la clasificación existente de los trastornos de la personalidad de la Sección II, este modelo híbrido dimensional-categórico de la Sección III define el trastorno de la personalidad en términos de deterioro del funcionamiento de la personalidad y rasgos de personalidad patológicos (la opción C es correcta; las opciones A y B son incorrectas). En algunas ocasiones, lo que parece ser un trastorno de la personalidad puede explicarse mejor por otro trastorno mental, los efectos fisiológicos de una sustancia u otra afección médica, o una etapa normal del desarrollo (la opción D es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (p. 881); Criterios E, F y G: explicaciones alternativas de la patología de la personalidad (diagnóstico diferencial) (p. 883).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', 'En el modelo alternativo del DSM-5 para los trastornos de la personalidad, los trastornos de la personalidad se caracterizan por rasgos de personalidad patológicos y ¿cuál de los siguientes?', '["Deterioro del funcionamiento de la personalidad.", "Deterioro de la identidad.", "Deterioro de la autodirección.", "Deterioro de la empatía."]', 0, 'En el modelo alternativo del DSM-5 para los trastornos de la personalidad, los trastornos de la personalidad se caracterizan por deterioro del funcionamiento de la personalidad y rasgos de personalidad patológicos (la opción A es correcta). Un diagnóstico de trastorno de personalidad requiere dos determinaciones: 1) una evaluación del nivel de deterioro del funcionamiento de la personalidad, que se necesita para el Criterio A, y 2) una evaluación de los rasgos de personalidad patológicos, que se requiere para el Criterio B. La identidad, la autodirección y la empatía se consideran todos ellos elementos del funcionamiento de la personalidad; el funcionamiento del yo implica la identidad y la autodirección; el funcionamiento interpersonal implica la empatía y la intimidad. Referencia: DSM-5-TR, Introducción al capítulo (p. 881); Criterios generales del trastorno de la personalidad (p. 881); Criterio A: nivel de funcionamiento de la personalidad (p. 882); Tabla 1 (p. 883).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', '¿Cuál de los siguientes es un dominio del modelo alternativo del DSM-5 para los trastornos de la personalidad?', '["Labilidad emocional.", "Evitación de la intimidad.", "Desinhibición.", "Desregulación cognitiva y perceptiva."]', 2, 'Los rasgos de personalidad patológicos se organizan en cinco amplios dominios: afectividad negativa, desapego, antagonismo, desinhibición y psicoticismo (la opción C es correcta). La labilidad emocional se considera una faceta de la afectividad negativa (la opción A es incorrecta). La evitación de la intimidad se considera una faceta del desapego (la opción B es incorrecta). La desregulación cognitiva y perceptiva se considera una faceta del psicoticismo (la opción D es incorrecta). Referencia: DSM-5-TR, Criterio B: rasgos de personalidad patológicos (p. 882); Tabla 3 (Definiciones de los dominios y facetas de los rasgos de los trastornos de la personalidad del DSM-5) (pp. 899-901).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', 'Además de la afectividad negativa, ¿cuál de los siguientes dominios de rasgos desadaptativos está más asociado con el trastorno de la personalidad evitativa?', '["Desapego.", "Antagonismo.", "Desinhibición.", "Psicoticismo."]', 0, 'Las características típicas del trastorno de personalidad evitativa son la evitación de situaciones sociales y la inhibición en las relaciones interpersonales relacionadas con sentimientos de ineptitud e insuficiencia, preocupación ansiosa por la evaluación negativa y el rechazo, y miedos al ridículo o la vergiienza. Las dificultades características se manifiestan en la identidad, la autodirección, la empatía y/o la intimidad, junto con rasgos maladaptativos específicos en los dominios de la afectividad negativa y el desapego (la opción A es correcta). Las dificultades características en otros trastornos de personalidad se manifiestan en la identidad, la autodirección, la empatía y/o la intimidad, junto con rasgos maladaptativos específicos en el dominio de la afectividad negativa (trastorno de personalidad límite), antagonismo (trastornos de personalidad antisocial, límite y narcisista), y/o desinhibición (trastornos de personalidad antisocial y límite); las opciones B y C son incorrectas. Las dificultades características en el trastorno de personalidad esquizotípica incluyen rasgos maladaptativos específicos en los dominios del psicoticismo y el desapego (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de la personalidad antisocial (pp. 884-885); Trastorno de la personalidad evitativa (pp. 885-886); Trastorno de la personalidad límite (pp. 886-887); Trastorno de la personalidad esquizotípica (pp. 889-890).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', '¿Cuál de las siguientes opciones está incluida en el sistema de rasgos de personalidad de la Sección III?', '["Psicopatología de la personalidad 5 (PSY-5).", "Escala de funcionamiento de la personalidad (LPFS).", "Modelo de cinco factores de la personalidad (FFM).", "Inventario de personalidad para el DSM-5 (PID-5)."]', 2, 'El sistema de rasgos de personalidad de la Sección III incluye cinco amplios dominios de variación de rasgos—afectividad negativa (vs. estabilidad emocional), desapego (vs. extraversión), antagonismo (vs. amabilidad), desinhibición (vs. responsabilidad) y psicoticismo (vs. lucidez) — - que comprenden 25 facetas específicas. Estos cinco amplios dominios son variantes desadaptativas de los cinco dominios del modelo de la personalidad ampliamente validado y replicado, conocido como el modelo de los cinco factores de la personalidad (FFM) o "Big Five" (la opción C es correcta), y también son similares a los dominios de Psicopatología de la personalidad 5 (PSY-5; la opción A es incorrecta). El nivel específico de deterioro del funcionamiento de la personalidad y los rasgos de personalidad patológicos que caracterizan a la personalidad del individuo pueden especificarse mediante el trastorno de la personalidad especificado por rasgos (TP-ER), utilizando la Escala de funcionamiento de la personalidad (LPFS) y la taxonomía de rasgos patológicos. La LPFS también puede usarse como indicador global del funcionamiento de la personalidad sin especificar un diagnóstico de trastorno de la personalidad o en caso de que el deterioro de la personalidad esté por debajo del umbral del diagnóstico de trastorno (la opción B es incorrecta). El modelo de rasgos de personalidad está operacionalizado en el Inventario de personalidad del DSM-5 (PID-5), que puede ser completado en su forma autocumplimentable por los propios pacientes y en su forma para informantes por aquellos que conocen bien al paciente (la opción D es incorrecta). Referencia: DSM-5-TR, El modelo de rasgos de personalidad (p. 893); Diagnóstico de trastorno de la personalidad (p. 891); Evaluación del nivel de funcionamiento de la personalidad (p. 892); Evaluación del modelo de rasgos de personalidad de la Sección III del DSM-5 (p. 894).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', 'Las perturbaciones del yo y del funcionamiento interpersonal constituyen el núcleo de la psicopatología de la personalidad, y en el modelo diagnóstico alternativo del DSM-5-TR para los trastornos de la personalidad se evalúan en un continuo. ¿Cuál de las siguientes es una característica del funcionamiento saludable del yo?', '["Comprensión y apreciación de las experiencias y motivaciones de los demás.", "Variabilidad de la autoestima.", "Fluctuación de los límites entre el yo y los demás.", "Experiencia de uno mismo como único."]', 3, 'Los elementos del funcionamiento saludable del yo incluyen la identidad (experiencia de uno mismo como único, con límites claros entre el yo y los demás [la opción D es correcta y la opción C es incorrecta]; estabilidad de la autoestima y precisión de la autoevaluación [la opción B es incorrecta], capacidad y habilidad de regular toda una serie de experiencias emocionales) y la autodirección (búsqueda de metas a corto plazo y para la vida coherentes y significativas; utilización de estándares internos de comportamiento constructivos y prosociales; y capacidad para reflexionar de manera productiva sobre uno mismo). Los elementos del funcionamiento interpersonal saludable incluyen la empatía (comprensión y apreciación de las experiencias y motivaciones de los demás [la opción A es incorrecta], tolerancia de perspectivas diferentes y comprensión de los efectos del propio comportamiento sobre los demás) y la intimidad (profundidad y duración de la conexión con los demás, deseo y capacidad de cercanía y reciprocidad del respeto, reflejado en el comportamiento interpersonal). Referencia: DSM-5-TR, Criterio A: nivel de funcionamiento de la personalidad (p. 882); Tabla 1 (Elementos del funcionamiento de la personalidad) (p. 883).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', '¿Cuál de los siguientes es un criterio general del trastorno de la personalidad en el modelo alternativo del DSM-5-TR para los trastornos de la personalidad?', '["El individuo experimenta un deterioro leve en el funcionamiento de la personalidad (yo/interpersonal).", "El individuo demuestra dos o más rasgos de personalidad patológicos.", "Los deterioros del funcionamiento de la personalidad y la expresión de los rasgos de personalidad del individuo pueden fluctuar con el tiempo.", "Los deterioros del funcionamiento de la personalidad y la expresión de los rasgos de personalidad del individuo no se explican mejor por otro trastorno mental."]', 3, 'En el modelo alternativo del D5SM-5 para los trastornos de la personalidad, las características esenciales de un trastorno de la personalidad son las siguientes: deterioro moderado o mayor del funcionamiento de la personalidad (yo/interpersonal) (la opción A es incorrecta); uno o más rasgos de personalidad patológicos (la opción B es incorrecta); los deterioros del funcionamiento de la personalidad y la expresión de los rasgos de personalidad del individuo son relativamente inflexibles y generalizados en una amplia gama de situaciones personales y sociales; los deterioros del funcionamiento de la personalidad y la expresión de los rasgos de personalidad del individuo son relativamente estables en el tiempo, con inicios que pueden remontarse al menos a la adolescencia o la juventud (la opción C es incorrecta); los deterioros del funcionamiento de la personalidad y la expresión de los rasgos de personalidad del individuo no se explican mejor por otro trastorno mental (la opción D es correcta); los deterioros del funcionamiento de la personalidad y la expresión de los rasgos de personalidad del individuo no se atribuyen únicamente a los efectos fisiológicos de una sustancia o a otra afección médica (por ejemplo, un traumatismo craneoencefálico grave), y los deterioros del funcionamiento de la personalidad y la expresión de los rasgos de personalidad del individuo no se entienden mejor como normales para su etapa de desarrollo o entorno sociocultural. Referencia: DSM-5-TR, Criterios generales del trastorno de la personalidad (pp. 881-882).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', 'Para cumplirlos criterios diagnósticos propuestos para el trastorno de la personalidad antisocial en el modelo alternativo del DSM-5 para los trastornos de la personalidad, ¿en cuál de los siguientes dominios un individuo debe tener rasgos de personalidad desadaptativos?', '["Afectividad negativa.", "Desapego.", "Antagonismo.", "Psicoticismo."]', 2, 'En el trastorno de la personalidad antisocial, las dificultades características son evidentes en la identidad, la autodirección, la empatía y/o la intimidad, junto con rasgos desadaptativos específicos en los dominios de antagonismo y desinhibición (la opción C es correcta). En el trastorno de la personalidad evitativa y el trastorno de la personalidad obsesivo-compulsiva, las dificultades características son evidentes en la identidad, la autodirección, la empatía y/o la intimidad, junto con rasgos desadaptativos específicos en los dominios de afectividad negativa y desapego (las opciones A y B son incorrectas). En el trastorno de la personalidad límite, las dificultades características son evidentes en la identidad, la autodirección, la empatía y /o la intimidad, junto con rasgos desadaptativos específicos en los dominios de afectividad negativa y también de antagonismo y/o desinhibición (la opción A es incorrecta). En el trastorno de la personalidad esquizotípica, las dificultades características son evidentes en la identidad, la autodirección, la empatía y/o la intimidad, junto con rasgos desadaptativos específicos en los dominios de psicoticismo y desapego (las opciones B y D son incorrectas). Referencia: DSM-5-TR, Trastorno de la personalidad antisocial (pp. 884-885); Trastorno de la personalidad evitativa (pp. 885-886); Trastorno de la personalidad límite (pp. 886-887); Trastorno de la personalidad obsesivo-compulsiva (pp. 888-889); Trastorno de la personalidad esquizotípica (pp. 889-890).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', '¿Cuál de las siguientes afirmaciones caracteriza mejor la relación entre la gravedad de la disfunción de la personalidad, según se califica en la Escala del nivel de funcionamiento de la personalidad (LPFS), y la presencia de un trastorno de la personalidad?', '["Se requiere un nivel moderado de deterioro del funcionamiento de la personalidad para el diagnóstico de un trastorno de la personalidad.", "El deterioro del funcionamiento de la personalidad no está relacionado con la presencia de un trastorno de la personalidad.", "La gravedad del deterioro del funcionamiento de la personalidad no está relacionada con el número de trastornos de la personalidad.", "La gravedad del deterioro del funcionamiento de la personalidad no está relacionada con la gravedad del trastorno de la personalidad."]', 0, 'En la LPFS, el deterioro del funcionamiento de la personalidad predice la presencia de un trastorno de la personalidad (la opción B es incorrecta), y la gravedad del deterioro predice si un individuo tiene más de un trastorno de la personalidad o uno de los trastornos de la personalidad típicamente más graves (las opciones C y D son incorrectas). Se requiere un nivel moderado de deterioro del funcionamiento de la personalidad para el diagnóstico de un trastorno de la personalidad (la opción A es correcta). Este umbral se basa en la evidencia empírica, que indica que el nivel moderado de deterioro maximiza la capacidad de los clínicos para identificar de manera precisa y eficiente la patología del trastorno de la personalidad. Referencia: DSM-5-TR, Criterio A: nivel de funcionamiento de la personalidad (p. 882).'),
('DSM-5-TR', 'Modelo alternativo del DSM-5 para los trastornos de la personalidad (Sección III del DSM-5-TR)', '¿Cuál de las siguientes afirmaciones sobre la Escala del nivel de funcionamiento de la personalidad (LPFS) es más precisa?', '["Se necesita una calificación de deterioro moderado o mayor para el diagnóstico de un trastorno de la personalidad.", "Se necesita una calificación de deterioro leve para el diagnóstico de un trastorno de la personalidad.", "La LPFS solo puede utilizarse con la especificación de un diagnóstico de trastorno de la personalidad.", "Para utilizar la LPFS, el clínico selecciona el nivel que capta el grado más bajo de deterioro en la vida de la persona."]', 0, 'Para utilizar la LPFS, el clínico selecciona el nivel que refleja de manera más precisa el grado de deterioro actual y general del funcionamiento de la personalidad del individuo (la opción D es incorrecta). La calificación es necesaria para el diagnóstico de un trastorno de la personalidad (deterioro moderado o mayor) y puede usarse para especificar la gravedad del deterioro presente en un individuo con cualquier trastorno de la personalidad en un momento dado (la opción A es correcta y la opción B es incorrecta). La LPFS también puede usarse como indicador global del funcionamiento de la personalidad sin especificar un diagnóstico de trastorno de la personalidad o en caso de que el deterioro de la personalidad no alcance el umbral del diagnóstico de trastorno (la opción C es incorrecta). Referencia: DSM-5-TR, Evaluación del nivel de funcionamiento de la personalidad (p. 892).')
) as v(curso, tema, pregunta, opciones, correcta, explicacion)
where not exists (
  select 1 from public.preguntas p
  where p.curso = v.curso and p.pregunta = v.pregunta and p.opciones = v.opciones::jsonb
);
